    [Fact]
    public void FallbackFrontierRepairAuthority_ForwardsCoordinatorIdentityAndFullTuple()
    {
        var predecessorAuthorityId = new FileTransferAuthorityId("fta2-fallback-frontier-predecessor");
        var (state, repairDecision) = AuthorizeFallbackFrontierRepair(predecessorAuthorityId);

        Assert.True(FileTransferCoordinator.TryIssueFallbackFrontierRepairAuthority(
            repairDecision,
            new FallbackFrontierRepairAuthorityRequest(
                "fallback-frontier:12:3:frng-test",
                "frng-test",
                FrontierChunkIndex: 12,
                DurableReceivedHighestChunkIndex: 18,
                RangeCount: 2,
                RequestedChunkCount: 3,
                FallbackFrontierRepairSourceKind.PeerRequest,
                ProtocolRepairRequestId: "v6-frontier:9:12:1",
                RequestCorrelationId: "frq-test",
                CheckpointRequestId: "(none)",
                Priority: "frontier",
                RecoveryMode: "frontier_repair_only",
                DecisionReason: "fallback_frontier_request_received"),
            out var authority,
            out var rejectionReason));

        Assert.Equal("accepted", rejectionReason);
        Assert.NotNull(authority);
        var issuedAuthority = authority!.Value;
        Assert.Equal(repairDecision.AuthorityId, issuedAuthority.AuthorityId);
        Assert.Equal(predecessorAuthorityId, issuedAuthority.PredecessorAuthorityId);
        Assert.Equal(FileTransferRoute.PostTunaFallbackV6, issuedAuthority.Route);
        Assert.Equal(FileTransferProtocol.ProtocolVersionV6, issuedAuthority.ProtocolVersion);
        Assert.Equal(FileTransferTransportKind.RegularNkn, issuedAuthority.TargetTransport);
        Assert.Equal(repairDecision.RoutePublicationToken!.Value.PublicationGeneration, issuedAuthority.RoutePublicationGeneration);
        Assert.Equal("frng-test", issuedAuthority.RangeFingerprint);
        Assert.Equal("frq-test", issuedAuthority.RequestCorrelationId);
        Assert.True(FileTransferCoordinator.IsRepairReplayDecisionCurrent(state, repairDecision, out var currentReason));
        Assert.Equal("accepted", currentReason);
    }

    [Fact]
    public void FallbackFrontierRepairAuthority_RejectsNonFallbackAndIncompleteShapes()
    {
        var (_, repairDecision) = AuthorizeFallbackFrontierRepair();
        var validRequest = new FallbackFrontierRepairAuthorityRequest(
            "fallback-frontier:12:1:frng-test",
            "frng-test",
            FrontierChunkIndex: 12,
            DurableReceivedHighestChunkIndex: 11,
            RangeCount: 1,
            RequestedChunkCount: 1,
            FallbackFrontierRepairSourceKind.PeerRequest,
            ProtocolRepairRequestId: "v6-frontier:9:12:1",
            RequestCorrelationId: "frq-test",
            CheckpointRequestId: "(none)",
            Priority: "frontier",
            RecoveryMode: "frontier_repair_only",
            DecisionReason: "fallback_frontier_request_received");

        Assert.False(FileTransferCoordinator.TryIssueFallbackFrontierRepairAuthority(
            repairDecision with { RepairKind = RepairReplayKind.V6Repair },
            validRequest,
            out _,
            out var repairKindReason));
        Assert.Equal("fallback_frontier_repair_route_invariant_mismatch", repairKindReason);

        Assert.False(FileTransferCoordinator.TryIssueFallbackFrontierRepairAuthority(
            repairDecision with { CurrentProtocolVersion = FileTransferProtocol.ProtocolVersionV4 },
            validRequest,
            out _,
            out var protocolReason));
        Assert.Equal("repair_route_publication_authority_mismatch", protocolReason);

        Assert.False(FileTransferCoordinator.TryIssueFallbackFrontierRepairAuthority(
            repairDecision with { CurrentRuntimeGeneration = repairDecision.CurrentRuntimeGeneration + 1 },
            validRequest,
            out _,
            out var runtimeGenerationReason));
        Assert.Equal("repair_route_publication_authority_mismatch", runtimeGenerationReason);

        Assert.False(FileTransferCoordinator.TryIssueFallbackFrontierRepairAuthority(
            repairDecision with { CurrentTerminalGeneration = repairDecision.CurrentTerminalGeneration + 1 },
            validRequest,
            out _,
            out var terminalGenerationReason));
        Assert.Equal("repair_route_publication_authority_mismatch", terminalGenerationReason);

        var publication = repairDecision.RoutePublicationToken!.Value;
        Assert.False(FileTransferCoordinator.TryIssueFallbackFrontierRepairAuthority(
            repairDecision with
            {
                RoutePublicationToken = publication with { TargetTransport = FileTransferTransportKind.Tuna },
            },
            validRequest,
            out _,
            out var targetReason));
        Assert.Equal("fallback_frontier_repair_route_invariant_mismatch", targetReason);

        Assert.False(FileTransferCoordinator.TryIssueFallbackFrontierRepairAuthority(
            repairDecision with { RoutePublicationToken = null },
            validRequest,
            out _,
            out var publicationReason));
        Assert.Equal("route_publication_authority_missing", publicationReason);

        Assert.False(FileTransferCoordinator.TryIssueFallbackFrontierRepairAuthority(
            repairDecision,
            validRequest with { RequestCorrelationId = "" },
            out _,
            out var correlationReason));
        Assert.Equal("fallback_frontier_repair_identity_missing", correlationReason);

        Assert.False(FileTransferCoordinator.TryIssueFallbackFrontierRepairAuthority(
            repairDecision,
            validRequest with { CanonicalRepairKey = "fallback-frontier:12:2:frng-test" },
            out _,
            out var canonicalKeyReason));
        Assert.Equal("fallback_frontier_repair_identity_mismatch", canonicalKeyReason);
    }

    [Fact]
    public void RuntimeUnlockRetryDispatchAuthority_GrantsExactRegularV4ReleaseAndIsIdempotent()
    {
        var (state, request, release) = AuthorizeRegularRuntimeUnlockRetryDispatchSource();

        var granted = FileTransferCoordinator.AuthorizeRuntimeUnlockRetryDispatch(
            state,
            request,
            RuntimeUnlockRetryReleaseKind.RegularV4RepairSettlement,
            release.AuthorityId,
            release.RepairGeneration,
            FileTransferRegularV4FrontierRepairSettlementOutcome.ProgressObserved.ToString());

        Assert.True(granted.Granted);
        Assert.Equal(
            RuntimeUnlockRetryLifecycleRepairSettlementReleaseState.Available,
            FileTransferCoordinator.GetRuntimeUnlockRetryLifecycle(granted.State)
                .RepairSettlementRelease?.State);
        Assert.Equal(FileTransferRoute.FileTunaV4, granted.Contract!.Authority.TargetRoute);
        Assert.Equal(FileTransferProtocol.ProtocolVersionV4, granted.Contract.Authority.TargetProtocolVersion);
        Assert.Equal(FileTransferTransportKind.Tuna, granted.Contract.Authority.TargetTransport);
        var duplicate = FileTransferCoordinator.AuthorizeRuntimeUnlockRetryDispatch(
            granted.State,
            request,
            RuntimeUnlockRetryReleaseKind.RegularV4RepairSettlement,
            release.AuthorityId,
            release.RepairGeneration,
            FileTransferRegularV4FrontierRepairSettlementOutcome.ProgressObserved.ToString());
        Assert.True(duplicate.Granted);
        Assert.Equal(granted.Contract!.Authority, duplicate.Contract!.Authority);
        Assert.Equal("idempotent", duplicate.Reason);
        Assert.False(granted.Contract.RequestActivePredecessorSupersession);

        var flippedSupersession = FileTransferCoordinator.AuthorizeRuntimeUnlockRetryDispatch(
            granted.State,
            request with { RequestActivePredecessorSupersession = true },
            RuntimeUnlockRetryReleaseKind.RegularV4RepairSettlement,
            release.AuthorityId,
            release.RepairGeneration,
            FileTransferRegularV4FrontierRepairSettlementOutcome.ProgressObserved.ToString());
        Assert.Equal(RuntimeUnlockRetryDispatchDecisionStatus.Rejected, flippedSupersession.Status);
        Assert.Equal("retry_dispatch_attempt_identity_mismatch", flippedSupersession.Reason);
        Assert.Same(granted.State, flippedSupersession.State);
    }

    [Fact]
    [Trait("FileTransferCoordinatorSuite", "CoordinatorSnapshots")]
    [Trait("FileTransferCoordinatorSuite", "ReceiveRecoveryOperation")]
    public void FileTransferReceiveRecovery_CoordinatorAuthorsExactSnapshotBoundaries()
    {
        var fixture = CreateReceiveRecoveryOperationFixture();
        var state = fixture.State with
        {
            PersistentState = fixture.State.PersistentState with
            {
                CoordinatorInstanceId = "receive-recovery-snapshot-coordinator",
                SnapshotStateGeneration = 0,
            },
        };
        var authority = Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
            fixture.Decision.Authority);

        var issued = FileTransferCoordinator.IssueReceiveRecoveryOperation(
            state,
            authority.Observation,
            authority.BridgeRecoveryDecision.RecoveryKind,
            authority.ExecutionCommand.CheckpointRequestId);
        Assert.True(issued.Accepted, issued.Reason);
        var issueEnvelope = Assert.IsType<FileTransferCoordinatorTransitionEnvelope>(
            issued.SnapshotEnvelope);
        Assert.Equal(0, issueEnvelope.Aggregate.BeforeStateGeneration);
        Assert.Equal(1, issueEnvelope.Aggregate.AfterStateGeneration);
        var current = Assert.Single(
            issueEnvelope.Aggregate.Operations,
            operation => operation is
            {
                Family: "receive_recovery",
                OperationRole: "operation_current",
            });
        Assert.Equal("Issued", current.ReceiveRecovery?.ExecutionState);
        Assert.Equal(
            authority.Observation.CheckpointRequestId ?? "(none)",
            current.ReceiveRecovery?.SourceBoundary.CheckpointRequestId);
        Assert.Equal(
            authority.ExecutionCommand.CheckpointRequestId ?? "(none)",
            current.ReceiveRecovery?.EffectiveBoundary.CheckpointRequestId);

        var duplicate = FileTransferCoordinator.IssueReceiveRecoveryOperation(
            issued.State,
            authority.Observation,
            authority.BridgeRecoveryDecision.RecoveryKind,
            authority.ExecutionCommand.CheckpointRequestId);
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Idempotent,
            duplicate.Status);
        var duplicateEnvelope = Assert.IsType<FileTransferCoordinatorTransitionEnvelope>(
            duplicate.SnapshotEnvelope);
        Assert.Equal(1, duplicateEnvelope.Aggregate.BeforeStateGeneration);
        Assert.Equal(1, duplicateEnvelope.Aggregate.AfterStateGeneration);
        Assert.Equal("Idempotent", duplicateEnvelope.DecisionStatus);
        var duplicateReceipt = Assert.Single(
            Assert.Single(
                duplicateEnvelope.Aggregate.Operations,
                operation => operation.Family == "receive_recovery")
            .ReceiveRecovery!.Receipts);
        Assert.Equal("attempted_decision", duplicateReceipt.Stage);
        Assert.Equal("Idempotent", duplicateReceipt.ReceiptStatus);

        var rejected = FileTransferCoordinator.IssueReceiveRecoveryOperation(
            duplicate.State,
            authority.Observation with
            {
                ObservationIdentity = "competing-observation",
                ObservationGeneration =
                    authority.Observation.ObservationGeneration + 1,
            },
            authority.BridgeRecoveryDecision.RecoveryKind,
            authority.ExecutionCommand.CheckpointRequestId);
        Assert.False(rejected.Accepted);
        var rejectedEnvelope = Assert.IsType<FileTransferCoordinatorTransitionEnvelope>(
            rejected.SnapshotEnvelope);
        Assert.Equal(1, rejectedEnvelope.Aggregate.BeforeStateGeneration);
        Assert.Equal(1, rejectedEnvelope.Aggregate.AfterStateGeneration);
        Assert.Equal("Rejected", rejectedEnvelope.DecisionStatus);

        var invalidated = FileTransferCoordinator.InvalidateReceiveRecoveryOperation(
            rejected.State,
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                issued.Authority),
            "snapshot_test_invalidation");
        Assert.True(invalidated.Accepted, invalidated.Reason);
        var invalidationEnvelope = Assert.IsType<FileTransferCoordinatorTransitionEnvelope>(
            invalidated.SnapshotEnvelope);
        Assert.Equal(1, invalidationEnvelope.Aggregate.BeforeStateGeneration);
        Assert.Equal(2, invalidationEnvelope.Aggregate.AfterStateGeneration);
        Assert.Contains(
            invalidationEnvelope.Aggregate.Operations,
            operation => operation is
            {
                Family: "receive_recovery",
                OperationRole: "operation_current",
            } && operation.AfterState == "None");
        Assert.Contains(
            invalidationEnvelope.Aggregate.Operations,
            operation => operation is
            {
                Family: "receive_recovery",
                OperationRole: "operation_terminal",
            } && operation.AfterState.StartsWith(
                "Invalidated:",
                StringComparison.Ordinal));
    }

    [Fact]
    [Trait("FileTransferCoordinatorSuite", "CoordinatorSnapshots")]
    [Trait("FileTransferCoordinatorSuite", "FallbackTailYield")]
    public void FallbackTailYield_CoordinatorAuthorsTypedProofAndPairingSnapshots()
    {
        var fallback = FileTransferRouteResolver.Resolve(
            FileTransferRoute.PostTunaFallbackV6);
        var source = ActiveFallbackStateWithoutCheckpoint() with
        {
            CurrentDataSessionIdentity = "fallback-snapshot-data-session",
            CurrentDataSessionGeneration = 7,
        };
        var yielded = MarkFallbackTailQuiescent(
            source,
            fallback,
            source.CurrentLeg!.TransportEpochId,
            committedChunk: 5,
            highestObservedChunk: 5);
        var state = yielded.State with
        {
            PersistentState = yielded.State.PersistentState with
            {
                CoordinatorInstanceId = "fallback-tail-snapshot-coordinator",
                SnapshotStateGeneration = 0,
            },
        };
        var decision = Assert.IsType<FallbackTailYieldDecision>(
            yielded.FallbackTailYieldDecision);
        var localReceipt =
            FileTransferCoordinator.CreateFallbackTailLocalProofReceipt(
                state,
                decision,
                "snapshot-local-proof",
                "snapshot-local-fingerprint",
                1_000);
        var peerReceipt =
            FileTransferCoordinator.CreateFallbackTailPeerProofReceipt(
                state,
                CreateCoordinatorFallbackTailPeerProof(state, decision),
                "snapshot-peer-proof",
                1_001);

        var local = FileTransferCoordinator.ApplyFallbackTailLocalProofReceipt(
            state,
            localReceipt);
        Assert.True(local.Accepted, local.Reason);
        var localEnvelope = Assert.IsType<
            FileTransferCoordinatorTransitionEnvelope>(local.SnapshotEnvelope);
        Assert.Equal(0, localEnvelope.Aggregate.BeforeStateGeneration);
        Assert.Equal(1, localEnvelope.Aggregate.AfterStateGeneration);
        var localOperation = Assert.Single(
            localEnvelope.Aggregate.Operations,
            operation => operation.Family == "fallback_tail_yield" &&
                operation.OperationRole == "yield_current");
        Assert.Equal("LocalProofObserved", localOperation.AfterState);
        Assert.Contains(
            localOperation.FallbackTailYield!.Receipts,
            receipt => receipt.Stage == "local_proof" &&
                receipt.ReceiptValidated);

        var paired = FileTransferCoordinator.ApplyFallbackTailPeerProofReceipt(
            local.State,
            peerReceipt);
        Assert.True(paired.Accepted, paired.Reason);
        var pairedEnvelope = Assert.IsType<
            FileTransferCoordinatorTransitionEnvelope>(paired.SnapshotEnvelope);
        Assert.Equal(1, pairedEnvelope.Aggregate.BeforeStateGeneration);
        Assert.Equal(2, pairedEnvelope.Aggregate.AfterStateGeneration);
        var pairedOperation = Assert.Single(
            pairedEnvelope.Aggregate.Operations,
            operation => operation.Family == "fallback_tail_yield" &&
                operation.OperationRole == "yield_current");
        Assert.Equal("Paired", pairedOperation.AfterState);
        Assert.Equal(
            decision.PairKey,
            pairedOperation.FallbackTailYield!.PairKey);
        Assert.Contains(
            pairedOperation.FallbackTailYield.Receipts,
            receipt => receipt.Stage == "local_proof");
        Assert.Contains(
            pairedOperation.FallbackTailYield.Receipts,
            receipt => receipt.Stage == "peer_proof");
        Assert.Contains(
            pairedOperation.FallbackTailYield.Receipts,
            receipt => receipt.Stage == "paired_release");

        var duplicate =
            FileTransferCoordinator.ApplyFallbackTailPeerProofReceipt(
                paired.State,
                peerReceipt);
        Assert.Equal(
            FileTransferFallbackTailYieldTransitionStatus.Idempotent,
            duplicate.Status);
        var duplicateEnvelope = Assert.IsType<
            FileTransferCoordinatorTransitionEnvelope>(
                duplicate.SnapshotEnvelope);
        Assert.Equal(2, duplicateEnvelope.Aggregate.BeforeStateGeneration);
        Assert.Equal(2, duplicateEnvelope.Aggregate.AfterStateGeneration);
        Assert.Equal("Idempotent", duplicateEnvelope.DecisionStatus);
        Assert.Contains(
            duplicateEnvelope.Aggregate.Operations,
            operation => operation.Family == "fallback_tail_yield" &&
                operation.OperationRole == "attempted_decision" &&
                !operation.StateApplied);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "RuntimeUnlockRetryLifecycle")]
    [Trait("FileTransferCoordinatorSuite", "CoordinatorSnapshots")]
    public void RuntimeUnlockRetryLifecycle_CoordinatorAuthorsExactSnapshotBoundaries()
    {
        var (state, request, release) =
            AuthorizeRegularRuntimeUnlockRetryDispatchSource(
                coordinatorInstanceId: "retry-snapshot-coordinator");
        var granted = FileTransferCoordinator.AuthorizeRuntimeUnlockRetryDispatch(
            state,
            request,
            RuntimeUnlockRetryReleaseKind.RegularV4RepairSettlement,
            release.AuthorityId,
            release.RepairGeneration,
            FileTransferRegularV4FrontierRepairSettlementOutcome
                .ProgressObserved
                .ToString());
        var grantEnvelope = Assert.IsType<
            FileTransferCoordinatorTransitionEnvelope>(
                granted.SnapshotEnvelope);
        Assert.Equal(0, grantEnvelope.Aggregate.BeforeStateGeneration);
        Assert.Equal(1, grantEnvelope.Aggregate.AfterStateGeneration);
        var grantedOperation = Assert.Single(
            grantEnvelope.Aggregate.Operations,
            operation => operation.Family ==
                "runtime_unlock_retry_lifecycle");
        Assert.Equal("attempt_pending", grantedOperation.OperationRole);
        Assert.Equal("RetryAttempt", grantedOperation.OperationKind);
        Assert.Equal(
            request.SourcePublicationAuthority.RouteToken,
            grantedOperation.RuntimeUnlockRetry?.SourceBoundary.Route);
        Assert.Equal(
            request.DispatchAttemptGeneration,
            grantedOperation.RuntimeUnlockRetry?.DispatchAttemptGeneration);

        const long stagedUtcMs = 7_000_000;
        var stageResult = new RuntimeUnlockRetryDispatchDecisionStageResult(
            RuntimeUnlockRetryDispatchDecisionStageStatus.Staged,
            "staged",
            granted)
        {
            StageDisposition =
                RuntimeUnlockRetryDispatchStageDisposition.Retained,
            StagedUtcMs = stagedUtcMs,
            StageExpiresUtcMs = stagedUtcMs +
                FileTransferCoordinator
                    .RuntimeUnlockRetryDispatchDeadlineMilliseconds,
        };
        var staged = FileTransferCoordinator.ObserveRuntimeUnlockRetryDispatchStage(
            granted.State,
            stageResult,
            stagedUtcMs);
        var stageEnvelope = Assert.IsType<
            FileTransferCoordinatorTransitionEnvelope>(
                staged.SnapshotEnvelope);
        Assert.Equal(1, stageEnvelope.Aggregate.BeforeStateGeneration);
        Assert.Equal(2, stageEnvelope.Aggregate.AfterStateGeneration);
        var stagedOperation = Assert.Single(
            stageEnvelope.Aggregate.Operations,
            operation => operation.OperationRole == "attempt_pending");
        var stageReceipt = Assert.Single(
            stagedOperation.RuntimeUnlockRetry!.Receipts,
            receipt => receipt.Stage == "stage");
        Assert.True(stageReceipt.ReceiptValidated);

        var duplicate =
            FileTransferCoordinator.ObserveRuntimeUnlockRetryDispatchStage(
                staged.State,
                stageResult,
                stagedUtcMs + 1);
        var duplicateEnvelope = Assert.IsType<
            FileTransferCoordinatorTransitionEnvelope>(
                duplicate.SnapshotEnvelope);
        Assert.Equal(2, duplicateEnvelope.Aggregate.BeforeStateGeneration);
        Assert.Equal(2, duplicateEnvelope.Aggregate.AfterStateGeneration);
        Assert.Equal("Idempotent", duplicateEnvelope.DecisionStatus);
        Assert.All(
            duplicateEnvelope.Aggregate.Operations,
            operation => Assert.False(operation.StateApplied));

        var invalidationPrepared = FileTransferCoordinator
            .PrepareRuntimeUnlockRetryLifecycleScopeInvalidation(
                staged.State,
                "retry_dispatch_runtime_scope_replaced");
        var invalidationCommand = Assert.IsType<
            RuntimeUnlockRetryDispatchScopeInvalidationCommand>(
                invalidationPrepared.Command);
        var invalidationEnvelope = Assert.IsType<
            FileTransferCoordinatorTransitionEnvelope>(
                invalidationPrepared.SnapshotEnvelope);
        var invalidationOperation = Assert.Single(
            invalidationEnvelope.Aggregate.Operations,
            operation => operation.OperationRole == "scope_invalidation");
        Assert.Contains(
            invalidationCommand.CommandId.ToString(),
            invalidationOperation.OperationKey,
            StringComparison.Ordinal);

        var duplicateInvalidation = FileTransferCoordinator
            .PrepareRuntimeUnlockRetryLifecycleScopeInvalidation(
                invalidationPrepared.State,
                "retry_dispatch_runtime_scope_replaced");
        var duplicateInvalidationEnvelope = Assert.IsType<
            FileTransferCoordinatorTransitionEnvelope>(
                duplicateInvalidation.SnapshotEnvelope);
        var duplicateInvalidationOperation = Assert.Single(
            duplicateInvalidationEnvelope.Aggregate.Operations);
        Assert.Equal(
            "scope_invalidation",
            duplicateInvalidationOperation.OperationRole);
        Assert.False(duplicateInvalidationOperation.StateApplied);
        Assert.Contains(
            invalidationCommand.CommandId.ToString(),
            duplicateInvalidationOperation.OperationKey,
            StringComparison.Ordinal);

        var invalidationCommitted = FileTransferCoordinator
            .CommitRuntimeUnlockRetryLifecycleScopeInvalidation(
                invalidationPrepared.State,
                new RuntimeUnlockRetryDispatchScopeInvalidationReceipt(
                    invalidationCommand,
                    RuntimeUnlockRetryDispatchScopeInvalidationStatus.Applied,
                    "retry_dispatch_runtime_scope_replaced"));
        var committedInvalidationEnvelope = Assert.IsType<
            FileTransferCoordinatorTransitionEnvelope>(
                invalidationCommitted.SnapshotEnvelope);
        var committedInvalidationOperation = Assert.Single(
            committedInvalidationEnvelope.Aggregate.Operations,
            operation => operation.OperationRole == "scope_invalidation");
        Assert.Equal("Applied", committedInvalidationOperation.ReceiptStatus);
        Assert.True(committedInvalidationOperation.ReceiptValidated);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "RuntimeUnlockRetryLifecycle")]
    public void RuntimeUnlockRetryLifecycle_InitialRequestOrdinalsAreCoordinatorPrepared()
    {
        var (state, sourceRequest, release) =
            AuthorizeRegularRuntimeUnlockRetryDispatchSource();
        var evaluation = new RuntimeUnlockRetryDispatchInitialEvaluation(
            sourceRequest.SessionId,
            sourceRequest.TransferId,
            sourceRequest.Direction,
            sourceRequest.SourcePublicationAuthority,
            sourceRequest.RecoveryContractGeneration,
            sourceRequest.RetiredOfferGeneration,
            sourceRequest.RetryReason,
            sourceRequest.RecoveryReason,
            sourceRequest.RegularV4LivenessGeneration,
            sourceRequest.BridgeDecisionGeneration)
        {
            ListenerRearmRequirement =
                RuntimeUnlockRetryDispatchListenerRearmRequirement
                    .Required,
        };

        Assert.True(
            FileTransferCoordinator.TryPrepareRuntimeUnlockRetryDispatchInitialRequest(
                state,
                evaluation,
                out var prepared,
                out var prepareReason),
            prepareReason);
        Assert.Equal(1, prepared.DispatchAttemptGeneration);
        Assert.Equal(0, prepared.MissingDispatchSuccessorGeneration);
        Assert.Null(prepared.PredecessorAuthorityId);
        Assert.False(prepared.RequestActivePredecessorSupersession);
        Assert.Equal(
            RuntimeUnlockRetryDispatchListenerRearmRequirement
                .Required,
            prepared.ListenerRearmRequirement);

        var granted = FileTransferCoordinator.AuthorizeRuntimeUnlockRetryDispatch(
            state,
            prepared,
            RuntimeUnlockRetryReleaseKind.RegularV4RepairSettlement,
            release.AuthorityId,
            release.RepairGeneration,
            FileTransferRegularV4FrontierRepairSettlementOutcome
                .ProgressObserved
                .ToString());
        Assert.True(granted.Granted);
        Assert.True(
            FileTransferCoordinator.TryPrepareRuntimeUnlockRetryDispatchInitialRequest(
                granted.State,
                evaluation,
                out var duplicate,
                out var duplicateReason),
            duplicateReason);
        Assert.Equal("idempotent", duplicateReason);
        Assert.Equal(prepared, duplicate);

        Assert.False(
            FileTransferCoordinator.TryPrepareRuntimeUnlockRetryDispatchInitialRequest(
                granted.State,
                evaluation with
                {
                    RetiredOfferGeneration =
                        evaluation.RetiredOfferGeneration + 1,
                },
                out _,
                out var mismatchReason));
        Assert.Equal(
            "retry_dispatch_initial_attempt_already_current",
            mismatchReason);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "RuntimeUnlockRetryLifecycle")]
    public void RuntimeUnlockRetryLifecycle_AuthorizeStageInstallAndDuplicatesAreIdempotent()
    {
        var fixture = AuthorizeAndStagePersistentRetryLifecycle();
        var stagedLifecycle =
            FileTransferCoordinator.GetRuntimeUnlockRetryLifecycle(
                fixture.StagedState);

        Assert.Null(stagedLifecycle.InstalledAttempt);
        var pending = Assert.IsType<RuntimeUnlockRetryLifecycleAttemptSnapshot>(
            stagedLifecycle.PendingAttempt);
        Assert.Equal(
            RuntimeUnlockRetryLifecycleAttemptState.Staged,
            pending.State);
        Assert.Equal(fixture.Request, pending.Request);
        Assert.Equal(fixture.Granted.Contract!.Authority, pending.Authority);

        var duplicateStage =
            FileTransferCoordinator.ObserveRuntimeUnlockRetryDispatchStage(
                fixture.StagedState,
                fixture.StageResult,
                fixture.StagedUtcMs + 1);
        Assert.Equal(
            RuntimeUnlockRetryLifecycleTransitionStatus.Idempotent,
            duplicateStage.Status);
        Assert.Same(fixture.StagedState, duplicateStage.State);

        var issuance =
            FileTransferCoordinator.IssueRuntimeUnlockRetryDispatchInstallReceipt(
                fixture.StagedState,
                fixture.Granted,
                fixture.Request,
                fixture.StagedUtcMs + 1);
        Assert.Equal(
            RuntimeUnlockRetryLifecycleTransitionStatus.Accepted,
            issuance.Status);
        var receipt = Assert.IsType<RuntimeUnlockRetryDispatchInstallReceipt>(
            issuance.Receipt);
        var issuedLifecycle =
            FileTransferCoordinator.GetRuntimeUnlockRetryLifecycle(issuance.State);
        Assert.Equal(receipt, issuedLifecycle.PendingAttempt!.Value.InstallReceipt);
        Assert.Equal(
            receipt.InstallGeneration,
            issuedLifecycle.LastInstallGeneration);
        Assert.Equal(
            fixture.StagedUtcMs + 1 +
            FileTransferCoordinator.RuntimeUnlockRetryDispatchDeadlineMilliseconds,
            receipt.DispatchDeadlineUtcMs);
        Assert.Equal(
            receipt.DispatchDeadlineUtcMs,
            issuedLifecycle.PendingAttempt!.Value.DispatchDeadlineUtcMs);
        var duplicateIssuance =
            FileTransferCoordinator.IssueRuntimeUnlockRetryDispatchInstallReceipt(
                issuance.State,
                fixture.Granted,
                fixture.Request,
                fixture.StagedUtcMs + 2);
        Assert.Equal(
            RuntimeUnlockRetryLifecycleTransitionStatus.Idempotent,
            duplicateIssuance.Status);
        Assert.Equal(receipt, duplicateIssuance.Receipt);
        Assert.Same(issuance.State, duplicateIssuance.State);
        var installed = FileTransferCoordinator.CommitRuntimeUnlockRetryDispatchInstall(
            issuance.State,
            new RuntimeUnlockRetryDispatchInstallResult(
                RuntimeUnlockRetryDispatchInstallStatus.Installed,
                "installed",
                receipt),
            fixture.StagedUtcMs + 3);
        Assert.Equal(
            RuntimeUnlockRetryLifecycleTransitionStatus.Accepted,
            installed.Status);
        var installedAttempt = Assert.IsType<RuntimeUnlockRetryLifecycleAttemptSnapshot>(
            FileTransferCoordinator.GetRuntimeUnlockRetryLifecycle(installed.State)
                .InstalledAttempt);
        Assert.Equal(
            RuntimeUnlockRetryLifecycleAttemptState.Installed,
            installedAttempt.State);
        Assert.Equal(receipt, installedAttempt.InstallReceipt);
        Assert.Equal(
            receipt.DispatchDeadlineUtcMs,
            installedAttempt.DispatchDeadlineUtcMs);

        var duplicateInstall =
            FileTransferCoordinator.CommitRuntimeUnlockRetryDispatchInstall(
                installed.State,
                new RuntimeUnlockRetryDispatchInstallResult(
                    RuntimeUnlockRetryDispatchInstallStatus.Idempotent,
                    "idempotent",
                    receipt),
                fixture.StageResult.StageExpiresUtcMs + 1);
        Assert.Equal(
            RuntimeUnlockRetryLifecycleTransitionStatus.Idempotent,
            duplicateInstall.Status);
        Assert.Same(installed.State, duplicateInstall.State);
        Assert.Equal(
            installedAttempt.DispatchDeadlineUtcMs,
            FileTransferCoordinator.GetRuntimeUnlockRetryLifecycle(
                    duplicateInstall.State)
                .InstalledAttempt!.Value.DispatchDeadlineUtcMs);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "RuntimeUnlockRetryLifecycle")]
    public void RuntimeUnlockRetryLifecycle_IdempotentRetainedStagePreservesOriginalTimestamp()
    {
        var fixture = AuthorizeAndStagePersistentRetryLifecycle();
        var originalLifecycle =
            FileTransferCoordinator.GetRuntimeUnlockRetryLifecycle(
                fixture.StagedState);
        var originalPending =
            Assert.IsType<RuntimeUnlockRetryLifecycleAttemptSnapshot>(
                originalLifecycle.PendingAttempt);
        var idempotentRetainedStage = fixture.StageResult with
        {
            Status = RuntimeUnlockRetryDispatchDecisionStageStatus.Idempotent,
            StageDisposition =
                RuntimeUnlockRetryDispatchStageDisposition.Retained,
            StagedUtcMs = originalPending.StagedUtcMs,
            StageExpiresUtcMs = originalPending.StageExpiresUtcMs,
        };

        var duplicate =
            FileTransferCoordinator.ObserveRuntimeUnlockRetryDispatchStage(
                fixture.StagedState,
                idempotentRetainedStage,
                fixture.StagedUtcMs + 1);

        Assert.Equal(
            RuntimeUnlockRetryLifecycleTransitionStatus.Idempotent,
            duplicate.Status);
        Assert.Equal("retry_dispatch_stage_duplicate", duplicate.Reason);
        Assert.Same(fixture.StagedState, duplicate.State);
        var duplicatePending =
            Assert.IsType<RuntimeUnlockRetryLifecycleAttemptSnapshot>(
                FileTransferCoordinator.GetRuntimeUnlockRetryLifecycle(
                        duplicate.State)
                    .PendingAttempt);
        Assert.Equal(
            RuntimeUnlockRetryDispatchDecisionStageStatus.Staged,
            duplicatePending.StageStatus);
