    [Fact]
    public void FileTransferReceiveRecoveryOperation_ReceiptAndProofArrivalOrdersConverge()
    {
        var receiptFirst = CreateReceiveRecoveryOperationFixture();
        var proofFirst = CreateReceiveRecoveryOperationFixture();
        var receiptFirstAuthority =
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                receiptFirst.Decision.Authority);
        var proofFirstAuthority =
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                proofFirst.Decision.Authority);
        Assert.Equal(receiptFirstAuthority, proofFirstAuthority);

        var receipt = new FileTransferBridgeRecoveryExecutionReceipt(
            receiptFirstAuthority.ExecutionCommand,
            FileTransferBridgeRecoveryExecutionOutcome.Completed,
            "soft_then_hard",
            "bridge_recovery_completed");
        var startResult =
            new FileTransferBridgeRecoveryExecutionStartResult(
                receiptFirstAuthority.ExecutionCommand,
                FileTransferBridgeRecoveryExecutionStartStatus.Started,
                "bridge_recovery_execution_started",
                Task.FromResult(receipt));
        var receiptFirstStarted =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
                receiptFirst.Decision.State,
                startResult);
        Assert.True(receiptFirstStarted.Accepted);
        var receiptApplied =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
                receiptFirstStarted.State,
                receipt);
        var retained = Assert.IsType<FileTransferReceiveRecoveryOperation>(
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                receiptApplied.State).CurrentOperation);
        Assert.Equal(
            FileTransferReceiveRecoveryClosureState.Retained,
            retained.ClosureState);

        var proof = new FileTransferReceiveRecoveryProof(
            receiptFirstAuthority,
            "receive-proof-1",
            "receive_proof_observed",
            2);
        var receiptThenProof =
            FileTransferCoordinator.ObserveReceiveRecoveryProof(
                receiptApplied.State,
                proof);
        var adoptedAfterReceipt =
            Assert.IsType<FileTransferReceiveRecoveryOperation>(
                FileTransferCoordinator.GetReceiveRecoverySubstate(
                    receiptThenProof.State).CurrentOperation);
        Assert.Equal(
            FileTransferReceiveRecoveryClosureState.Adopted,
            adoptedAfterReceipt.ClosureState);

        var proofFirstReceipt = receipt with
        {
            Command = proofFirstAuthority.ExecutionCommand,
        };
        var proofFirstStarted =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
                proofFirst.Decision.State,
                startResult with
                {
                    Command = proofFirstAuthority.ExecutionCommand,
                    Completion = Task.FromResult(proofFirstReceipt),
                });
        var proofObserved =
            FileTransferCoordinator.ObserveReceiveRecoveryProof(
                proofFirstStarted.State,
                proof with { Authority = proofFirstAuthority });
        var pendingProof = Assert.IsType<FileTransferReceiveRecoveryOperation>(
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                proofObserved.State).CurrentOperation);
        Assert.Equal(
            FileTransferReceiveRecoveryClosureState.None,
            pendingProof.ClosureState);
        var proofThenReceipt =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
                proofObserved.State,
                proofFirstReceipt);
        var adoptedAfterProof =
            Assert.IsType<FileTransferReceiveRecoveryOperation>(
                FileTransferCoordinator.GetReceiveRecoverySubstate(
                    proofThenReceipt.State).CurrentOperation);
        Assert.Equal(adoptedAfterReceipt, adoptedAfterProof);
    }

    [Fact]
    public void FileTransferReceiveRecoveryProofStatePublication_ReceiptAndReachabilityArrivalOrdersConverge()
    {
        var reachabilityFirst =
            CreateReceiveRecoveryOperationFixture(
                FileTransferDirection.Inbound);
        var receiptFirst =
            CreateReceiveRecoveryOperationFixture(
                FileTransferDirection.Inbound);
        var reachabilityAuthority =
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                reachabilityFirst.Decision.Authority);
        var receiptAuthority =
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                receiptFirst.Decision.Authority);
        var reachabilityReceipt =
            new FileTransferBridgeRecoveryExecutionReceipt(
                reachabilityAuthority.ExecutionCommand,
                FileTransferBridgeRecoveryExecutionOutcome.Completed,
                "hard",
                "bridge_recovery_completed");
        var receiptFirstReceipt = reachabilityReceipt with
        {
            Command = receiptAuthority.ExecutionCommand,
        };
        var reachabilityStarted =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
                reachabilityFirst.Decision.State,
                new FileTransferBridgeRecoveryExecutionStartResult(
                    reachabilityAuthority.ExecutionCommand,
                    FileTransferBridgeRecoveryExecutionStartStatus.Started,
                    "bridge_recovery_execution_started",
                    Task.FromResult(reachabilityReceipt)),
                observedUtcMs: 100);
        var receiptStarted =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
                receiptFirst.Decision.State,
                new FileTransferBridgeRecoveryExecutionStartResult(
                    receiptAuthority.ExecutionCommand,
                    FileTransferBridgeRecoveryExecutionStartStatus.Started,
                    "bridge_recovery_execution_started",
                    Task.FromResult(receiptFirstReceipt)),
                observedUtcMs: 100);
        var reachabilityObservation =
            CreateReceiveRecoveryPeerReachabilityObservation(
                reachabilityAuthority.ExecutionCommand,
                observedUtcMs: 300);
        var observedFirst =
            FileTransferCoordinator.ObserveReceiveRecoveryPeerReachability(
                reachabilityStarted.State,
                reachabilityObservation);
        Assert.True(observedFirst.Accepted, observedFirst.Reason);
        Assert.Null(observedFirst.ProofStatePublicationCommand);

        var reachabilityThenReceipt =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
                observedFirst.State,
                reachabilityReceipt,
                observedUtcMs: 200);
        var firstCommand =
            Assert.IsType<
                FileTransferReceiveRecoveryProofStatePublicationCommand>(
                reachabilityThenReceipt.ProofStatePublicationCommand);

        var receiptApplied =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
                receiptStarted.State,
                receiptFirstReceipt,
                observedUtcMs: 200);
        Assert.Null(receiptApplied.ProofStatePublicationCommand);
        var receiptThenReachability =
            FileTransferCoordinator.ObserveReceiveRecoveryPeerReachability(
                receiptApplied.State,
                reachabilityObservation with
                {
                    ExecutionCommand = receiptAuthority.ExecutionCommand,
                });
        var secondCommand =
            Assert.IsType<
                FileTransferReceiveRecoveryProofStatePublicationCommand>(
                receiptThenReachability.ProofStatePublicationCommand);

        Assert.Equal(firstCommand.ClosureGeneration, secondCommand.ClosureGeneration);
        Assert.Equal(
            firstCommand.PublicationGeneration,
            secondCommand.PublicationGeneration);
        Assert.Equal(
            FileTransferReceiveRecoveryClosureState.Retained,
            reachabilityThenReceipt.State.PersistentState
                .FileTransferReceiveRecovery.CurrentOperation?.ClosureState);
    }

    [Fact]
    public void FileTransferReceiveRecoveryProofStateActivationPause_HeldPreservesExactCommandUntilTerminalReceipt()
    {
        var fixture = CreateReceiveRecoveryOperationFixture(
            FileTransferDirection.Inbound);
        var authority =
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                fixture.Decision.Authority);
        var executionReceipt = new FileTransferBridgeRecoveryExecutionReceipt(
            authority.ExecutionCommand,
            FileTransferBridgeRecoveryExecutionOutcome.Completed,
            "hard",
            "bridge_recovery_completed");
        var started = FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
            fixture.Decision.State,
            new FileTransferBridgeRecoveryExecutionStartResult(
                authority.ExecutionCommand,
                FileTransferBridgeRecoveryExecutionStartStatus.Started,
                "bridge_recovery_execution_started",
                Task.FromResult(executionReceipt)),
            observedUtcMs: 100);
        var completed = FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
            started.State,
            executionReceipt,
            observedUtcMs: 200);
        var issued = FileTransferCoordinator.ObserveReceiveRecoveryPeerReachability(
            completed.State,
            CreateReceiveRecoveryPeerReachabilityObservation(
                authority.ExecutionCommand,
                observedUtcMs: 300));
        var command =
            Assert.IsType<FileTransferReceiveRecoveryProofStatePublicationCommand>(
                issued.ProofStatePublicationCommand);
        var heldReceipt =
            new FileTransferReceiveRecoveryProofStatePublicationReceipt(
                command,
                FileTransferReceiveRecoveryProofStatePublicationOutcome.Held,
                "(none)",
                "filetransfer_receive_recovery_proof_state_held_for_tuna_activation_pause");

        var held = FileTransferCoordinator
            .ApplyReceiveRecoveryProofStatePublicationReceipt(
                issued.State,
                heldReceipt,
                observedUtcMs: 350);

        Assert.True(held.Accepted, held.Reason);
        var heldSubstate = Assert.IsType<
            FileTransferReceiveRecoveryProofStatePublicationSubstate>(
            held.State.PersistentState.FileTransferReceiveRecovery
                .ProofStatePublication);
        Assert.Equal(command, heldSubstate.PendingCommand);
        Assert.Equal(heldReceipt, heldSubstate.LastHeldReceipt);
        Assert.Null(heldSubstate.LastReceipt);
        Assert.Null(heldSubstate.PendingRecheckArm);
        Assert.Equal(
            command,
            FileTransferCoordinator
                .GetCurrentHeldReceiveRecoveryProofStatePublicationCommand(
                    held.State));

        var duplicate = FileTransferCoordinator
            .ApplyReceiveRecoveryProofStatePublicationReceipt(
                held.State,
                heldReceipt,
                observedUtcMs: 360);
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Idempotent,
            duplicate.Status);
        Assert.Equal(held.State, duplicate.State);

        var mutated = FileTransferCoordinator
            .ApplyReceiveRecoveryProofStatePublicationReceipt(
                held.State,
                heldReceipt with { FrameFingerprint = "mutated" },
                observedUtcMs: 370);
        Assert.False(mutated.Accepted);
        Assert.Equal(held.State, mutated.State);

        var deliveredReceipt = heldReceipt with
        {
            Outcome =
                FileTransferReceiveRecoveryProofStatePublicationOutcome
                    .Delivered,
            FrameFingerprint = "frame-fingerprint",
            Reason = "filetransfer_receive_recovery_proof_state_delivered",
        };
        var delivered = FileTransferCoordinator
            .ApplyReceiveRecoveryProofStatePublicationReceipt(
                held.State,
                deliveredReceipt,
                observedUtcMs: 400);
        Assert.True(delivered.Accepted, delivered.Reason);
        var deliveredSubstate = Assert.IsType<
            FileTransferReceiveRecoveryProofStatePublicationSubstate>(
            delivered.State.PersistentState.FileTransferReceiveRecovery
                .ProofStatePublication);
        Assert.Null(deliveredSubstate.PendingCommand);
        Assert.Null(deliveredSubstate.LastHeldReceipt);
        Assert.Equal(deliveredReceipt, deliveredSubstate.LastReceipt);
        Assert.NotNull(deliveredSubstate.PendingRecheckArm);
        Assert.Null(
            FileTransferCoordinator
                .GetCurrentHeldReceiveRecoveryProofStatePublicationCommand(
                    delivered.State));

        var rejected = FileTransferCoordinator
            .ApplyReceiveRecoveryProofStatePublicationReceipt(
                held.State,
                heldReceipt with
                {
                    Outcome =
                        FileTransferReceiveRecoveryProofStatePublicationOutcome
                            .Rejected,
                    Reason = "filetransfer_receive_recovery_proof_state_rejected",
                },
                observedUtcMs: 400);
        Assert.True(rejected.Accepted, rejected.Reason);
        Assert.Null(
            rejected.State.PersistentState.FileTransferReceiveRecovery
                .ProofStatePublication?.PendingCommand);
        Assert.Null(
            rejected.State.PersistentState.FileTransferReceiveRecovery
                .ProofStatePublication?.LastHeldReceipt);
    }

    [Fact]
    public void FileTransferReceiveRecoveryProofStatePublication_DeliveredReceiptArmsOneHeartbeatRecheckAndProofInvalidatesPendingCommand()
    {
        var fixture =
            CreateReceiveRecoveryOperationFixture(
                FileTransferDirection.Inbound);
        var authority =
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                fixture.Decision.Authority);
        var receipt = new FileTransferBridgeRecoveryExecutionReceipt(
            authority.ExecutionCommand,
            FileTransferBridgeRecoveryExecutionOutcome.Completed,
            "hard",
            "bridge_recovery_completed");
        var started =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
                fixture.Decision.State,
                new FileTransferBridgeRecoveryExecutionStartResult(
                    authority.ExecutionCommand,
                    FileTransferBridgeRecoveryExecutionStartStatus.Started,
                    "bridge_recovery_execution_started",
                    Task.FromResult(receipt)),
                observedUtcMs: 100);
        var completed =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
                started.State,
                receipt,
                observedUtcMs: 200);
        var reachability =
            CreateReceiveRecoveryPeerReachabilityObservation(
                authority.ExecutionCommand,
                observedUtcMs: 300);
        var issued =
            FileTransferCoordinator.ObserveReceiveRecoveryPeerReachability(
                completed.State,
                reachability);
        var command =
            Assert.IsType<
                FileTransferReceiveRecoveryProofStatePublicationCommand>(
                issued.ProofStatePublicationCommand);
        var delivered =
            FileTransferCoordinator
                .ApplyReceiveRecoveryProofStatePublicationReceipt(
                    issued.State,
                    new FileTransferReceiveRecoveryProofStatePublicationReceipt(
                        command,
                        FileTransferReceiveRecoveryProofStatePublicationOutcome
                            .Delivered,
                        "frame-fingerprint",
                        "delivered"),
                    observedUtcMs: 350);
        Assert.True(delivered.Accepted, delivered.Reason);
        var retained = Assert.IsType<FileTransferReceiveRecoveryOperation>(
            delivered.State.PersistentState.FileTransferReceiveRecovery
                .CurrentOperation);
        Assert.Equal(
            FileTransferReceiveRecoveryClosureState.Retained,
            retained.ClosureState);
        Assert.Null(retained.ReceiveProof);
        var deliveredReceipt =
            Assert.IsType<
                FileTransferReceiveRecoveryProofStatePublicationReceipt>(
                delivered.State.PersistentState.FileTransferReceiveRecovery
                    .ProofStatePublication?.LastReceipt);
        var arm =
            Assert.IsType<
                FileTransferReceiveRecoveryProofStatePublicationRecheckArm>(
                delivered.State.PersistentState.FileTransferReceiveRecovery
                    .ProofStatePublication?.PendingRecheckArm);
        Assert.Equal(deliveredReceipt, arm.PredecessorReceipt);
        Assert.Equal(350, arm.ArmedUtcMs);
        var duplicate =
            FileTransferCoordinator.ObserveReceiveRecoveryPeerReachability(
                delivered.State,
                reachability);
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Idempotent,
            duplicate.Status);
        Assert.Null(duplicate.ProofStatePublicationCommand);
        Assert.Equal(delivered.State, duplicate.State);

        var reissued =
            FileTransferCoordinator.ObserveReceiveRecoveryPeerReachability(
                delivered.State,
                CreateReceiveRecoveryPeerReachabilityObservation(
                    authority.ExecutionCommand,
                    observedUtcMs: 400));
        Assert.False(reissued.Accepted);
        Assert.Null(reissued.ProofStatePublicationCommand);

        var heartbeatEvidence =
            CreateReceiveRecoveryProofStatePublicationRecheckEvidence(
                delivered.State.SessionId,
                heartbeatSequence: 19,
                observedUtcMs: 400);
        var staleHeartbeat =
            FileTransferCoordinator
                .ObserveReceiveRecoveryProofStatePublicationRecheckEvidence(
                    delivered.State,
                    heartbeatEvidence with { ObservedUtcMs = 350 });
        Assert.False(staleHeartbeat.Accepted);
        Assert.Equal(delivered.State, staleHeartbeat.State);
        var heartbeatAck =
            FileTransferCoordinator
                .ObserveReceiveRecoveryProofStatePublicationRecheckEvidence(
                    delivered.State,
                    heartbeatEvidence with
                    {
                        ProofKind = "heartbeat_ack",
                        Lane = "control_ack",
                    });
        Assert.False(heartbeatAck.Accepted);
        Assert.Equal(delivered.State, heartbeatAck.State);

        var recheck =
            FileTransferCoordinator
                .ObserveReceiveRecoveryProofStatePublicationRecheckEvidence(
                    delivered.State,
                    heartbeatEvidence);
        Assert.True(recheck.Accepted, recheck.Reason);
        var recheckCommand =
            Assert.IsType<
                FileTransferReceiveRecoveryProofStatePublicationCommand>(
                recheck.ProofStatePublicationCommand);
        Assert.Equal(2, recheckCommand.PublicationGeneration);
        Assert.Equal(command.Authority, recheckCommand.Authority);
        Assert.Equal(command.ClosureGeneration, recheckCommand.ClosureGeneration);
        Assert.Equal(command.Observation, recheckCommand.Observation);
        Assert.Equal(deliveredReceipt, recheckCommand.PredecessorReceipt);
        Assert.Equal(
            arm.ArmedUtcMs,
            recheckCommand.PredecessorReceiptObservedUtcMs);
        Assert.Equal(heartbeatEvidence, recheckCommand.RecheckEvidence);
        Assert.Null(
            recheck.State.PersistentState.FileTransferReceiveRecovery
                .ProofStatePublication?.PendingRecheckArm);
        Assert.True(
            FileTransferCoordinator
                .IsReceiveRecoveryProofStatePublicationCommandCurrent(
                    recheck.State,
                    recheckCommand));

        var duplicateHeartbeat =
            FileTransferCoordinator
                .ObserveReceiveRecoveryProofStatePublicationRecheckEvidence(
                    recheck.State,
                    heartbeatEvidence);
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Idempotent,
            duplicateHeartbeat.Status);
        Assert.Equal(recheckCommand, duplicateHeartbeat.ProofStatePublicationCommand);
        Assert.Equal(recheck.State, duplicateHeartbeat.State);
        var duplicateHeartbeatWithLaterLocalTimestamp =
            FileTransferCoordinator
                .ObserveReceiveRecoveryProofStatePublicationRecheckEvidence(
                    recheck.State,
                    heartbeatEvidence with
                    {
                        ObservedUtcMs = heartbeatEvidence.ObservedUtcMs + 1,
                    });
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Idempotent,
            duplicateHeartbeatWithLaterLocalTimestamp.Status);
        Assert.Equal(
            recheckCommand,
            duplicateHeartbeatWithLaterLocalTimestamp
                .ProofStatePublicationCommand);
        Assert.Equal(
            recheck.State,
            duplicateHeartbeatWithLaterLocalTimestamp.State);
        var laterHeartbeat =
            FileTransferCoordinator
                .ObserveReceiveRecoveryProofStatePublicationRecheckEvidence(
                    recheck.State,
                    heartbeatEvidence with
                    {
                        HeartbeatSequence = 20,
                        ObservedUtcMs = 450,
                    });
        Assert.False(laterHeartbeat.Accepted);
        Assert.Null(laterHeartbeat.ProofStatePublicationCommand);
        Assert.Equal(recheck.State, laterHeartbeat.State);

        var proofWinsRecheckRace =
            FileTransferCoordinator.ObserveReceiveRecoveryProof(
                recheck.State,
                new FileTransferReceiveRecoveryProof(
                    authority,
                    "peer-v4-state-proof-after-recheck",
                    "file_transfer_data_frame",
                    475));
        Assert.True(proofWinsRecheckRace.Accepted, proofWinsRecheckRace.Reason);
        Assert.Null(
            proofWinsRecheckRace.State.PersistentState
                .FileTransferReceiveRecovery.ProofStatePublication);
        Assert.False(
            FileTransferCoordinator
                .IsReceiveRecoveryProofStatePublicationCommandCurrent(
                    proofWinsRecheckRace.State,
                    recheckCommand));

        var recheckDeliveredReceipt =
            new FileTransferReceiveRecoveryProofStatePublicationReceipt(
                recheckCommand,
                FileTransferReceiveRecoveryProofStatePublicationOutcome
                    .Delivered,
                "recheck-frame-fingerprint",
                "delivered");
        var recheckDelivered =
            FileTransferCoordinator
                .ApplyReceiveRecoveryProofStatePublicationReceipt(
                    recheck.State,
                    recheckDeliveredReceipt,
                    observedUtcMs: 500);
        Assert.True(recheckDelivered.Accepted, recheckDelivered.Reason);
        Assert.Null(
            recheckDelivered.State.PersistentState.FileTransferReceiveRecovery
                .ProofStatePublication?.PendingRecheckArm);
        var noThirdPublication =
            FileTransferCoordinator
                .ObserveReceiveRecoveryProofStatePublicationRecheckEvidence(
                    recheckDelivered.State,
                    heartbeatEvidence with
                    {
                        HeartbeatSequence = 21,
                        ObservedUtcMs = 550,
                    });
        Assert.False(noThirdPublication.Accepted);
        Assert.Null(noThirdPublication.ProofStatePublicationCommand);
        Assert.Equal(recheckDelivered.State, noThirdPublication.State);
        var duplicatePredecessorReceipt =
            FileTransferCoordinator
                .ApplyReceiveRecoveryProofStatePublicationReceipt(
                    recheckDelivered.State,
                    deliveredReceipt,
                    observedUtcMs: 600);
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Idempotent,
            duplicatePredecessorReceipt.Status);
        Assert.Equal(
            recheckDelivered.State,
            duplicatePredecessorReceipt.State);

        var pendingFixture =
            CreateReceiveRecoveryOperationFixture(
                FileTransferDirection.Inbound);
        var pendingAuthority =
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                pendingFixture.Decision.Authority);
        var pendingReceipt =
            new FileTransferBridgeRecoveryExecutionReceipt(
                pendingAuthority.ExecutionCommand,
                FileTransferBridgeRecoveryExecutionOutcome.Completed,
                "hard",
                "bridge_recovery_completed");
        var pendingStarted =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
                pendingFixture.Decision.State,
                new FileTransferBridgeRecoveryExecutionStartResult(
                    pendingAuthority.ExecutionCommand,
                    FileTransferBridgeRecoveryExecutionStartStatus.Started,
                    "bridge_recovery_execution_started",
                    Task.FromResult(pendingReceipt)),
                observedUtcMs: 100);
        var pendingCompleted =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
                pendingStarted.State,
                pendingReceipt,
                observedUtcMs: 200);
        var pendingIssued =
            FileTransferCoordinator.ObserveReceiveRecoveryPeerReachability(
                pendingCompleted.State,
                CreateReceiveRecoveryPeerReachabilityObservation(
                    pendingAuthority.ExecutionCommand,
                    observedUtcMs: 300));
        var pending =
            Assert.IsType<
                FileTransferReceiveRecoveryProofStatePublicationCommand>(
                pendingIssued.ProofStatePublicationCommand);
        var proved = FileTransferCoordinator.ObserveReceiveRecoveryProof(
            pendingIssued.State,
            new FileTransferReceiveRecoveryProof(
                pendingAuthority,
                "peer-v4-state-proof",
                "file_transfer_data_frame",
                500));
        Assert.True(proved.Accepted, proved.Reason);
        Assert.Null(
            proved.State.PersistentState.FileTransferReceiveRecovery
                .ProofStatePublication?.PendingCommand);
        Assert.Equal(
            FileTransferReceiveRecoveryClosureState.Adopted,
            proved.State.PersistentState.FileTransferReceiveRecovery
                .CurrentOperation?.ClosureState);
        Assert.False(
            FileTransferCoordinator
                .IsReceiveRecoveryProofStatePublicationCommandCurrent(
                    proved.State,
                    pending));
    }

    [Fact]
    public void FileTransferReceiveRecoveryProofStatePublication_RecheckArmIsClearedByExactOperationInvalidation()
    {
        var fixture =
            CreateReceiveRecoveryOperationFixture(
                FileTransferDirection.Inbound);
        var authority =
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                fixture.Decision.Authority);
        var executionReceipt =
            new FileTransferBridgeRecoveryExecutionReceipt(
                authority.ExecutionCommand,
                FileTransferBridgeRecoveryExecutionOutcome.Completed,
                "hard",
                "bridge_recovery_completed");
        var started =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
                fixture.Decision.State,
                new FileTransferBridgeRecoveryExecutionStartResult(
                    authority.ExecutionCommand,
                    FileTransferBridgeRecoveryExecutionStartStatus.Started,
                    "bridge_recovery_execution_started",
                    Task.FromResult(executionReceipt)),
                observedUtcMs: 100);
        var completed =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
                started.State,
                executionReceipt,
                observedUtcMs: 200);
        var issued =
            FileTransferCoordinator.ObserveReceiveRecoveryPeerReachability(
                completed.State,
                CreateReceiveRecoveryPeerReachabilityObservation(
                    authority.ExecutionCommand,
                    observedUtcMs: 300));
        var command =
            Assert.IsType<
                FileTransferReceiveRecoveryProofStatePublicationCommand>(
                issued.ProofStatePublicationCommand);
        var delivered =
            FileTransferCoordinator
                .ApplyReceiveRecoveryProofStatePublicationReceipt(
                    issued.State,
                    new FileTransferReceiveRecoveryProofStatePublicationReceipt(
                        command,
                        FileTransferReceiveRecoveryProofStatePublicationOutcome
                            .Delivered,
                        "frame-fingerprint",
                        "delivered"),
                    observedUtcMs: 350);
        Assert.NotNull(
            delivered.State.PersistentState.FileTransferReceiveRecovery
                .ProofStatePublication?.PendingRecheckArm);

        var invalidated =
            FileTransferCoordinator.InvalidateReceiveRecoveryOperation(
                delivered.State,
                authority,
                "scope_replaced");
        Assert.True(invalidated.Accepted, invalidated.Reason);
        Assert.Null(
            invalidated.State.PersistentState.FileTransferReceiveRecovery
                .ProofStatePublication);

        var staleEvidence =
            FileTransferCoordinator
                .ObserveReceiveRecoveryProofStatePublicationRecheckEvidence(
                    invalidated.State,
                    CreateReceiveRecoveryProofStatePublicationRecheckEvidence(
                        invalidated.State.SessionId,
                        heartbeatSequence: 19,
                        observedUtcMs: 400));
        Assert.False(staleEvidence.Accepted);
        Assert.Null(staleEvidence.ProofStatePublicationCommand);
        Assert.Equal(invalidated.State, staleEvidence.State);
    }

    [Fact]
    public void RuntimeUnlockInitialActivationReceiveRecoveryHold_ProofReleasesAfterCompletionAndProofFirstDoesNotInstallOne()
    {
        var heldFixture = CreateReceiveRecoveryOperationFixture();
        var authority =
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                heldFixture.Decision.Authority);
        var request =
            CreateInitialActivationReceiveRecoveryHoldRequest(
