    [Fact]
    public void BridgeRecoveryExecutionPayloadHold_CoordinatorReleasesOnlyOnCompletedProof()
    {
        var runningFixture = CreateReceiveRecoveryOperationFixture();
        var runningAuthority =
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                runningFixture.Decision.Authority);
        Assert.True(
            FileTransferCoordinator
                .TryGetCurrentReceiveRecoveryPayloadSubmissionHold(
                    runningFixture.Decision.State,
                    out var issued,
                    out _));
        Assert.Equal(
            FileTransferReceiveRecoveryExecutionState.Issued,
            issued.ExecutionState);

        var completedReceipt =
            new FileTransferBridgeRecoveryExecutionReceipt(
                runningAuthority.ExecutionCommand,
                FileTransferBridgeRecoveryExecutionOutcome.Completed,
                "hard",
                "bridge_recovery_completed");
        var running =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
                runningFixture.Decision.State,
                new FileTransferBridgeRecoveryExecutionStartResult(
                    runningAuthority.ExecutionCommand,
                    FileTransferBridgeRecoveryExecutionStartStatus.Started,
                    "bridge_recovery_execution_started",
                    Task.FromResult(completedReceipt)));
        Assert.True(
            FileTransferCoordinator
                .TryGetReceiveRecoveryPayloadSubmissionHold(
                    running.State,
                    out var runningOperation,
                    out _));
        Assert.Equal(
            FileTransferReceiveRecoveryExecutionState.Running,
            runningOperation.ExecutionState);

        var completed =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
                running.State,
                completedReceipt);
        Assert.True(
            FileTransferCoordinator
                .TryGetReceiveRecoveryPayloadSubmissionHold(
                    completed.State,
                    out var completedHeld,
                    out var completedHoldReason));
        Assert.Equal(
            FileTransferReceiveRecoveryClosureState.Retained,
            completedHeld.ClosureState);
        Assert.Equal(
            "filetransfer_receive_recovery_completed_awaiting_receive_proof",
            completedHoldReason);
        Assert.False(
            FileTransferCoordinator
                .TryGetReceiveRecoveryPayloadSubmissionProofRelease(
                    completed.State,
                    out _));

        var proof = FileTransferCoordinator.ObserveReceiveRecoveryProof(
            completed.State,
            new FileTransferReceiveRecoveryProof(
                runningAuthority,
                "payload-hold-release-proof",
                "receive_proof_observed",
                completedHeld.ExecutionReceiptObservedUtcMs + 1));
        Assert.True(proof.Accepted, proof.Reason);
        Assert.False(
            FileTransferCoordinator
                .TryGetReceiveRecoveryPayloadSubmissionHold(
                    proof.State,
                    out _,
                    out _));
        Assert.True(
            FileTransferCoordinator
                .TryGetReceiveRecoveryPayloadSubmissionProofRelease(
                    proof.State,
                    out var released));
        Assert.Equal(
            FileTransferReceiveRecoveryClosureState.Adopted,
            released.ClosureState);

        foreach (var outcome in new[]
                 {
                     FileTransferBridgeRecoveryExecutionOutcome.Exhausted,
                     FileTransferBridgeRecoveryExecutionOutcome.Discarded,
                 })
        {
            var terminalFixture = CreateReceiveRecoveryOperationFixture();
            var terminalAuthority =
                Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                    terminalFixture.Decision.Authority);
            var terminalReceipt =
                new FileTransferBridgeRecoveryExecutionReceipt(
                    terminalAuthority.ExecutionCommand,
                    outcome,
                    "hard",
                    $"bridge_recovery_{outcome.ToString().ToLowerInvariant()}");
            var terminalRunning =
                FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
                    terminalFixture.Decision.State,
                    new FileTransferBridgeRecoveryExecutionStartResult(
                        terminalAuthority.ExecutionCommand,
                        FileTransferBridgeRecoveryExecutionStartStatus.Started,
                        "bridge_recovery_execution_started",
                        Task.FromResult(terminalReceipt)));
            var terminal =
                FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
                    terminalRunning.State,
                    terminalReceipt);

            Assert.False(
                FileTransferCoordinator
                    .TryGetCurrentReceiveRecoveryPayloadSubmissionHold(
                        terminal.State,
                        out _,
                        out _));
            Assert.True(
                FileTransferCoordinator
                    .TryGetReceiveRecoveryPayloadSubmissionHold(
                        terminal.State,
                        out var heldTerminal,
                        out var holdReason));
            Assert.Equal(
                outcome ==
                    FileTransferBridgeRecoveryExecutionOutcome.Exhausted
                    ? FileTransferReceiveRecoveryExecutionState.Exhausted
                    : FileTransferReceiveRecoveryExecutionState.Discarded,
                heldTerminal.ExecutionState);
            Assert.Equal(
                "filetransfer_receive_recovery_execution_terminal_without_completion",
                holdReason);

            var staleState = terminal.State with
            {
                TerminalGeneration =
                    terminal.State.TerminalGeneration + 1,
            };
            Assert.False(
                FileTransferCoordinator
                    .TryGetReceiveRecoveryPayloadSubmissionHold(
                        staleState,
                        out _,
                        out var staleReason));
            Assert.Equal(
                "filetransfer_receive_recovery_execution_scope_not_current",
                staleReason);
        }

        var invalidatedFixture =
            CreateReceiveRecoveryOperationFixture();
        var invalidatedAuthority =
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                invalidatedFixture.Decision.Authority);
        var invalidated =
            FileTransferCoordinator.InvalidateReceiveRecoveryOperation(
                invalidatedFixture.Decision.State,
                invalidatedAuthority,
                "bridge_recovery_execution_begin_failed");
        Assert.True(
            FileTransferCoordinator
                .TryGetReceiveRecoveryPayloadSubmissionHold(
                    invalidated.State,
                    out var invalidatedHold,
                    out var invalidatedReason));
        Assert.Equal(
            FileTransferReceiveRecoveryExecutionState.Invalidated,
            invalidatedHold.ExecutionState);
        Assert.Equal(
            "filetransfer_receive_recovery_execution_terminal_without_completion",
            invalidatedReason);
    }

    [Fact]
    public void FileTransferReceiveRecoveryOperation_RetainedClosureKeepsBoundedLivenessDeferral()
    {
        var fixture = CreateReceiveRecoveryOperationFixture();
        var authority =
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                fixture.Decision.Authority);
        var receipt = new FileTransferBridgeRecoveryExecutionReceipt(
            authority.ExecutionCommand,
            FileTransferBridgeRecoveryExecutionOutcome.Completed,
            "soft_then_hard",
            "bridge_recovery_completed");
        var start = new FileTransferBridgeRecoveryExecutionStartResult(
            authority.ExecutionCommand,
            FileTransferBridgeRecoveryExecutionStartStatus.Started,
            "bridge_recovery_execution_started",
            Task.FromResult(receipt));
        var started =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
                fixture.Decision.State,
                start,
                observedUtcMs: 45_001);
        var completed =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
                started.State,
                receipt,
                observedUtcMs: 90_001);

        Assert.True(
            FileTransferCoordinator.TryGetReceiveRecoveryLivenessDeferral(
                completed.State,
                out var operation,
                out var retainedGrant,
                out var maximumDeadlineUtc));
        Assert.Equal(
            FileTransferReceiveRecoveryClosureState.Retained,
            operation.ClosureState);
        Assert.Equal(
            RecoveryLivenessLeaseState.Retired,
            Enum.Parse<RecoveryLivenessLeaseState>(
                retainedGrant.LeaseState));
        Assert.Equal(
            180_001,
            maximumDeadlineUtc.ToUnixTimeMilliseconds());

        var duplicateStart =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
                completed.State,
                start with
                {
                    Status =
                        FileTransferBridgeRecoveryExecutionStartStatus.Idempotent,
                    Completion = Task.FromResult(receipt),
                },
                observedUtcMs: 150_001);
        var duplicateReceipt =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
                duplicateStart.State,
                receipt,
                observedUtcMs: 150_001);
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Idempotent,
            duplicateStart.Status);
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Idempotent,
            duplicateReceipt.Status);
        Assert.Equal(completed.State, duplicateReceipt.State);

        var cappedFixture = CreateReceiveRecoveryOperationFixture();
        var cappedAuthority =
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                cappedFixture.Decision.Authority);
        var cappedReceipt = receipt with
        {
            Command = cappedAuthority.ExecutionCommand,
        };
        var cappedStarted =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
                cappedFixture.Decision.State,
                start with
                {
                    Command = cappedAuthority.ExecutionCommand,
                    Completion = Task.FromResult(cappedReceipt),
                },
                observedUtcMs: 45_001);
        var cappedCompleted =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
                cappedStarted.State,
                cappedReceipt,
                observedUtcMs: 190_001);
        Assert.True(
            FileTransferCoordinator.TryGetReceiveRecoveryLivenessDeferral(
                cappedCompleted.State,
                out _,
                out _,
                out var cappedDeadlineUtc));
        Assert.Equal(
            210_001,
            cappedDeadlineUtc.ToUnixTimeMilliseconds());
    }

    [Fact]
    public void FileTransferReceiveRecoveryOperation_PostFallbackArrivalOrdersConvergeWithCoordinatorBackedLiveness()
    {
        var fixture = CreateNonRegularV4ReceiveRecoveryOperationFixture();
        var observedUtcMs =
            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        var observation = CreateReceiveRecoveryObservationForTest(
            fixture.State,
            "post_fallback_receive_recovery") with
        {
            ObservationIdentity =
                "post-fallback-receive-recovery-observation",
            ObservedUtcMs = observedUtcMs,
        };
        var issued = FileTransferCoordinator.IssueReceiveRecoveryOperation(
            fixture.State,
            observation,
            BridgeRecoveryKind.ReceiveRecoveryRequest,
            fixture.State.CurrentLeg?.CheckpointRequestId);
        var authority =
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                issued.Authority);
        Assert.Null(authority.RecoveryLivenessLease);
        var terminalReceipt =
            new FileTransferBridgeRecoveryExecutionReceipt(
                authority.ExecutionCommand,
                FileTransferBridgeRecoveryExecutionOutcome.Completed,
                "soft",
                "bridge_recovery_completed");
        var started =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
                issued.State,
                new FileTransferBridgeRecoveryExecutionStartResult(
                    authority.ExecutionCommand,
                    FileTransferBridgeRecoveryExecutionStartStatus.Started,
                    "bridge_recovery_execution_started",
                    Task.FromResult(terminalReceipt)),
                observedUtcMs + 1);
        var proof = new FileTransferReceiveRecoveryProof(
            authority,
            "post-fallback-receive-proof",
            "receive_proof_observed",
            observedUtcMs + 2);
        var proofFirst =
            FileTransferCoordinator.ObserveReceiveRecoveryProof(
                started.State,
                proof);

        Assert.True(
            SessionFileTransferService
                .TryCreateReceiveRecoveryLivenessSnapshot(
                    proofFirst.State,
                    out var snapshot));
        Assert.Equal(
            FileTransferRecoveryLivenessState.ReceiveProofObserved,
            snapshot.State);
        Assert.False(snapshot.TerminalRecommended);
        var recoveryBefore =
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                proofFirst.State);
        Assert.True(
            SessionFileTransferService
                .TryAuthorizeReceiveRecoveryOperationLivenessDeferralLocked(
                    proofFirst.State,
                    snapshot,
                    "post_fallback_proof_first_liveness",
                    DateTimeOffset
                        .FromUnixTimeMilliseconds(observedUtcMs)
                        .AddSeconds(30),
                    out var grant));
        Assert.NotNull(grant);
        Assert.Equal(
            "ReceiveRecoveryOperation",
            grant!.LeaseState);
        Assert.Equal(
            authority.BridgeRecoveryDecision.BridgeDecisionGeneration,
            grant.LeaseGeneration);
        Assert.Equal(
            recoveryBefore,
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                proofFirst.State));

        var receiptFirst =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
                started.State,
                terminalReceipt,
                observedUtcMs + 3);
        var awaitingProof =
            Assert.IsType<FileTransferReceiveRecoveryOperation>(
                FileTransferCoordinator.GetReceiveRecoverySubstate(
                    receiptFirst.State).CurrentOperation);
        Assert.Equal(
            FileTransferReceiveRecoveryExecutionState.Completed,
            awaitingProof.ExecutionState);
        Assert.Equal(
            FileTransferReceiveRecoveryClosureState.None,
            awaitingProof.ClosureState);
        Assert.Null(awaitingProof.ReceiveProof);
        Assert.True(
            SessionFileTransferService
                .TryCreateReceiveRecoveryLivenessSnapshot(
                    receiptFirst.State,
                    out var receiptFirstSnapshot));
        Assert.Equal(
            FileTransferRecoveryLivenessState
                .BridgeRecoveryCompletedAwaitingProof,
            receiptFirstSnapshot.State);
        Assert.False(receiptFirstSnapshot.TerminalRecommended);
        Assert.True(
            SessionFileTransferService
                .TryAuthorizeReceiveRecoveryOperationLivenessDeferralLocked(
                    receiptFirst.State,
                    receiptFirstSnapshot,
                    "post_fallback_receipt_first_liveness",
                    DateTimeOffset
                        .FromUnixTimeMilliseconds(observedUtcMs)
                        .AddSeconds(30),
                    out var receiptFirstGrant));
        Assert.Equal(
            "ReceiveRecoveryOperation",
            receiptFirstGrant!.LeaseState);

        var receiptThenProof =
            FileTransferCoordinator.ObserveReceiveRecoveryProof(
                receiptFirst.State,
                proof);
        var proofThenReceipt =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
                proofFirst.State,
                terminalReceipt,
                observedUtcMs + 3);
        Assert.Null(
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                receiptThenProof.State).CurrentOperation);
        Assert.Equal(
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                proofThenReceipt.State),
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                receiptThenProof.State));
    }

    [Fact]
    public void FileTransferReceiveRecoveryOperation_CompletedProvenPostFallbackClassifiesObservedPhysicalChildForRetirement()
    {
        var fixture = CreateNonRegularV4ReceiveRecoveryOperationFixture();
        var authority = Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
            fixture.Decision.Authority);
        var receipt = new FileTransferBridgeRecoveryExecutionReceipt(
            authority.ExecutionCommand,
            FileTransferBridgeRecoveryExecutionOutcome.Completed,
            "soft",
            "bridge_recovery_completed");
        var started = FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
            fixture.Decision.State,
            new FileTransferBridgeRecoveryExecutionStartResult(
                authority.ExecutionCommand,
                FileTransferBridgeRecoveryExecutionStartStatus.Started,
                "bridge_recovery_execution_started",
                Task.FromResult(receipt)),
            observedUtcMs: 10);
        var scope = authority.Observation;
        var observation = new FileTransferReceiveRecoverySubmissionFailureObservation(
            authority,
            PhysicalSendLeaseGeneration: 91,
            scope.RuntimeOwner,
            scope.RoutePublication,
            scope.TerminalGeneration,
            scope.LegGeneration,
            scope.TransportEpoch,
            scope.BridgeRecoveryGeneration,
            scope.DataSessionIdentity,
            scope.DataSessionGeneration,
            SendKind: "PostTunaFallbackV6Payload",
            RepairRequestKey: "(none)",
            FileTransferDataSessionSubmissionUnavailableReason.SubmissionEpochChanged,
            RejectionStage: "send_pre_submit",
            RejectionChannel: "bulk",
            ExpectedSubmissionEpoch: 3,
            CurrentSubmissionEpoch: 4,
            ExpectedProcessEpoch: 7,
            CurrentProcessEpoch: 8,
            RecoveryBarrierActive: true,
            ObservedUtcMs: 11);
        Assert.False(observation.IsDefault);

        var completed = FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
            started.State,
            receipt,
            observedUtcMs: 12);
        var proved = FileTransferCoordinator.ObserveReceiveRecoveryProof(
            completed.State,
            new FileTransferReceiveRecoveryProof(
                authority,
                "post-fallback-receive-proof",
                "receive_proof_observed",
                13));

        var disposition = FileTransferCoordinator.ClassifyReceiveRecoverySubmissionFailure(
            proved.State,
            observation,
            DateTimeOffset.FromUnixTimeMilliseconds(14),
            out var operation,
            out var deadline,
            out var reason);

        Assert.Equal(
            FileTransferReceiveRecoverySubmissionFailureDisposition
                .CompletedProvenLateChildRetirement,
            disposition);
        Assert.Equal(authority, operation.Authority);
        Assert.Equal(default, deadline);
        Assert.Equal("completed_proven_late_child_retirement", reason);
        Assert.Equal(FileTransferReceiveRecoveryClosureState.None, operation.ClosureState);
        Assert.NotNull(operation.ReceiveProof);

        var terminalState = proved.State with { IsTerminal = true };
        Assert.Equal(
            FileTransferReceiveRecoverySubmissionFailureDisposition.Rejected,
            FileTransferCoordinator.ClassifyReceiveRecoverySubmissionFailure(
                terminalState,
                observation,
                DateTimeOffset.FromUnixTimeMilliseconds(15),
                out _,
                out _,
                out _));
    }

    [Fact]
    public void FileTransferReceiveRecoveryPostTunaEpochRestart_ActiveOperationIsHeldWithoutMutation()
    {
        var fixture = CreateNonRegularV4ReceiveRecoveryOperationFixture();
        var authority = Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
            fixture.Decision.Authority);
        var receipt = new FileTransferBridgeRecoveryExecutionReceipt(
            authority.ExecutionCommand,
