    [Fact]
    public void FileTransferReceiveRecoveryFallbackCheckpointFrontierRequest_ChildPreservesRunningOperationAndConvergesAfterProof()
    {
        var fixture = CreateNonRegularV4ReceiveRecoveryOperationFixture();
        RunReceiveRecoveryFallbackCheckpointFrontierRequestLifecycle(fixture);
    }

    private static void
        RunReceiveRecoveryFallbackCheckpointFrontierRequestLifecycle(
            (FileTransferCoordinatorState State,
             FileTransferReceiveRecoveryDecision Decision) fixture)
    {
        var authority =
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                fixture.Decision.Authority);
        var receipt = new FileTransferBridgeRecoveryExecutionReceipt(
            authority.ExecutionCommand,
            FileTransferBridgeRecoveryExecutionOutcome.Completed,
            "soft",
            "bridge_recovery_completed");
        var started = FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
            fixture.Decision.State,
            new FileTransferBridgeRecoveryExecutionStartResult(
                authority.ExecutionCommand,
                FileTransferBridgeRecoveryExecutionStartStatus.Started,
                "bridge_recovery_execution_started",
                Task.FromResult(receipt)),
            observedUtcMs: 10);
        Assert.True(started.Accepted, started.Reason);
        var answerTimeoutHoldRequest =
            CreateInitialActivationReceiveRecoveryHoldRequest(
                started.State,
                payerDecisionId: 104);

        var leg = Assert.IsType<FileTransferLeg>(started.State.CurrentLeg);
        var frame = new FileTransferFrontierRequestFrameV6
        {
            SessionId = started.State.SessionId,
            TransferId = started.State.TransferId,
            TransportEpoch = leg.TransportEpochId,
            RepairRequestId = "v6-regular-nkn-state-refresh:1",
            RequestCorrelationId =
                $"receive-recovery-fallback-checkpoint:{authority.OperationGeneration}:v6-regular-nkn-state-refresh:1",
            MissingRanges =
            [
                new FileTransferRangeV4
                {
                    StartChunkIndex = 7,
                    ChunkCount = 1,
                },
            ],
            Priority = "state_refresh",
            RecoveryMode = "post_tuna_fallback_state_refresh",
        };
        Assert.True(
            PostTunaFallbackPeerProofFrameIdentity.TryCreate(
                frame,
                out var frameIdentity));
        var bindingRequest =
            new FileTransferReceiveRecoveryFallbackCheckpointBindingRequest(
                authority,
                authority.Observation.CheckpointRequestId,
                leg.CheckpointGeneration,
                frame.RepairRequestId,
                leg.CheckpointGeneration + 1,
                frameIdentity,
                frame.RequestCorrelationId,
                "frng-checkpoint-child",
                frame.Priority,
                frame.TransportEpoch)
            {
                Frame = frame,
            };
        var fallback = FileTransferRouteResolver.Resolve(
            FileTransferRoute.PostTunaFallbackV6);
        var requested = FileTransferCoordinator
            .ApplyReceiveRecoveryFallbackCheckpointBinding(
            CoordinatorEvent(
                FileTransferCoordinatorEventKind.FallbackCheckpointRequested,
                fallback,
                reason: "checkpoint_requested",
                state: FileTransferLegState.CheckpointPending,
                canSendData: false,
                transportEpoch: frame.TransportEpoch,
                checkpointRequestId: frame.RepairRequestId,
                checkpointPriority: frame.Priority),
            started.State,
            bindingRequest);

        Assert.Null(requested.MutationRejectedReason);
        var recovery = FileTransferCoordinator.GetReceiveRecoverySubstate(
            requested.State);
        Assert.Equal(
            authority,
            Assert.IsType<FileTransferReceiveRecoveryOperation>(
                recovery.CurrentOperation).Authority);
        var binding =
            Assert.IsType<FileTransferReceiveRecoveryFallbackCheckpointBinding>(
                recovery.CurrentFallbackCheckpointBinding);
        Assert.Equal(
            FileTransferReceiveRecoveryFallbackCheckpointBindingState.Pending,
            binding.State);
        var answerTimeoutHold = FileTransferCoordinator
            .EvaluateRuntimeUnlockInitialActivationReceiveRecoveryHold(
                requested.State,
                answerTimeoutHoldRequest);
        Assert.Equal(
            RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus.Held,
            answerTimeoutHold.Decision.Status);
        Assert.Equal(
            authority,
            answerTimeoutHold.Decision.ReceiveRecoveryOperation?.Authority);
        Assert.NotNull(
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                    answerTimeoutHold.State)
                .CurrentInitialActivationHold);
        var command =
            Assert.IsType<FileTransferReceiveRecoveryFallbackCheckpointDeliveryCommand>(
                requested.ReceiveRecoveryFallbackCheckpointDeliveryCommand);
        var held = FileTransferCoordinator
            .ApplyReceiveRecoveryFallbackCheckpointDeliveryReceipt(
                answerTimeoutHold.State,
                new FileTransferReceiveRecoveryFallbackCheckpointDeliveryReceipt(
                    command,
                    FileTransferReceiveRecoveryFallbackCheckpointDeliveryState
                        .Held,
                    frameIdentity.Sha256,
                    "submission_barrier_closed"),
                observedUtcMs: 15);
        Assert.True(held.Accepted, held.Reason);
        Assert.Equal(
            command,
            FileTransferCoordinator.GetReceiveRecoverySubstate(held.State)
                .PendingFallbackCheckpointDeliveryCommand);

        var prematureRetirement = RetireFallbackCheckpoint(
            held.State,
            fallback,
            frame.RepairRequestId,
            frame.TransportEpoch);
        Assert.Equal(
            "filetransfer_receive_recovery_fallback_checkpoint_delivery_terminal_receipt_required",
            prematureRetirement.MutationRejectedReason);
        Assert.Equal(held.State, prematureRetirement.State);

        var completed = FileTransferCoordinator
            .ObserveReceiveRecoveryExecutionReceipt(
                held.State,
                receipt,
                observedUtcMs: 20);
        Assert.True(completed.Accepted, completed.Reason);
        var completionResume = FileTransferCoordinator
            .ReserveReceiveRecoveryFallbackCheckpointDeliveryResume(
                completed.State,
                new FileTransferReceiveRecoveryFallbackCheckpointResumeEvidence(
                    command,
                    FileTransferReceiveRecoveryFallbackCheckpointResumeTrigger
                        .RecoveryCompleted,
                    21));
        Assert.True(completionResume.Accepted, completionResume.Reason);
        Assert.Equal(
            command,
            Assert.IsType<FileTransferReceiveRecoveryFallbackCheckpointResumeReservation>(
                completionResume.FallbackCheckpointResumeReservation).Command);
        var duplicateCompletionResume = FileTransferCoordinator
            .ReserveReceiveRecoveryFallbackCheckpointDeliveryResume(
                completionResume.State,
                new FileTransferReceiveRecoveryFallbackCheckpointResumeEvidence(
                    command,
                    FileTransferReceiveRecoveryFallbackCheckpointResumeTrigger
                        .RecoveryCompleted,
                    21));
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Idempotent,
            duplicateCompletionResume.Status);
        var losingAvailabilityResume = FileTransferCoordinator
            .ReserveReceiveRecoveryFallbackCheckpointDeliveryResume(
                completionResume.State,
                new FileTransferReceiveRecoveryFallbackCheckpointResumeEvidence(
                    command,
                    FileTransferReceiveRecoveryFallbackCheckpointResumeTrigger
                        .DataSessionAvailable,
                    22));
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Idempotent,
            losingAvailabilityResume.Status);
        Assert.Equal(
            completionResume.FallbackCheckpointResumeReservation,
            losingAvailabilityResume.FallbackCheckpointResumeReservation);

        var reHeld = FileTransferCoordinator
            .ApplyReceiveRecoveryFallbackCheckpointDeliveryReceipt(
                completionResume.State,
                new FileTransferReceiveRecoveryFallbackCheckpointDeliveryReceipt(
                    command,
                    FileTransferReceiveRecoveryFallbackCheckpointDeliveryState
                        .Held,
                    frameIdentity.Sha256,
                    "submission_barrier_closed"),
                observedUtcMs: 23);
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Idempotent,
            reHeld.Status);
        Assert.Null(
            FileTransferCoordinator.GetReceiveRecoverySubstate(reHeld.State)
                .PendingFallbackCheckpointResumeReservation);
        var availabilityResume = FileTransferCoordinator
            .ReserveReceiveRecoveryFallbackCheckpointDeliveryResume(
                reHeld.State,
                new FileTransferReceiveRecoveryFallbackCheckpointResumeEvidence(
                    command,
                    FileTransferReceiveRecoveryFallbackCheckpointResumeTrigger
                        .DataSessionAvailable,
                    24));
        Assert.True(availabilityResume.Accepted, availabilityResume.Reason);
        var delivered = FileTransferCoordinator
            .ApplyReceiveRecoveryFallbackCheckpointDeliveryReceipt(
                availabilityResume.State,
                new FileTransferReceiveRecoveryFallbackCheckpointDeliveryReceipt(
                    command,
                    FileTransferReceiveRecoveryFallbackCheckpointDeliveryState
                        .Delivered,
                    frameIdentity.Sha256,
                    "checkpoint_delivered"),
                observedUtcMs: 25);
        Assert.True(delivered.Accepted, delivered.Reason);
        Assert.NotNull(
            FileTransferCoordinator.GetReceiveRecoverySubstate(delivered.State)
                .CurrentInitialActivationHold);
        Assert.Null(
            FileTransferCoordinator.GetReceiveRecoverySubstate(delivered.State)
                .PendingFallbackCheckpointDeliveryCommand);
        var deliveredRetirement = RetireFallbackCheckpoint(
            delivered.State,
            fallback,
            frame.RepairRequestId,
            frame.TransportEpoch);
        Assert.Equal(
            "filetransfer_receive_recovery_fallback_checkpoint_peer_proof_required",
            deliveredRetirement.MutationRejectedReason);
        Assert.Equal(delivered.State, deliveredRetirement.State);

        var prematureRecheck = FileTransferCoordinator
            .RecheckReceiveRecoveryFallbackCheckpointDelivery(
                delivered.State,
                new FileTransferReceiveRecoveryFallbackCheckpointResponseTimeoutObservation(
                    Assert.IsType<
                        FileTransferReceiveRecoveryFallbackCheckpointDeliveryReceipt>(
                            FileTransferCoordinator.GetReceiveRecoverySubstate(
                                    delivered.State)
                                .LastFallbackCheckpointDeliveryReceipt),
                    ResponseTimeoutMs: 100,
                    ObservedUtcMs: 124));
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Rejected,
            prematureRecheck.Status);
        Assert.Equal(
            "filetransfer_receive_recovery_fallback_checkpoint_response_timeout_not_elapsed",
            prematureRecheck.Reason);

        var deliveredReceipt = Assert.IsType<
            FileTransferReceiveRecoveryFallbackCheckpointDeliveryReceipt>(
                FileTransferCoordinator.GetReceiveRecoverySubstate(delivered.State)
                    .LastFallbackCheckpointDeliveryReceipt);
        var recheck = FileTransferCoordinator
            .RecheckReceiveRecoveryFallbackCheckpointDelivery(
                delivered.State,
                new FileTransferReceiveRecoveryFallbackCheckpointResponseTimeoutObservation(
                    deliveredReceipt,
                    ResponseTimeoutMs: 100,
                    ObservedUtcMs: 125));
        Assert.True(recheck.Accepted, recheck.Reason);
        var redelivery = Assert.IsType<
            FileTransferReceiveRecoveryFallbackCheckpointDeliveryCommand>(
                recheck.FallbackCheckpointDeliveryCommand);
        Assert.Equal(command.DeliveryGeneration + 1, redelivery.DeliveryGeneration);
        Assert.Equal(command.Binding, redelivery.Binding);
        Assert.Equal(command.Frame, redelivery.Frame);
        var duplicateRecheck = FileTransferCoordinator
            .RecheckReceiveRecoveryFallbackCheckpointDelivery(
                recheck.State,
                new FileTransferReceiveRecoveryFallbackCheckpointResponseTimeoutObservation(
                    deliveredReceipt,
                    ResponseTimeoutMs: 100,
                    ObservedUtcMs: 126));
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Idempotent,
            duplicateRecheck.Status);
        Assert.Equal(redelivery, duplicateRecheck.FallbackCheckpointDeliveryCommand);
        var redelivered = FileTransferCoordinator
            .ApplyReceiveRecoveryFallbackCheckpointDeliveryReceipt(
                duplicateRecheck.State,
                new FileTransferReceiveRecoveryFallbackCheckpointDeliveryReceipt(
                    redelivery,
                    FileTransferReceiveRecoveryFallbackCheckpointDeliveryState
                        .Delivered,
                    frameIdentity.Sha256,
                    "checkpoint_redelivered"),
                observedUtcMs: 130);
        Assert.True(redelivered.Accepted, redelivered.Reason);
        var proof = FileTransferCoordinator.ObserveReceiveRecoveryProof(
            redelivered.State,
            new FileTransferReceiveRecoveryProof(
                authority,
                "post-fallback-checkpoint-proof",
                "receive_proof_observed",
                21));
        Assert.True(proof.Accepted, proof.Reason);
        var release = Assert.IsType<
            RuntimeUnlockInitialActivationReceiveRecoveryHoldDecision>(
            proof.InitialActivationHoldDecision);
        Assert.Equal(
            RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus.Released,
            release.Status);
        var refresh = Assert.IsType<
            RuntimeUnlockInitialActivationOfferEnvelopeRefreshCommand>(
            release.EnvelopeRefreshCommand);
        Assert.Equal(
            RuntimeUnlockInitialActivationOfferEnvelopeRefreshReleaseProfile
                .PostTunaFallbackCheckpointProof,
            refresh.ReleaseProfile);
        Assert.Equal(0, refresh.ClosureGeneration);
        Assert.Equal(
            FileTransferReceiveRecoveryFallbackCheckpointBindingState.Pending,
            refresh.FallbackCheckpointBinding?.State);
        Assert.Equal(frameIdentity, refresh.FallbackCheckpointBinding?.FrameIdentity);
        var refreshReceipt =
            new RuntimeUnlockInitialActivationOfferEnvelopeRefreshReceipt(
                refresh,
                "post-fallback-successor-envelope-fingerprint",
                SecureSequence: 19,
                MessageId: "post-fallback-refresh-message-1");
        var capturedBinding = Assert.IsType<
            RuntimeUnlockInitialActivationReceiveRecoveryFallbackCheckpointBinding>(
            refresh.FallbackCheckpointBinding);
        var mutatedRefresh = refresh with
        {
            FallbackCheckpointBinding = capturedBinding with
            {
                BindingGeneration = capturedBinding.BindingGeneration + 1,
            },
        };
        var mutatedRefreshDecision = FileTransferCoordinator
            .CommitRuntimeUnlockInitialActivationOfferEnvelopeRefresh(
                proof.State,
                new RuntimeUnlockInitialActivationOfferEnvelopeRefreshReceipt(
                    mutatedRefresh,
                    "mutated-post-fallback-successor-envelope-fingerprint",
                    SecureSequence: 20,
                    MessageId: "mutated-post-fallback-refresh-message-1"));
        Assert.Equal(
            RuntimeUnlockInitialActivationOfferEnvelopeRefreshStatus.Rejected,
            mutatedRefreshDecision.Decision.Status);
        var acceptedBeforeRefresh = AcceptFallbackCheckpoint(
            proof.State,
            fallback,
            frame.RepairRequestId,
            frame.TransportEpoch,
            committedChunk: 7,
            highestObservedChunk: 7);
        Assert.Null(
            acceptedBeforeRefresh
                .ReceiveRecoveryFallbackCheckpointFrontierRequestRecheckCommand);
        var acceptFirstFrame = frame with
        {
            RepairRequestId = "v6-frontier:accept-first",
            RequestCorrelationId = "v6-frontier:accept-first:correlation",
            Priority = "frontier",
            RecoveryMode = "regular_nkn_frontier_stall",
        };
        var acceptFirstObservation = FileTransferCoordinator
            .ObserveReceiveRecoveryFallbackCheckpointFrontierRequest(
                acceptedBeforeRefresh.State,
                new FileTransferReceiveRecoveryFallbackCheckpointFrontierRequestObservation(
                    binding,
                    acceptFirstFrame,
                    FileTransferReceiveRecoveryFallbackCheckpointFrontierRequestDispatchPath
                        .NativeV6,
                    FileTransferTransportKind.RegularNkn,
                    acceptedBeforeRefresh.State.CurrentDataSessionIdentity!,
                    acceptedBeforeRefresh.State.CurrentDataSessionGeneration,
                    "frng-accept-first",
                    PostTunaFallbackPeerProofFrameIdentity.Create(
                        acceptFirstFrame),
                    ObservedUtcMs: 139));
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Rejected,
            acceptFirstObservation.Status);
        Assert.Null(
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                    acceptFirstObservation.State)
                .PendingFallbackCheckpointFrontierRequestHold);
        Assert.Null(
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                    acceptFirstObservation.State)
                .PendingFallbackCheckpointFrontierRequestRecheckCommand);
        var refreshCommittedAfterAcceptance = FileTransferCoordinator
            .CommitRuntimeUnlockInitialActivationOfferEnvelopeRefresh(
                acceptedBeforeRefresh.State,
                refreshReceipt);
        Assert.Equal(
            RuntimeUnlockInitialActivationOfferEnvelopeRefreshStatus.Accepted,
            refreshCommittedAfterAcceptance.Decision.Status);
        var refreshCommitted = FileTransferCoordinator
            .CommitRuntimeUnlockInitialActivationOfferEnvelopeRefresh(
                proof.State,
                refreshReceipt);
        Assert.Equal(
            RuntimeUnlockInitialActivationOfferEnvelopeRefreshStatus.Accepted,
            refreshCommitted.Decision.Status);
        Assert.NotNull(
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                    refreshCommitted.State)
                .CurrentOperation);

        var retainedBinding = Assert.IsType<
            FileTransferReceiveRecoveryFallbackCheckpointBinding>(
                FileTransferCoordinator.GetReceiveRecoverySubstate(
                        refreshCommitted.State)
                    .CurrentFallbackCheckpointBinding);
        var peerFrontierRequest78 = frame with
        {
            RepairRequestId = "v6-frontier:2151:78",
            RequestCorrelationId = "v6-frontier:2151:78:correlation",
            MissingRanges =
            [
                new FileTransferRangeV4
                {
                    StartChunkIndex = 7,
                    ChunkCount = 3,
                },
            ],
            Priority = "frontier",
            RecoveryMode = "regular_nkn_frontier_stall",
        };
        var held78 = FileTransferCoordinator
            .ObserveReceiveRecoveryFallbackCheckpointFrontierRequest(
                refreshCommitted.State,
                new FileTransferReceiveRecoveryFallbackCheckpointFrontierRequestObservation(
                    retainedBinding,
                    peerFrontierRequest78,
                    FileTransferReceiveRecoveryFallbackCheckpointFrontierRequestDispatchPath
                        .NativeV6,
                    FileTransferTransportKind.RegularNkn,
                    refreshCommitted.State.CurrentDataSessionIdentity!,
                    refreshCommitted.State.CurrentDataSessionGeneration,
                    "frng-peer-frontier-78",
                    PostTunaFallbackPeerProofFrameIdentity.Create(
                        peerFrontierRequest78),
                    ObservedUtcMs: 140));
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Accepted,
            held78.Status);
        var hold78 = Assert.IsType<
            FileTransferReceiveRecoveryFallbackCheckpointFrontierRequestHold>(
                held78.FallbackCheckpointFrontierRequestHold);
        var duplicate78 = FileTransferCoordinator
            .ObserveReceiveRecoveryFallbackCheckpointFrontierRequest(
                held78.State,
                hold78.Observation with { ObservedUtcMs = 141 });
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Idempotent,
            duplicate78.Status);
        Assert.Equal(hold78, duplicate78.FallbackCheckpointFrontierRequestHold);

        var peerFrontierRequest81 = peerFrontierRequest78 with
        {
            RepairRequestId = "v6-frontier:2151:81",
            RequestCorrelationId = "v6-frontier:2151:81:correlation",
        };
        var held81 = FileTransferCoordinator
            .ObserveReceiveRecoveryFallbackCheckpointFrontierRequest(
                duplicate78.State,
                new FileTransferReceiveRecoveryFallbackCheckpointFrontierRequestObservation(
                    retainedBinding,
                    peerFrontierRequest81,
                    FileTransferReceiveRecoveryFallbackCheckpointFrontierRequestDispatchPath
                        .RetainedSparseV4,
                    FileTransferTransportKind.RegularNkn,
                    refreshCommitted.State.CurrentDataSessionIdentity!,
                    refreshCommitted.State.CurrentDataSessionGeneration,
                    "frng-peer-frontier-81",
                    PostTunaFallbackPeerProofFrameIdentity.Create(
                        peerFrontierRequest81),
                    // The coordinator gate provides ordering authority. Distinct requests
                    // received in the same clock millisecond must still advance the hold.
                    ObservedUtcMs: 140));
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Accepted,
            held81.Status);
        var hold81 = Assert.IsType<
            FileTransferReceiveRecoveryFallbackCheckpointFrontierRequestHold>(
                held81.FallbackCheckpointFrontierRequestHold);
        Assert.Equal(hold78.HoldGeneration + 1, hold81.HoldGeneration);
        Assert.Equal(
            peerFrontierRequest81.RepairRequestId,
            hold81.Observation.Frame.RepairRequestId);
        var wrongReceivingTransport = FileTransferCoordinator
            .ObserveReceiveRecoveryFallbackCheckpointFrontierRequest(
                held81.State,
                hold81.Observation with
                {
                    ReceivedTransportKind =
                        FileTransferTransportKind.Tuna,
                    ObservedUtcMs = 143,
                });
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Rejected,
            wrongReceivingTransport.Status);
        var wrongReceivingDataSession = FileTransferCoordinator
            .ObserveReceiveRecoveryFallbackCheckpointFrontierRequest(
                held81.State,
                hold81.Observation with
                {
                    ReceivingDataSessionGeneration =
                        hold81.Observation.ReceivingDataSessionGeneration + 1,
                });
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Rejected,
            wrongReceivingDataSession.Status);
        Assert.Equal(held81.State, wrongReceivingDataSession.State);
        var mutated81Frame = peerFrontierRequest81 with
        {
            Priority = "backfill",
        };
        var mutated81 = FileTransferCoordinator
            .ObserveReceiveRecoveryFallbackCheckpointFrontierRequest(
                held81.State,
                hold81.Observation with
                {
                    Frame = mutated81Frame,
                    FrameIdentity =
                        PostTunaFallbackPeerProofFrameIdentity.Create(
                            mutated81Frame),
                    ObservedUtcMs = 143,
                });
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Rejected,
            mutated81.Status);
        var conflictingRequestIdFrame = peerFrontierRequest81 with
        {
            RepairRequestId = "v6-frontier:2151:81-conflict",
        };
        var conflictingRequestId = FileTransferCoordinator
            .ObserveReceiveRecoveryFallbackCheckpointFrontierRequest(
                held81.State,
                hold81.Observation with
                {
                    Frame = conflictingRequestIdFrame,
                    FrameIdentity =
                        PostTunaFallbackPeerProofFrameIdentity.Create(
                            conflictingRequestIdFrame),
                    ObservedUtcMs = 143,
                });
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Rejected,
            conflictingRequestId.Status);
        Assert.Equal(
            "filetransfer_receive_recovery_fallback_checkpoint_frontier_request_identity_mutated",
            conflictingRequestId.Reason);

        var invalidatedHeld = FileTransferCoordinator
            .InvalidateReceiveRecoveryOperation(
                held81.State,
                authority,
                "unit_test_checkpoint_frontier_hold_invalidated");
        Assert.True(invalidatedHeld.Accepted, invalidatedHeld.Reason);
        Assert.Null(
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                    invalidatedHeld.State)
                .PendingFallbackCheckpointFrontierRequestHold);
        Assert.Null(
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                    invalidatedHeld.State)
                .PendingFallbackCheckpointFrontierRequestRecheckCommand);

        var accepted = AcceptFallbackCheckpoint(
            held81.State,
            fallback,
            frame.RepairRequestId,
            frame.TransportEpoch,
            committedChunk: 7,
            highestObservedChunk: 7);
        var frontierRecheckCommand = Assert.IsType<
            FileTransferReceiveRecoveryFallbackCheckpointFrontierRequestRecheckCommand>(
                accepted
                    .ReceiveRecoveryFallbackCheckpointFrontierRequestRecheckCommand);
        Assert.Equal(hold81, frontierRecheckCommand.Hold);
        Assert.Equal(
            FileTransferReceiveRecoveryFallbackCheckpointBindingState.Accepted,
            frontierRecheckCommand.AcceptedBinding.State);
        Assert.Equal(
            peerFrontierRequest81.RepairRequestId,
            frontierRecheckCommand.Hold.Observation.Frame.RepairRequestId);
        var appliedReceipt =
            new FileTransferReceiveRecoveryFallbackCheckpointFrontierRequestRecheckReceipt(
                frontierRecheckCommand,
                FileTransferReceiveRecoveryFallbackCheckpointFrontierRequestRecheckStatus
                    .Applied,
                "frontier_recheck_dispatched",
                ObservedUtcMs: 144);
        var publication = Assert.IsType<RoutePublicationToken>(
            accepted.State.CurrentRoutePublicationToken);
        var stalePublicationReceipt = FileTransferCoordinator
            .ApplyReceiveRecoveryFallbackCheckpointFrontierRequestRecheckReceipt(
                accepted.State with
                {
                    CurrentRoutePublicationToken = publication with
                    {
                        PublicationGeneration =
                            publication.PublicationGeneration + 1,
                    },
                },
                appliedReceipt);
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Rejected,
            stalePublicationReceipt.Status);
        var staleDataSessionReceipt = FileTransferCoordinator
            .ApplyReceiveRecoveryFallbackCheckpointFrontierRequestRecheckReceipt(
                accepted.State with
                {
                    CurrentDataSessionGeneration =
                        accepted.State.CurrentDataSessionGeneration + 1,
                },
                appliedReceipt);
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Rejected,
            staleDataSessionReceipt.Status);
        var staleCheckpointReceipt = FileTransferCoordinator
            .ApplyReceiveRecoveryFallbackCheckpointFrontierRequestRecheckReceipt(
                accepted.State with
                {
                    CurrentFallbackCheckpointLease =
                        frontierRecheckCommand.AcceptedBinding.CheckpointLease,
                },
                appliedReceipt);
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Rejected,
            staleCheckpointReceipt.Status);
        var acceptedLeg = Assert.IsType<FileTransferLeg>(
            accepted.State.CurrentLeg);
        acceptedLeg.TransportEpochId++;
        var staleLegReceipt = FileTransferCoordinator
            .ApplyReceiveRecoveryFallbackCheckpointFrontierRequestRecheckReceipt(
                accepted.State,
                appliedReceipt);
        acceptedLeg.TransportEpochId--;
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Rejected,
            staleLegReceipt.Status);

        var terminalizedBeforeReceipt = FileTransferCoordinator.Apply(
            CoordinatorEvent(
                FileTransferCoordinatorEventKind.Terminalized,
                fallback,
                reason: "unit_test_checkpoint_frontier_terminalized"),
            accepted.State);
        Assert.False(terminalizedBeforeReceipt.TerminalMutationRejected);
        Assert.Null(
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                    terminalizedBeforeReceipt.State)
                .PendingFallbackCheckpointFrontierRequestHold);
        Assert.Null(
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                    terminalizedBeforeReceipt.State)
                .PendingFallbackCheckpointFrontierRequestRecheckCommand);
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Rejected,
            FileTransferCoordinator
                .ApplyReceiveRecoveryFallbackCheckpointFrontierRequestRecheckReceipt(
                    terminalizedBeforeReceipt.State,
                    appliedReceipt)
                .Status);

        var idempotentTerminal = FileTransferCoordinator
            .ApplyReceiveRecoveryFallbackCheckpointFrontierRequestRecheckReceipt(
                accepted.State,
                appliedReceipt with
                {
                    Status =
                        FileTransferReceiveRecoveryFallbackCheckpointFrontierRequestRecheckStatus
                            .Idempotent,
                });
        Assert.True(idempotentTerminal.Accepted, idempotentTerminal.Reason);
        Assert.Null(
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                    idempotentTerminal.State)
                .PendingFallbackCheckpointFrontierRequestRecheckCommand);
        Assert.Equal(
            FileTransferReceiveRecoveryFallbackCheckpointFrontierRequestRecheckStatus
                .Idempotent,
            Assert.IsType<
                FileTransferReceiveRecoveryFallbackCheckpointFrontierRequestRecheckReceipt>(
                    FileTransferCoordinator.GetReceiveRecoverySubstate(
                            idempotentTerminal.State)
                        .LastFallbackCheckpointFrontierRequestRecheckReceipt)
                .Status);
        var rejectedTerminal = FileTransferCoordinator
            .ApplyReceiveRecoveryFallbackCheckpointFrontierRequestRecheckReceipt(
                accepted.State,
                appliedReceipt with
                {
                    Status =
                        FileTransferReceiveRecoveryFallbackCheckpointFrontierRequestRecheckStatus
                            .Rejected,
                    Reason = "frontier_recheck_dispatch_rejected",
                });
        Assert.True(rejectedTerminal.Accepted, rejectedTerminal.Reason);
        Assert.Null(
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                    rejectedTerminal.State)
                .PendingFallbackCheckpointFrontierRequestRecheckCommand);
        Assert.Equal(
            FileTransferReceiveRecoveryFallbackCheckpointFrontierRequestRecheckStatus
                .Rejected,
            Assert.IsType<
                FileTransferReceiveRecoveryFallbackCheckpointFrontierRequestRecheckReceipt>(
                    FileTransferCoordinator.GetReceiveRecoverySubstate(
                            rejectedTerminal.State)
                        .LastFallbackCheckpointFrontierRequestRecheckReceipt)
                .Status);
        var recheckApplied = FileTransferCoordinator
            .ApplyReceiveRecoveryFallbackCheckpointFrontierRequestRecheckReceipt(
                accepted.State,
                appliedReceipt);
        Assert.True(recheckApplied.Accepted, recheckApplied.Reason);
        Assert.Null(
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                    recheckApplied.State)
                .PendingFallbackCheckpointFrontierRequestHold);
        Assert.Null(
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                    recheckApplied.State)
                .PendingFallbackCheckpointFrontierRequestRecheckCommand);
        var duplicateApplied = FileTransferCoordinator
            .ApplyReceiveRecoveryFallbackCheckpointFrontierRequestRecheckReceipt(
                recheckApplied.State,
                new FileTransferReceiveRecoveryFallbackCheckpointFrontierRequestRecheckReceipt(
                    frontierRecheckCommand,
                    FileTransferReceiveRecoveryFallbackCheckpointFrontierRequestRecheckStatus
                        .Applied,
                    "frontier_recheck_dispatched",
                    ObservedUtcMs: 145));
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Idempotent,
            duplicateApplied.Status);
        var terminalRecovery = FileTransferCoordinator
            .GetReceiveRecoverySubstate(recheckApplied.State);
        Assert.Null(terminalRecovery.CurrentOperation);
        Assert.Equal(
            authority,
            Assert.IsType<FileTransferReceiveRecoveryOperation>(
                terminalRecovery.LastTerminalOperation).Authority);
        Assert.Equal(
            FileTransferReceiveRecoveryFallbackCheckpointBindingState.Accepted,
            Assert.IsType<FileTransferReceiveRecoveryFallbackCheckpointBinding>(
                terminalRecovery.LastTerminalFallbackCheckpointBinding).State);
        var projectBinding = Assert.IsAssignableFrom<MethodInfo>(
            typeof(SessionFileTransferService).GetMethod(
                "FindReceiveRecoveryFallbackCheckpointBindingForDirective",
                BindingFlags.Static | BindingFlags.NonPublic));
        var projected = Assert.IsType<
            RuntimeUnlockInitialActivationReceiveRecoveryFallbackCheckpointBinding>(
                projectBinding.Invoke(
                    null,
                    [terminalRecovery, authority]));
        Assert.Equal(authority.AuthorityId, projected.ParentAuthorityId);
        Assert.Equal(
            frame.RepairRequestId,
            projected.EffectiveCheckpointRequestId);
        Assert.Equal(
            FileTransferReceiveRecoveryFallbackCheckpointBindingState.Accepted,
            projected.State);
    }

    [Fact]
    public void FileTransferReceiveRecoveryOperation_ExhaustedAfterProofDoesNotExposeClosure()
    {
        var fixture = CreateReceiveRecoveryOperationFixture();
        var authority =
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                fixture.Decision.Authority);
        var receipt = new FileTransferBridgeRecoveryExecutionReceipt(
            authority.ExecutionCommand,
            FileTransferBridgeRecoveryExecutionOutcome.Exhausted,
            "soft_then_hard",
            "bridge_recovery_execution_exhausted");
        var started =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
                fixture.Decision.State,
                new FileTransferBridgeRecoveryExecutionStartResult(
                    authority.ExecutionCommand,
                    FileTransferBridgeRecoveryExecutionStartStatus.Started,
                    "bridge_recovery_execution_started",
                    Task.FromResult(receipt)));
        var proof =
            FileTransferCoordinator.ObserveReceiveRecoveryProof(
                started.State,
                new FileTransferReceiveRecoveryProof(
                    authority,
                    "receive-proof-1",
                    "receive_proof_observed",
                    2));
        var exhausted =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
                proof.State,
                receipt);

        var recoveryState =
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                exhausted.State);
        Assert.Null(recoveryState.CurrentOperation);
        var terminal = Assert.IsType<FileTransferReceiveRecoveryOperation>(
            recoveryState.LastTerminalOperation);
        Assert.Equal(
            FileTransferReceiveRecoveryExecutionState.Exhausted,
            terminal.ExecutionState);
        Assert.Equal(
            FileTransferReceiveRecoveryClosureState.None,
            terminal.ClosureState);
    }

    [Theory]
    [InlineData(
        (int)FileTransferBridgeRecoveryExecutionOutcome.Completed,
        true)]
    [InlineData(
        (int)FileTransferBridgeRecoveryExecutionOutcome.Exhausted,
        false)]
    [InlineData(
        (int)FileTransferBridgeRecoveryExecutionOutcome.Discarded,
        false)]
    public void FileTransferReceiveRecoveryOperation_TerminalReceiptAndProofArrivalOrdersConvergeWithoutClosure(
        int outcomeValue,
        bool nonRegularV4)
    {
        var outcome =
            (FileTransferBridgeRecoveryExecutionOutcome)outcomeValue;
        var receiptFirst = nonRegularV4
            ? CreateNonRegularV4ReceiveRecoveryOperationFixture()
            : CreateReceiveRecoveryOperationFixture();
        var proofFirst = nonRegularV4
            ? CreateNonRegularV4ReceiveRecoveryOperationFixture()
            : CreateReceiveRecoveryOperationFixture();
        var receiptFirstAuthority =
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                receiptFirst.Decision.Authority);
        var proofFirstAuthority =
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                proofFirst.Decision.Authority);
        Assert.Equal(receiptFirstAuthority, proofFirstAuthority);

        var receipt = new FileTransferBridgeRecoveryExecutionReceipt(
            receiptFirstAuthority.ExecutionCommand,
            outcome,
            "soft_then_hard",
            outcome == FileTransferBridgeRecoveryExecutionOutcome.Completed
                ? "bridge_recovery_completed"
                : outcome ==
                    FileTransferBridgeRecoveryExecutionOutcome.Exhausted
                    ? "bridge_recovery_execution_exhausted"
                    : "bridge_recovery_execution_discarded");
        var receiptFirstStarted =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
                receiptFirst.Decision.State,
                new FileTransferBridgeRecoveryExecutionStartResult(
                    receiptFirstAuthority.ExecutionCommand,
                    FileTransferBridgeRecoveryExecutionStartStatus.Started,
                    "bridge_recovery_execution_started",
                    Task.FromResult(receipt)));
        Assert.True(
            receiptFirstStarted.Accepted,
            receiptFirstStarted.Reason);
        var receiptApplied =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
                receiptFirstStarted.State,
                receipt);
        Assert.True(receiptApplied.Accepted, receiptApplied.Reason);
        var proof = new FileTransferReceiveRecoveryProof(
            receiptFirstAuthority,
            "receive-proof-1",
            "receive_proof_observed",
            2);
        var receiptThenProof =
            FileTransferCoordinator.ObserveReceiveRecoveryProof(
                receiptApplied.State,
                proof);
        Assert.True(receiptThenProof.Accepted, receiptThenProof.Reason);

        var proofFirstReceipt = receipt with
        {
            Command = proofFirstAuthority.ExecutionCommand,
        };
        var proofFirstStarted =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
                proofFirst.Decision.State,
                new FileTransferBridgeRecoveryExecutionStartResult(
                    proofFirstAuthority.ExecutionCommand,
                    FileTransferBridgeRecoveryExecutionStartStatus.Started,
                    "bridge_recovery_execution_started",
                    Task.FromResult(proofFirstReceipt)));
        Assert.True(proofFirstStarted.Accepted, proofFirstStarted.Reason);
        var proofObserved =
            FileTransferCoordinator.ObserveReceiveRecoveryProof(
                proofFirstStarted.State,
                proof with { Authority = proofFirstAuthority });
        Assert.True(proofObserved.Accepted, proofObserved.Reason);
        var proofThenReceipt =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
                proofObserved.State,
                proofFirstReceipt);
        Assert.True(proofThenReceipt.Accepted, proofThenReceipt.Reason);

        var receiptFirstState =
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                receiptThenProof.State);
        var proofFirstState =
            FileTransferCoordinator.GetReceiveRecoverySubstate(
                proofThenReceipt.State);
        Assert.Null(receiptFirstState.CurrentOperation);
        Assert.Null(proofFirstState.CurrentOperation);
        Assert.Equal(
            receiptFirstState.LastTerminalOperation,
            proofFirstState.LastTerminalOperation);
        Assert.Equal(
            FileTransferReceiveRecoveryClosureState.None,
            receiptFirstState.LastTerminalOperation?.ClosureState);
        Assert.Equal(
            proof,
            receiptFirstState.LastTerminalOperation?.ReceiveProof);

        var duplicate =
            FileTransferCoordinator.ObserveReceiveRecoveryProof(
                receiptThenProof.State,
                proof);
        Assert.Equal(
            FileTransferReceiveRecoveryTransitionStatus.Idempotent,
            duplicate.Status);
        Assert.Equal(receiptThenProof.State, duplicate.State);
    }

    [Fact]
    public void FileTransferReceiveRecoveryOperation_TerminalReceiptRejectsProofAfterDataSessionReplacement()
    {
        var fixture = CreateNonRegularV4ReceiveRecoveryOperationFixture();
        var authority =
            Assert.IsType<FileTransferReceiveRecoveryOperationAuthority>(
                fixture.Decision.Authority);
        var receipt = new FileTransferBridgeRecoveryExecutionReceipt(
            authority.ExecutionCommand,
            FileTransferBridgeRecoveryExecutionOutcome.Completed,
            "soft",
            "bridge_recovery_completed");
        var started =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionStart(
                fixture.Decision.State,
                new FileTransferBridgeRecoveryExecutionStartResult(
                    authority.ExecutionCommand,
                    FileTransferBridgeRecoveryExecutionStartStatus.Started,
                    "bridge_recovery_execution_started",
                    Task.FromResult(receipt)));
        var completed =
            FileTransferCoordinator.ObserveReceiveRecoveryExecutionReceipt(
                started.State,
                receipt);
        var staleState = completed.State with
        {
            CurrentDataSessionGeneration =
                completed.State.CurrentDataSessionGeneration + 1,
        };

        var rejected =
