    [Fact]
    public void FallbackTailUnblockRecheck_ExactRepairSuccessorCarriesHeldRequestOnce()
    {
        var (pairedState, request, _) =
            AuthorizeFallbackRuntimeUnlockRetryDispatchSource();
        var predecessorDecision = FileTransferCoordinator.AuthorizeAction(
            pairedState,
            RecoveryActionRequest(
                FileTransferCoordinatorActionKind.RepairReplay,
                pairedState.CurrentRuntimeOwner!.Value,
                pairedState.CurrentLeg!,
                repairReplayKind: RepairReplayKind.FrontierStallRepair));
        Assert.True(predecessorDecision.Accepted);
        Assert.True(
            FileTransferCoordinator.TryIssueFallbackFrontierRepairAuthority(
                predecessorDecision.RepairReplayDecision!.Value,
                new FallbackFrontierRepairAuthorityRequest(
                    "fallback-frontier:12:1:frng-recheck-predecessor",
                    "frng-recheck-predecessor",
                    FrontierChunkIndex: 12,
                    DurableReceivedHighestChunkIndex: 12,
                    RangeCount: 1,
                    RequestedChunkCount: 1,
                    FallbackFrontierRepairSourceKind.PeerRequest,
                    ProtocolRepairRequestId: "v6-frontier:12:1",
                    RequestCorrelationId: "frq-recheck-predecessor",
                    CheckpointRequestId: "(none)",
                    Priority: "frontier",
                    RecoveryMode: "regular_nkn_frontier_stall_control_bulk",
                    DecisionReason: "fallback_frontier_request_received"),
                out var predecessor,
                out var predecessorReason),
            predecessorReason);

        var held = FileTransferCoordinator.AuthorizeRuntimeUnlockRetryDispatch(
            predecessorDecision.State,
            request,
            RuntimeUnlockRetryReleaseKind.Unknown,
            null,
            0,
            "pending");
        var bound = FileTransferCoordinator.BindFallbackTailYieldRetryDispatchHold(
            held.State,
            request,
            predecessor!.Value);
        Assert.True(bound.Accepted, bound.Reason);
        var original = Assert.IsType<FileTransferFallbackTailYieldRetryDispatchHold>(
            bound.State.PersistentState.FallbackTailYield
                .CurrentRetryDispatchHold);
        Assert.Null(
            bound.State.PersistentState.FallbackTailYield.CurrentReservation);

        var successorDecision = FileTransferCoordinator.AuthorizeAction(
            bound.State,
            RecoveryActionRequest(
                FileTransferCoordinatorActionKind.RepairReplay,
                bound.State.CurrentRuntimeOwner!.Value,
                bound.State.CurrentLeg!,
                repairReplayKind: RepairReplayKind.FrontierStallRepair,
                predecessorAuthorityId: predecessor.Value.AuthorityId));
        Assert.True(successorDecision.Accepted);
        Assert.True(
            FileTransferCoordinator.TryIssueFallbackFrontierRepairAuthority(
                successorDecision.RepairReplayDecision!.Value,
                new FallbackFrontierRepairAuthorityRequest(
                    "fallback-frontier:13:1:frng-recheck-successor",
                    "frng-recheck-successor",
                    FrontierChunkIndex: 13,
                    DurableReceivedHighestChunkIndex: 13,
                    RangeCount: 1,
                    RequestedChunkCount: 1,
                    FallbackFrontierRepairSourceKind.PeerRequest,
                    ProtocolRepairRequestId: "v6-frontier:13:2",
                    RequestCorrelationId: "frq-recheck-successor",
                    CheckpointRequestId: "(none)",
                    Priority: "frontier",
                    RecoveryMode: "regular_nkn_frontier_stall_control_bulk",
                    DecisionReason: "fallback_frontier_request_received"),
                out var successor,
                out var successorReason),
            successorReason);

        var rebound = FileTransferCoordinator
            .RebindFallbackTailYieldRetryDispatchHoldToRepairSuccessor(
                successorDecision.State,
                predecessor.Value,
                successor!.Value);
        Assert.True(rebound.Accepted, rebound.Reason);
        var carried = Assert.IsType<FileTransferFallbackTailYieldRetryDispatchHold>(
            rebound.State.PersistentState.FallbackTailYield
                .CurrentRetryDispatchHold);
        Assert.Equal(request, carried.Request);
        Assert.Equal(original.Release, carried.Release);
        Assert.Equal(original.DataSessionIdentity, carried.DataSessionIdentity);
        Assert.Equal(original.DataSessionGeneration, carried.DataSessionGeneration);
        Assert.Equal(successor.Value, carried.BlockingRepair);
        Assert.Equal(2, carried.HoldGeneration);
        Assert.Null(
            rebound.State.PersistentState.FallbackTailYield.CurrentReservation);

        var duplicate = FileTransferCoordinator
            .RebindFallbackTailYieldRetryDispatchHoldToRepairSuccessor(
                rebound.State,
                predecessor.Value,
                successor.Value);
        Assert.Equal(
            FileTransferFallbackTailYieldTransitionStatus.Idempotent,
            duplicate.Status);
        Assert.Equal(
            carried,
            duplicate.State.PersistentState.FallbackTailYield
                .CurrentRetryDispatchHold);

        var observation =
            new FileTransferFallbackTailYieldRetryDispatchRecheckObservation(
                carried,
                successor.Value,
                "ProgressObserved",
                SuccessorAuthorityId: null,
                ObservedUtcMs: 25_001);
        var issued = FileTransferCoordinator
            .IssueFallbackTailYieldRetryDispatchRecheck(
                duplicate.State,
                observation);
        Assert.True(issued.Accepted, issued.Reason);

        var mutatedSuccessor = successor.Value with
        {
            CheckpointRequestId = "checkpoint-mutated",
        };
        var rejected = FileTransferCoordinator
            .RebindFallbackTailYieldRetryDispatchHoldToRepairSuccessor(
                bound.State,
                predecessor.Value,
                mutatedSuccessor);
        Assert.Equal(
            FileTransferFallbackTailYieldTransitionStatus.Rejected,
            rejected.Status);
        Assert.Equal(
            "fallback_tail_retry_dispatch_hold_successor_invalid",
            rejected.Reason);
        Assert.Equal(
            original,
            rejected.State.PersistentState.FallbackTailYield
                .CurrentRetryDispatchHold);
        Assert.Null(
            rejected.State.PersistentState.FallbackTailYield.CurrentReservation);

        var transportEpochSuccessor = successor.Value with
        {
            TransportEpoch = successor.Value.TransportEpoch + 1,
        };
        var transportEpochRejected = FileTransferCoordinator
            .RebindFallbackTailYieldRetryDispatchHoldToRepairSuccessor(
                bound.State,
                predecessor.Value,
                transportEpochSuccessor);
        Assert.Equal(
            FileTransferFallbackTailYieldTransitionStatus.Rejected,
            transportEpochRejected.Status);
        Assert.Equal(
            "fallback_tail_retry_dispatch_hold_successor_invalid",
            transportEpochRejected.Reason);
        Assert.Equal(
            original,
            transportEpochRejected.State.PersistentState.FallbackTailYield
                .CurrentRetryDispatchHold);
        Assert.Null(
            transportEpochRejected.State.PersistentState.FallbackTailYield
                .CurrentReservation);

        var dataSessionReplacedState = bound.State with
        {
            CurrentDataSessionGeneration =
                bound.State.CurrentDataSessionGeneration + 1,
        };
        var dataSessionRejected = FileTransferCoordinator
            .RebindFallbackTailYieldRetryDispatchHoldToRepairSuccessor(
                dataSessionReplacedState,
                predecessor.Value,
                successor.Value);
        Assert.Equal(
            FileTransferFallbackTailYieldTransitionStatus.Rejected,
            dataSessionRejected.Status);
        Assert.Equal(
            "fallback_tail_retry_dispatch_hold_successor_scope_replaced",
            dataSessionRejected.Reason);
        Assert.Equal(
            original,
            dataSessionRejected.State.PersistentState.FallbackTailYield
                .CurrentRetryDispatchHold);

        var operation = Assert.IsType<FileTransferFallbackTailYieldOperation>(
            bound.State.PersistentState.FallbackTailYield.CurrentOperation);
        var mutatedRelease = original.Release with
        {
            PairingGeneration = original.Release.PairingGeneration + 1,
        };
        var releaseReplacedState = bound.State with
        {
            PersistentState = bound.State.PersistentState with
            {
                FallbackTailYield =
                    bound.State.PersistentState.FallbackTailYield with
                    {
                        CurrentOperation = operation with
                        {
                            PairedRelease = mutatedRelease,
                        },
                    },
            },
        };
        var releaseRejected = FileTransferCoordinator
            .RebindFallbackTailYieldRetryDispatchHoldToRepairSuccessor(
                releaseReplacedState,
                predecessor.Value,
                successor.Value);
        Assert.Equal(
            FileTransferFallbackTailYieldTransitionStatus.Rejected,
            releaseRejected.Status);
        Assert.Equal(
            "fallback_tail_retry_dispatch_hold_successor_scope_replaced",
            releaseRejected.Reason);
        Assert.Equal(
            original,
            releaseRejected.State.PersistentState.FallbackTailYield
                .CurrentRetryDispatchHold);
        Assert.Null(
            releaseRejected.State.PersistentState.FallbackTailYield
                .CurrentReservation);
    }

    [Fact]
    public void RuntimeUnlockRetryDispatchAuthority_FallbackMissingDispatchSuccessorPreservesCanonicalReleaseAcrossTransportEpoch()
    {
        var (state, request, tailYield) = AuthorizeFallbackRuntimeUnlockRetryDispatchSource();
        var first = FileTransferCoordinator.AuthorizeRuntimeUnlockRetryDispatch(
            state,
            request,
            RuntimeUnlockRetryReleaseKind.FallbackPairedTailYield,
            tailYield.AuthorityId,
            tailYield.YieldGeneration,
            tailYield.YieldKind.ToString());
        var predecessor = StageAndInstallPersistentRetryLifecycle(
            first.State,
            first,
            request,
            stagedUtcMs: 6_000_000);
        var settlement = SettlePersistentRetryMissingDispatch(
            predecessor.State,
            predecessor.Receipt.Authority.AuthorityId,
            2,
            "fallback-missing-dispatch");
        var predecessorReport =
            Assert.IsType<RuntimeUnlockRetryDispatchSettlementReport>(
                settlement.Settlement);

        var sourceTransportEpoch = settlement.State.CurrentLeg!.TransportEpochId;
        settlement.State.CurrentLeg.TransportEpochId = sourceTransportEpoch + 1;
        var successorPreparation =
            FileTransferCoordinator.PrepareRuntimeUnlockRetryDispatchSuccessor(
                settlement.State,
                predecessor.Receipt.Authority,
                retiredOfferGeneration: 2);
        Assert.True(
            successorPreparation.Status ==
                RuntimeUnlockRetryDispatchSuccessorDecisionStatus.Requested,
            successorPreparation.Reason);
        var successorRequest =
            Assert.IsType<RuntimeUnlockRetryDispatchAuthorityRequest>(
                successorPreparation.Request);
        var successor =
            Assert.IsType<RuntimeUnlockRetryDispatchDecision>(
                successorPreparation.AuthorizationDecision);

        Assert.True(successor.Granted, successor.Reason);
        var successorContract = Assert.IsType<RuntimeUnlockRetryDispatchContract>(successor.Contract);
        Assert.Equal(2, successorContract.Authority.DispatchAttemptGeneration);
        Assert.Equal(1, successorContract.Authority.MissingDispatchSuccessorGeneration);
        Assert.Equal(predecessor.Receipt.Authority.AuthorityId, successorContract.Authority.PredecessorAuthorityId);
        Assert.False(successorContract.RequestActivePredecessorSupersession);
        Assert.Equal(sourceTransportEpoch + 1, successorContract.Authority.TransportEpoch);
        Assert.Equal(predecessor.Receipt.Authority.ReleaseKind, successorContract.Authority.ReleaseKind);
        Assert.Equal(predecessor.Receipt.Authority.ReleaseAuthorityId, successorContract.Authority.ReleaseAuthorityId);
        Assert.Equal(predecessor.Receipt.Authority.ReleaseGeneration, successorContract.Authority.ReleaseGeneration);
        Assert.Equal(nameof(FallbackTailYieldKind.Quiescent), successorContract.Authority.ReleaseOutcome);

        var mutatedAuthority = successorContract.Authority with
        {
            ReleaseAuthorityId = new FileTransferAuthorityId("fta2-mutated-successor-release"),
        };
        var mutatedContract = new RuntimeUnlockRetryDispatchContract(
            mutatedAuthority,
            successorContract.RequestActivePredecessorSupersession,
            successorContract.RegularV4LivenessGeneration,
            successorContract.RequestBridgeDecisionGeneration);
        var mutatedState = successorPreparation.State;
        var mutatedDecision = successor with
        {
            Contract = mutatedContract,
            State = mutatedState,
        };
        var mutatedStage = StagePersistentRetryLifecycle(
            mutatedState,
            mutatedDecision,
            stagedUtcMs: 6_001_000);
        Assert.Equal(
            RuntimeUnlockRetryLifecycleTransitionStatus.Rejected,
            mutatedStage.Status);
        Assert.Equal(
            "retry_dispatch_stage_authority_not_pending",
            mutatedStage.Reason);

        var staged = StagePersistentRetryLifecycle(
            successorPreparation.State,
            successor,
            stagedUtcMs: 6_001_000);
        Assert.Equal(
            RuntimeUnlockRetryLifecycleTransitionStatus.Accepted,
            staged.Status);
        var stagedPredecessor =
            Assert.IsType<RuntimeUnlockRetryLifecycleAttemptSnapshot>(
                FileTransferCoordinator.GetRuntimeUnlockRetryLifecycle(
                        staged.State)
                    .InstalledAttempt);
        Assert.Equal(predecessorReport, stagedPredecessor.Settlement);
        var issuance =
            FileTransferCoordinator.IssueRuntimeUnlockRetryDispatchInstallReceipt(
                staged.State,
                successor,
                successorRequest,
                observedUtcMs: 6_001_001);
        Assert.Equal(
            RuntimeUnlockRetryLifecycleTransitionStatus.Accepted,
            issuance.Status);
        var receipt =
            Assert.IsType<RuntimeUnlockRetryDispatchInstallReceipt>(
                issuance.Receipt);
        Assert.Equal(2, receipt.InstallGeneration);
        Assert.Equal(successorContract.Authority, receipt.Authority);

        var installedSuccessor = StageAndInstallPersistentRetryLifecycle(
            successorPreparation.State,
            successor,
            successorRequest,
            stagedUtcMs: 6_001_000);
        var successorSettlement = SettlePersistentRetryMissingDispatch(
            installedSuccessor.State,
            installedSuccessor.Receipt.Authority.AuthorityId,
            offerGeneration: 3,
            offerNonce: "fallback-successor-bounded");
        var bounded =
            FileTransferCoordinator.PrepareRuntimeUnlockRetryDispatchSuccessor(
                successorSettlement.State,
                installedSuccessor.Receipt.Authority,
                retiredOfferGeneration: 3);
        Assert.Equal(
            RuntimeUnlockRetryDispatchSuccessorDecisionStatus.ChainClosed,
            bounded.Status);
        Assert.Equal("retry_dispatch_chain_closed", bounded.Reason);
        Assert.Null(bounded.State.CurrentRuntimeUnlockRetryDispatchAuthority);
    }

    [Fact]
    public void RuntimeUnlockRetryDispatchAuthority_PreOfferMissingDispatchFallbackSuccessorReusesConsumedRelease()
    {
        var (state, request, tailYield) =
            AuthorizeFallbackRuntimeUnlockRetryDispatchSource();
        request = request with { RetiredOfferGeneration = 0 };
        var first = FileTransferCoordinator.AuthorizeRuntimeUnlockRetryDispatch(
            state,
            request,
            RuntimeUnlockRetryReleaseKind.FallbackPairedTailYield,
            tailYield.AuthorityId,
            tailYield.YieldGeneration,
            tailYield.YieldKind.ToString());
        Assert.True(first.Granted, first.Reason);
        var installed = StageAndInstallPersistentRetryLifecycle(
            first.State,
            first,
            request,
            stagedUtcMs: 6_100_000);
        var consumedRelease = FileTransferCoordinator
            .GetFallbackTailYieldSubstate(installed.State)
            .LastConsumedReservation;
        Assert.NotNull(consumedRelease);

        var report = new RuntimeUnlockRetryDispatchSettlementReport(
            installed.Receipt.Authority,
            RuntimeUnlockRetryDispatchSettlementOutcome.MissingDispatch,
            "pre_offer_dispatch_missing");
        var settlement =
            FileTransferCoordinator.ObserveRuntimeUnlockRetryDispatchSettlement(
                installed.State,
                report);
        Assert.Equal(
            RuntimeUnlockRetryDispatchSettlementDecisionStatus.Accepted,
            settlement.Status);

        var evaluation = new RuntimeUnlockRetryDispatchSuccessorEvaluation(
            installed.Receipt.Authority,
            RetiredOfferGeneration: 0)
        {
            PredecessorOfferGeneration = 0,
            PredecessorOfferNonce = null,
            PredecessorDispatchObserved = false,
        };
        var successor =
            FileTransferCoordinator.PrepareRuntimeUnlockRetryDispatchSuccessor(
                settlement.State,
                evaluation);
        Assert.Equal(
            RuntimeUnlockRetryDispatchSuccessorDecisionStatus.Requested,
            successor.Status);
        var successorRequest =
            Assert.IsType<RuntimeUnlockRetryDispatchAuthorityRequest>(
                successor.Request);
        var successorDecision =
            Assert.IsType<RuntimeUnlockRetryDispatchDecision>(
                successor.AuthorizationDecision);
        var successorAuthority =
            Assert.IsType<RuntimeUnlockRetryDispatchContract>(
                successorDecision.Contract).Authority;
        Assert.Equal(0, successorRequest.RetiredOfferGeneration);
        Assert.Equal(2, successorRequest.DispatchAttemptGeneration);
        Assert.Equal(1, successorRequest.MissingDispatchSuccessorGeneration);
        Assert.Equal(
            installed.Receipt.Authority.AuthorityId,
            successorRequest.PredecessorAuthorityId);
        Assert.Equal(
            installed.Receipt.Authority.SourcePublicationAuthority,
            successorAuthority.SourcePublicationAuthority);
        Assert.Equal(
            installed.Receipt.Authority.ReleaseKind,
            successorAuthority.ReleaseKind);
        Assert.Equal(
            installed.Receipt.Authority.ReleaseAuthorityId,
            successorAuthority.ReleaseAuthorityId);
        Assert.Equal(
            installed.Receipt.Authority.ReleaseGeneration,
            successorAuthority.ReleaseGeneration);
        Assert.Equal(
            installed.Receipt.Authority.ReleaseOutcome,
            successorAuthority.ReleaseOutcome);

        var duplicate =
            FileTransferCoordinator.PrepareRuntimeUnlockRetryDispatchSuccessor(
                successor.State,
                evaluation);
        Assert.Equal(
            RuntimeUnlockRetryDispatchSuccessorDecisionStatus.Idempotent,
            duplicate.Status);
        Assert.Equal(
            successorAuthority,
            duplicate.AuthorizationDecision!.Value.Contract!.Authority);

        var installedSuccessor = StageAndInstallPersistentRetryLifecycle(
            successor.State,
            successorDecision,
            successorRequest,
            stagedUtcMs: 6_101_000);
        var fallbackState = FileTransferCoordinator
            .GetFallbackTailYieldSubstate(installedSuccessor.State);
        Assert.Equal(consumedRelease, fallbackState.LastConsumedReservation);
        Assert.Equal(
            installed.Receipt,
            fallbackState.LastConsumingInstallReceipt);
    }

    [Fact]
    [Trait("FileTransferRuntimeSuite", "RuntimeUnlockRetryLifecycle")]
    public void RuntimeUnlockRetryLifecycle_FallbackTransportEpochCarryForwardClosesBoundedChainExactlyOnce()
    {
        var (state, request, tailYield) =
            AuthorizeFallbackRuntimeUnlockRetryDispatchSource();
        var firstDecision =
            FileTransferCoordinator.AuthorizeRuntimeUnlockRetryDispatch(
                state,
                request,
                RuntimeUnlockRetryReleaseKind.FallbackPairedTailYield,
                tailYield.AuthorityId,
                tailYield.YieldGeneration,
                tailYield.YieldKind.ToString());
        var first = StageAndInstallPersistentRetryLifecycle(
            firstDecision.State,
            firstDecision,
            request,
            stagedUtcMs: 6_200_000);
        const long firstOfferGeneration = 81;
        var firstMissing = SettlePersistentRetryMissingDispatch(
            first.State,
            first.Receipt.Authority.AuthorityId,
            firstOfferGeneration,
            "fallback-carry-forward-first");

        var sourceTransportEpoch =
            firstMissing.State.CurrentLeg!.TransportEpochId;
        firstMissing.State.CurrentLeg.TransportEpochId =
            sourceTransportEpoch + 1;
        var successor =
            FileTransferCoordinator.PrepareRuntimeUnlockRetryDispatchSuccessor(
                firstMissing.State,
                first.Receipt.Authority,
                firstOfferGeneration);
        Assert.Equal(
            RuntimeUnlockRetryDispatchSuccessorDecisionStatus.Requested,
            successor.Status);
        Assert.Equal(
            sourceTransportEpoch + 1,
            successor.AuthorizationDecision!.Value.Contract!.Authority
                .TransportEpoch);

        var successorRequest =
            Assert.IsType<RuntimeUnlockRetryDispatchAuthorityRequest>(
                successor.Request);
        var installedSuccessor = StageAndInstallPersistentRetryLifecycle(
            successor.State,
            successor.AuthorizationDecision.Value,
            successorRequest,
            stagedUtcMs: 6_201_000);
        const long secondOfferGeneration = 82;
        var secondMissing = SettlePersistentRetryMissingDispatch(
            installedSuccessor.State,
            installedSuccessor.Receipt.Authority.AuthorityId,
            secondOfferGeneration,
            "fallback-carry-forward-second");

        var closed =
            FileTransferCoordinator.PrepareRuntimeUnlockRetryDispatchSuccessor(
                secondMissing.State,
                installedSuccessor.Receipt.Authority,
                secondOfferGeneration);
        Assert.Equal(
            RuntimeUnlockRetryDispatchSuccessorDecisionStatus.ChainClosed,
            closed.Status);
        var rejectedRequest =
            Assert.IsType<RuntimeUnlockRetryDispatchAuthorityRequest>(
                closed.Request);
        var closure =
            Assert.IsType<RuntimeUnlockRetryLifecycleBoundedClosure>(
                FileTransferCoordinator.GetRuntimeUnlockRetryLifecycle(
                        closed.State)
                    .BoundedClosure);
        Assert.Equal(1, closure.ClosureGeneration);
        Assert.Equal(
            installedSuccessor.Receipt.Authority,
            closure.FinalAttempt.Authority);

        var duplicate =
            FileTransferCoordinator.CloseRuntimeUnlockRetryDispatchChain(
                closed.State,
                rejectedRequest,
                "retry_dispatch_missing_successor_limit_exhausted");
        Assert.Equal(
            RuntimeUnlockRetryLifecycleTransitionStatus.Idempotent,
            duplicate.Status);
        Assert.Same(closed.State, duplicate.State);
        Assert.Equal(
            closure,
            FileTransferCoordinator.GetRuntimeUnlockRetryLifecycle(
                    duplicate.State)
                .BoundedClosure);
    }

    [Fact]
    public void RuntimeUnlockRetryDispatchAuthority_FallbackReleaseTupleRejectsSyntheticAndMutatedValues()
    {
        var (state, request, tailYield) = AuthorizeFallbackRuntimeUnlockRetryDispatchSource();

        RuntimeUnlockRetryDispatchDecision Authorize(
            FileTransferAuthorityId authorityId,
            int generation,
