        var staleLease = lease with { LegGeneration = lease.LegGeneration + 1 };
        var stale = FileTransferCoordinator.AuthorizeAction(
            stored,
            RecoveryActionRequest(
                FileTransferCoordinatorActionKind.RecoveryLivenessLeaseValidate,
                owner,
