    [Fact]
    public void FallbackTailYield_FailedOperationIsSupersededBySameScopeQuiescence()
    {
        var fallback = FileTransferRouteResolver.Resolve(
            FileTransferRoute.PostTunaFallbackV6);
        var source = ActiveFallbackStateWithoutCheckpoint() with
        {
            CurrentDataSessionIdentity = "fallback-data-session",
            CurrentDataSessionGeneration = 17,
        };
        var failed = MarkFallbackTailFailed(
            source,
            fallback,
            source.CurrentLeg!.TransportEpochId);
        var failedDecision = Assert.IsType<FallbackTailYieldDecision>(
            failed.FallbackTailYieldDecision);
        var failedOperation = Assert.IsType<
            FileTransferFallbackTailYieldOperation>(
            FileTransferCoordinator.GetFallbackTailYieldSubstate(
                    failed.State)
                .CurrentOperation);

        var peerReceipt =
            FileTransferCoordinator.CreateFallbackTailPeerProofReceipt(
                failed.State,
                CreateCoordinatorFallbackTailPeerProof(
                    failed.State,
                    failedDecision),
                "peer-proof-before-quiescence",
                3_000);
        var peerFirst =
            FileTransferCoordinator.ApplyFallbackTailPeerProofReceipt(
                failed.State,
                peerReceipt);
        Assert.True(peerFirst.Accepted, peerFirst.Reason);

        var authorized = FileTransferCoordinator.AuthorizeAction(
            peerFirst.State,
            FallbackActionRequest(
                FileTransferCoordinatorActionKind.FallbackTailQuiescent,
                peerFirst.State.CurrentRuntimeOwner!.Value,
                peerFirst.State.CurrentLeg!,
                fallbackTailYieldKind:
                    FallbackTailYieldKind.Quiescent));

        Assert.True(authorized.Accepted, authorized.RejectionReason);
        var successor = Assert.IsType<FallbackTailYieldDecision>(
            authorized.FallbackTailYieldDecision);
        Assert.Equal(
            failedDecision.YieldGeneration + 1,
            successor.YieldGeneration);
        Assert.Null(successor.PredecessorAuthorityId);
        var aggregate = FileTransferCoordinator.GetFallbackTailYieldSubstate(
            authorized.State);
        var successorOperation = Assert.IsType<
            FileTransferFallbackTailYieldOperation>(
            aggregate.CurrentOperation);
        Assert.Equal(successor, successorOperation.Decision);
        Assert.Equal(peerReceipt, successorOperation.PeerProof);
        Assert.Equal(
            FileTransferFallbackTailYieldPairingState.PeerProofObserved,
            successorOperation.PairingState);
        var binding = Assert.IsType<
            FileTransferFallbackTailFailedYieldSupersessionBinding>(
            successorOperation.FailedYieldSupersession);
        Assert.Equal(failedDecision, binding.FailedDecision);
        Assert.Equal(successor, binding.SuccessorDecision);
        Assert.True(binding.CarriedPeerProof);
        Assert.Null(aggregate.RetainedPredecessor);
        Assert.Equal(
            failedDecision,
            aggregate.LastTerminalOperation!.Value.Decision);
        Assert.Equal(
            FileTransferFallbackTailYieldPairingState.Invalidated,
            aggregate.LastTerminalOperation.Value.PairingState);
        Assert.NotEqual(
            failedOperation.Decision.AuthorityId,
            successor.AuthorityId);

        var duplicate = FileTransferCoordinator.AuthorizeAction(
            authorized.State,
            FallbackActionRequest(
                FileTransferCoordinatorActionKind.FallbackTailQuiescent,
                authorized.State.CurrentRuntimeOwner!.Value,
                authorized.State.CurrentLeg!,
                fallbackTailYieldKind:
                    FallbackTailYieldKind.Quiescent));
        Assert.True(duplicate.Accepted);
        Assert.Equal(successor, duplicate.FallbackTailYieldDecision);
        Assert.Equal(
            successor,
            FileTransferCoordinator.GetFallbackTailYieldSubstate(
                    duplicate.State)
                .CurrentOperation!.Value.Decision);
    }

    [Fact]
    public void FallbackTailYield_InitialPeerProofCarriesThroughFailedToQuiescentWithoutFailedRelease()
    {
        var fallback = FileTransferRouteResolver.Resolve(
            FileTransferRoute.PostTunaFallbackV6);
        var source = ActiveFallbackStateWithoutCheckpoint() with
        {
            CurrentDataSessionIdentity = "peer-first-failed-data-session",
            CurrentDataSessionGeneration = 19,
        };
        var preview = MarkFallbackTailFailed(
            source,
            fallback,
            source.CurrentLeg!.TransportEpochId);
        var previewDecision = Assert.IsType<FallbackTailYieldDecision>(
            preview.FallbackTailYieldDecision);
        var receipt = FileTransferCoordinator.CreateFallbackTailPeerProofReceipt(
            source,
            CreateCoordinatorFallbackTailPeerProof(
                preview.State,
                previewDecision),
            "peer-proof-before-failed-yield",
            4_000);
        var retained = FileTransferCoordinator.ApplyFallbackTailPeerProofReceipt(
            source,
            receipt);
        Assert.True(retained.Accepted, retained.Reason);

        var failed = MarkFallbackTailFailed(
            retained.State,
            fallback,
            retained.State.CurrentLeg!.TransportEpochId);
        var failedOperation = Assert.IsType<FileTransferFallbackTailYieldOperation>(
            FileTransferCoordinator.GetFallbackTailYieldSubstate(failed.State)
                .CurrentOperation);
        Assert.Equal(
            FallbackTailYieldKind.Failed,
            failedOperation.Decision.YieldKind);
        Assert.Equal(receipt, failedOperation.PeerProof);
        Assert.NotEqual(
            FileTransferFallbackTailYieldPairingState.Paired,
            failedOperation.PairingState);

        var successor = FileTransferCoordinator.AuthorizeAction(
            failed.State,
            FallbackActionRequest(
                FileTransferCoordinatorActionKind.FallbackTailQuiescent,
                failed.State.CurrentRuntimeOwner!.Value,
                failed.State.CurrentLeg!,
                fallbackTailYieldKind: FallbackTailYieldKind.Quiescent));
        Assert.True(successor.Accepted, successor.RejectionReason);
        var successorOperation = Assert.IsType<FileTransferFallbackTailYieldOperation>(
            FileTransferCoordinator.GetFallbackTailYieldSubstate(successor.State)
                .CurrentOperation);
        Assert.Equal(
            FallbackTailYieldKind.Quiescent,
            successorOperation.Decision.YieldKind);
        Assert.Equal(receipt, successorOperation.PeerProof);
        Assert.True(successorOperation.FailedYieldSupersession!.Value.CarriedPeerProof);
        Assert.Equal(
            FileTransferFallbackTailYieldPairingState.PeerProofObserved,
            successorOperation.PairingState);

        var local = FileTransferCoordinator.CreateFallbackTailLocalProofReceipt(
            successor.State,
            successorOperation.Decision,
            "local-proof-after-failed-successor",
            "local-frame-after-failed-successor",
            4_100);
        var paired = FileTransferCoordinator.ApplyFallbackTailLocalProofReceipt(
            successor.State,
            local);
        Assert.True(paired.Accepted, paired.Reason);
        Assert.NotNull(paired.PairedRelease);
    }

    [Fact]
    public void Apply_TerminalStateRejectsFallbackLegMutations()
    {
        var regular = FileTransferRouteResolver.Resolve(FileTransferRoute.RegularNknV4Fast);
        var fallback = FileTransferRouteResolver.Resolve(FileTransferRoute.PostTunaFallbackV6);
        var fallbackDecision = FallBack(StartRegular(regular).State, fallback, committedChunk: 8, transportEpoch: 4);
        var terminal = FileTransferCoordinator.Apply(
            CoordinatorEvent(FileTransferCoordinatorEventKind.Terminalized, fallback, reason: "completed"),
            fallbackDecision.State);

        var rejected = FileTransferCoordinator.Apply(
            CoordinatorEvent(
                FileTransferCoordinatorEventKind.FallbackTailQuiescent,
                fallback,
                reason: "late_tail",
                state: FileTransferLegState.Active,
                canSendData: true,
                committedChunk: 12,
                highestObservedChunk: 18,
                transportEpoch: 4),
            terminal.State);

        Assert.True(rejected.TerminalMutationRejected);
        Assert.Equal("terminal_state", rejected.MutationRejectedReason);
        Assert.Equal(terminal.State.TerminalGeneration, rejected.State.TerminalGeneration);
        Assert.Equal(FileTransferLegState.Terminal, rejected.State.CurrentLeg!.State);
    }

    [Fact]
    public void FileTransferCoordinatorSnapshot_CheckpointAndTerminalTransitionsDoNotMutatePriorGraphs()
    {
        var regular = FileTransferRouteResolver.Resolve(FileTransferRoute.RegularNknV4Fast);
        var fallback = FileTransferRouteResolver.Resolve(FileTransferRoute.PostTunaFallbackV6);
        var fallbackDecision = FallBack(
            StartRegular(regular).State,
            fallback,
            committedChunk: 8,
            transportEpoch: 4);
        var sourceState = fallbackDecision.State;
        var sourceLeg = Assert.IsType<FileTransferLeg>(sourceState.CurrentLeg);
        var sourceEpoch = Assert.IsType<LiveRouteEpoch>(sourceState.CurrentLiveRouteEpoch);
        var sourceLegState = sourceLeg.State;
        var sourceCheckpointGeneration = sourceLeg.CheckpointGeneration;
        var sourceCheckpointRequestId = sourceLeg.CheckpointRequestId;
        var sourceCheckpointPriority = sourceLeg.CheckpointPriority;
        var sourceCheckpointRequestedUtc = sourceLeg.CheckpointRequestedUtc;

        var checkpoint = RequestFallbackCheckpoint(
            sourceState,
            fallback,
            "checkpoint:snapshot",
            transportEpoch: 4);

        Assert.Null(checkpoint.MutationRejectedReason);
        Assert.Equal(sourceLegState, sourceLeg.State);
        Assert.Equal(sourceCheckpointGeneration, sourceLeg.CheckpointGeneration);
        Assert.Equal(sourceCheckpointRequestId, sourceLeg.CheckpointRequestId);
        Assert.Equal(sourceCheckpointPriority, sourceLeg.CheckpointPriority);
        Assert.Equal(sourceCheckpointRequestedUtc, sourceLeg.CheckpointRequestedUtc);
        Assert.NotSame(sourceLeg, checkpoint.State.CurrentLeg);
        Assert.NotSame(sourceEpoch, checkpoint.State.CurrentLiveRouteEpoch);
        Assert.Equal(sourceEpoch.State, checkpoint.State.CurrentLiveRouteEpoch!.State);
        Assert.Same(checkpoint.State.CurrentLeg, checkpoint.State.LegHistory[^1]);
        Assert.Equal("checkpoint:snapshot", checkpoint.State.CurrentLeg!.CheckpointRequestId);

        var checkpointLeg = checkpoint.State.CurrentLeg;
        var terminal = FileTransferCoordinator.Apply(
            CoordinatorEvent(
                FileTransferCoordinatorEventKind.Terminalized,
                fallback,
                reason: "snapshot_terminal"),
            checkpoint.State);

        Assert.True(terminal.State.IsTerminal);
        Assert.Equal(FileTransferLegState.CheckpointPending, checkpointLeg.State);
        Assert.NotSame(checkpointLeg, terminal.State.CurrentLeg);
        Assert.Equal(FileTransferLegState.Terminal, terminal.State.CurrentLeg!.State);
        Assert.Same(terminal.State.CurrentLeg, terminal.State.LegHistory[^1]);

        var rejected = FileTransferCoordinator.Apply(
            CoordinatorEvent(
                FileTransferCoordinatorEventKind.FallbackCheckpointAccepted,
                fallback,
                reason: "snapshot_stale",
                transportEpoch: 4,
                checkpointRequestId: "checkpoint:other"),
            checkpoint.State);
        Assert.NotNull(rejected.MutationRejectedReason);
        Assert.Same(checkpoint.State, rejected.State);
        Assert.Same(checkpointLeg, rejected.State.CurrentLeg);
    }

    [Fact]
    [Trait("FileTransferCoordinatorSuite", "FileTransferRouteTransition")]
    public void FileTransferRouteTransition_GenericRegularV4ProjectionHasOnePersistentOperation()
    {
        var setup = CreateRegularV4ToTunaRouteTransitionSetup();

        var prepared =
            FileTransferCoordinator.PrepareFileTransferRouteTransition(
                setup.State,
                setup.Request);

        Assert.Equal(FileTransferRouteTransitionDecisionStatus.Prepared, prepared.Status);
        var generic = Assert.IsType<FileTransferRouteTransitionOperation>(
            FileTransferCoordinator.GetFileTransferRouteTransitionSubstate(prepared.State)
                .CurrentOperation);
        Assert.Equal(
            FileTransferRouteTransitionKind.RegularV4ToTunaV4,
            generic.Authority.Kind);

        var duplicate =
            FileTransferCoordinator.PrepareFileTransferRouteTransition(
                prepared.State,
                setup.Request);
        Assert.Equal(FileTransferRouteTransitionDecisionStatus.Idempotent, duplicate.Status);
        Assert.Same(prepared.State, duplicate.State);

        var draining =
            FileTransferCoordinator.BeginFileTransferRouteTransitionPhysicalDrain(
                prepared.State,
                generic.Authority,
                new FileTransferRouteTransitionPauseBindReceipt(
                    prepared.PauseBindCommand!.Value,
                    FileTransferRouteTransitionPauseBindStatus.Installed,
                    "filetransfer_route_transition_pause_bound"),
                capturedThroughPhysicalSendGeneration: 0,
                capturedPhysicalSendLeaseIds: [],
                FileTransferCoordinator
                    .CreateFileTransferRouteTransitionPhysicalDrainFingerprint([]));
        Assert.Equal(FileTransferRouteTransitionDecisionStatus.Draining, draining.Status);
        Assert.True(
            FileTransferCoordinator.IsFileTransferRouteTransitionDraining(
                draining.State,
                out var drainingAuthority));
        Assert.Equal(generic.Authority, drainingAuthority);

        var wrongDirectionPrepare =
            FileTransferCoordinator.PrepareFileTransferRouteTransition(
                setup.State with
                {
                    Direction = FileTransferDirection.Inbound,
                },
                setup.Request);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Rejected,
            wrongDirectionPrepare.Status);

        var drainCommand = Assert.IsType<
            FileTransferRouteTransitionPhysicalDrainCommand>(
                draining.DrainCommand);
        var wrongDirectionCommit =
            FileTransferCoordinator.CommitFileTransferRouteTransition(
                draining.State with
                {
                    Direction = FileTransferDirection.Inbound,
                },
                generic.Authority,
                new FileTransferRouteTransitionPhysicalDrainReceipt(
                    drainCommand,
                    drainCommand.CapturedPhysicalSendLeaseIds,
                    drainCommand.CapturedPhysicalSendCount,
                    drainCommand.CapturedPhysicalSendFingerprint,
                    FileTransferRouteTransitionPhysicalDrainOutcome.Completed,
                    "regular_v4_wrong_direction_physical_drain_completed"),
                setup.FinalProof);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Rejected,
            wrongDirectionCommit.Status);
    }

    [Fact]
    [Trait("FileTransferCoordinatorSuite", "FileTransferRouteTransition")]
    public void FileTransferRouteTransition_InitialResponderObservationUsesOnlyRegularV4AuthorityMode()
    {
        var regular = FileTransferRouteResolver.Resolve(
            FileTransferRoute.RegularNknV4Fast);
        var inbound = StartRegular(
            regular,
            FileTransferDirection.Inbound).State with
        {
            CurrentDataSessionIdentity =
                "initial-responder-coordinator-data-session",
            CurrentDataSessionGeneration = 17,
        };
        var setup = CreateRegularV4ToTunaRouteTransitionSetup(inbound);
        var state = setup.State;
        var activation = Assert.IsType<
            FileTransferTunaActivationTransitionProofBoundary>(
                setup.Request.ProofBoundary);
        var leg = Assert.IsType<FileTransferLeg>(state.CurrentLeg);
        var receiveScope =
            new RuntimeUnlockPeerPreCommitAnswerAcceptanceScope(
                state.CurrentRuntimeOwner!.Value,
                state.CurrentRoutePublicationToken!.Value,
                state.TerminalGeneration,
                leg.Generation,
                leg.TransportEpochId,
                leg.BridgeRecoveryGeneration,
                leg.CheckpointRequestId ?? "(none)",
                leg.CheckpointGeneration,
                state.CurrentDataSessionIdentity!,
                state.CurrentDataSessionGeneration,
                activation.RuntimeUnlockAdmission,
                RuntimeUnlockResponderPeerProbeTransitionMode
                    .InitialRegularV4);
        Assert.False(receiveScope.IsDefault);
        var observation =
            new RuntimeUnlockResponderPeerProbeRouteTransitionObservation(
                state.SessionId,
                state.TransferId,
                activation.PendingPreCommitProbe.TransactionGeneration,
                activation.PendingPreCommitProbe.OfferGeneration,
                PendingAnswerAckGeneration: 7,
                PayerDecisionId: 11,
                activation.LaunchGeneration,
                Lanes: "file",
                AnswerAcceptanceSource: "SemanticAnswerAck",
                AckMessageId: "initial-responder-coordinator-answer-ack",
                AckSourceFingerprint: new string('a', 64),
                PeerProbeFrameFingerprint: new string('b', 64),
                activation.PendingPreCommitProbe.TunaPathLeaseGeneration,
                activation.PendingPreCommitProbe
                    .TunaPathLeaseListenerRunId!,
                ProbeId: setup.FinalProof.PathProbeId!,
                RuntimeUnlockPathProbeState.Acked,
                FileTransferTransportKind.Tuna,
                ProbeAckedUtcMs: setup.FinalProof.PathProbeAckedUtcMs,
                FileTransferRoute.FileTunaV4,
                FileTransferProtocol.ProtocolVersionV4,
                FileTransferTransportHandoffKind.NormalToTunaActivation,
                FileTransferTransportKind.Tuna,
                receiveScope);
        var initialBoundary = activation with
        {
            AcceptedLaunchBoundary = setup.FinalProof,
            InitialResponderPeerProbeObservation = observation,
        };
        var initialRequest = setup.Request with
        {
            ProofBoundary = initialBoundary,
        };

        var missingObservation =
            FileTransferCoordinator.PrepareFileTransferRouteTransition(
                state,
                setup.Request);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Rejected,
            missingObservation.Status);
        Assert.Same(state, missingObservation.State);

        var prepared =
            FileTransferCoordinator.PrepareFileTransferRouteTransition(
                state,
                initialRequest);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Prepared,
            prepared.Status);
        var authority = Assert.IsType<FileTransferRouteTransitionAuthority>(
            prepared.Authority);
        var emptyFingerprint = FileTransferCoordinator
            .CreateFileTransferRouteTransitionPhysicalDrainFingerprint([]);
        var draining =
            FileTransferCoordinator.BeginFileTransferRouteTransitionPhysicalDrain(
                prepared.State,
                authority,
                new FileTransferRouteTransitionPauseBindReceipt(
                    prepared.PauseBindCommand!.Value,
                    FileTransferRouteTransitionPauseBindStatus.Installed,
                    "filetransfer_route_transition_pause_bound"),
                capturedThroughPhysicalSendGeneration: 0,
                capturedPhysicalSendLeaseIds: [],
                emptyFingerprint);
        var command = Assert.IsType<
            FileTransferRouteTransitionPhysicalDrainCommand>(
                draining.DrainCommand);
        var finalProof = setup.FinalProof with
        {
            Reason = "runtime_unlock_transaction_peer_proof",
        };
        (string Name, RuntimeUnlockRouteCommitProof Proof)[] mutatedProofs =
        [
            ("session", finalProof with { SessionId = finalProof.SessionId + "-mutated" }),
            ("transfer", finalProof with { TransferId = finalProof.TransferId + "-mutated" }),
            ("transaction", finalProof with { TransactionGeneration = finalProof.TransactionGeneration + 1 }),
            ("offer", finalProof with { OfferGeneration = finalProof.OfferGeneration + 1 }),
            ("peer_visible", finalProof with { PeerVisibleProof = false }),
            ("peer_received", finalProof with { PeerReceived = false }),
            ("answer_received", finalProof with { AnswerReceived = false }),
            ("target_route", finalProof with { TargetRoute = FileTransferRoute.PostTunaFallbackV6 }),
            ("protocol", finalProof with { ProtocolVersion = FileTransferProtocol.ProtocolVersionV6 }),
            ("handoff", finalProof with { HandoffKind = FileTransferTransportHandoffKind.TunaToNormalFallback }),
            ("transport", finalProof with { TargetTransport = FileTransferTransportKind.RegularNkn }),
            ("transaction_state", finalProof with { TransactionState = RuntimeUnlockTransactionState.AnswerReceived }),
            ("probe_id", finalProof with { PathProbeId = finalProof.PathProbeId + "-mutated" }),
            ("probe_state", finalProof with { PathProbeState = RuntimeUnlockPathProbeState.Started }),
            ("probe_transport", finalProof with { PathProbeTransport = FileTransferTransportKind.RegularNkn }),
            ("probe_time", finalProof with { PathProbeAckedUtcMs = finalProof.PathProbeAckedUtcMs + 1 }),
            ("probe_failure", finalProof with { PathProbeFailureReason = "mutated" }),
            ("lease_required", finalProof with { TunaPathLeaseRequired = false }),
            ("lease_generation", finalProof with { TunaPathLeaseGeneration = finalProof.TunaPathLeaseGeneration + 1 }),
            ("lease_state", finalProof with { TunaPathLeaseState = RuntimeUnlockTunaPathLeaseState.Retired }),
            ("listener", finalProof with { TunaPathLeaseListenerRunId = finalProof.TunaPathLeaseListenerRunId + "-mutated" }),
            ("lease_current", finalProof with { TunaPathLeaseCurrent = false }),
            ("lease_failure", finalProof with { TunaPathLeaseFailureReason = "mutated" }),
            ("admission", finalProof with
            {
                AdmissionToken = finalProof.AdmissionToken!.Value with
                {
                    AdmissionGeneration =
                        finalProof.AdmissionToken.Value.AdmissionGeneration + 1,
                },
            }),
            ("same_path_ack", finalProof with { SamePathTunaProbeAckId = finalProof.SamePathTunaProbeAckId + "-mutated" }),
        ];
        foreach (var mutation in mutatedProofs)
        {
            Assert.False(
                FileTransferCoordinator.TryValidateFileTransferRouteTransitionCommitProof(
                    draining.State,
                    authority,
                    mutation.Proof,
                    out _),
                mutation.Name);
        }

        var drainReceipt =
            new FileTransferRouteTransitionPhysicalDrainReceipt(
                command,
                command.CapturedPhysicalSendLeaseIds,
                command.CapturedPhysicalSendCount,
                command.CapturedPhysicalSendFingerprint,
                FileTransferRouteTransitionPhysicalDrainOutcome.Completed,
                "initial_responder_physical_drain_completed");
        var committed =
            FileTransferCoordinator.CommitFileTransferRouteTransition(
                draining.State,
                authority,
                drainReceipt,
                finalProof);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Committed,
            committed.Status);
        var duplicate =
            FileTransferCoordinator.CommitFileTransferRouteTransition(
                committed.State,
                authority,
                drainReceipt,
                finalProof);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Idempotent,
            duplicate.Status);
        Assert.Same(committed.State, duplicate.State);

        var wrongModeObservation = observation with
        {
            PeerReceiveScope = receiveScope with
            {
                ResponderTransitionMode =
                    RuntimeUnlockResponderPeerProbeTransitionMode
                        .PostFallbackV6Paired,
            },
        };
        var wrongModeRequest = setup.Request with
        {
            ProofBoundary = initialBoundary with
            {
                InitialResponderPeerProbeObservation = wrongModeObservation,
            },
        };
        var wrongMode =
            FileTransferCoordinator.PrepareFileTransferRouteTransition(
                state,
                wrongModeRequest);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Rejected,
            wrongMode.Status);

        var mixedAuthorityRequest = setup.Request with
        {
            ProofBoundary = initialBoundary with
            {
                FallbackTailPairedReleaseReceipt = default(
                    FileTransferFallbackTailPairedReleaseReceipt),
            },
        };
        var mixedAuthority =
            FileTransferCoordinator.PrepareFileTransferRouteTransition(
                state,
                mixedAuthorityRequest);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Rejected,
            mixedAuthority.Status);
    }

    [Fact]
    public void FallbackTailYield_RejectedProbeSupersedesConsumedPairForFreshQuiescentCycle()
    {
        var (state, request, predecessor) =
            AuthorizeFallbackRuntimeUnlockRetryDispatchSource();
        var granted = FileTransferCoordinator.AuthorizeRuntimeUnlockRetryDispatch(
            state,
            request,
            RuntimeUnlockRetryReleaseKind.FallbackPairedTailYield,
            predecessor.AuthorityId,
            predecessor.YieldGeneration,
            predecessor.YieldKind.ToString());
        Assert.True(granted.Granted, granted.Reason);
        var staged = StagePersistentRetryLifecycle(granted.State, granted, 30_000);
        var issuance = FileTransferCoordinator
            .IssueRuntimeUnlockRetryDispatchInstallReceipt(
                staged.State,
                granted,
                request,
                30_001);
        var receipt = Assert.IsType<RuntimeUnlockRetryDispatchInstallReceipt>(
            issuance.Receipt);
        var committed = FileTransferCoordinator
            .CommitRuntimeUnlockRetryDispatchInstall(
                issuance.State,
                new RuntimeUnlockRetryDispatchInstallResult(
                    RuntimeUnlockRetryDispatchInstallStatus.Installed,
                    "installed",
                    receipt),
                30_002);
        var consumed = FileTransferCoordinator.GetFallbackTailYieldSubstate(
            committed.State);
        var operation = Assert.IsType<FileTransferFallbackTailYieldOperation>(
            consumed.CurrentOperation);
        var release = Assert.IsType<FileTransferFallbackTailPairedReleaseReceipt>(
            operation.PairedRelease);

        var superseded = FileTransferCoordinator
            .SupersedeFallbackTailPairedYieldAfterRejectedProbe(
                committed.State,
                FileTransferFallbackTailRetryCycleSupersessionRole.Initiator,
                predecessor,
                release,
                receipt,
                "pressure_rejected_precommit_probe_rollback");

        Assert.Equal(
            FileTransferFallbackTailYieldTransitionStatus.Accepted,
            superseded.Status);
        Assert.True(
            FileTransferCoordinator.IsFallbackTailRetryCycleSupersessionPending(
                superseded.State));
        var successor = MarkFallbackTailQuiescent(
            superseded.State,
            superseded.State.RouteSelection,
            superseded.State.CurrentLeg!.TransportEpochId,
            superseded.State.CurrentLeg.ProvenCommittedChunkIndex,
            superseded.State.CurrentLeg.ProvenHighestObservedChunkIndex);
        Assert.Null(successor.MutationRejectedReason);
        var successorDecision = Assert.IsType<FallbackTailYieldDecision>(
            successor.FallbackTailYieldDecision);
        Assert.Equal(predecessor.AuthorityId, successorDecision.PredecessorAuthorityId);
        Assert.True(successorDecision.YieldGeneration > predecessor.YieldGeneration);
        Assert.False(
            FileTransferCoordinator.IsFallbackTailRetryCycleSupersessionPending(
                successor.State));
        var staleCallback = FileTransferCoordinator
            .SupersedeFallbackTailPairedYieldAfterRejectedProbe(
                successor.State,
                FileTransferFallbackTailRetryCycleSupersessionRole.Initiator,
                predecessor,
                release,
                receipt,
                "pressure_rejected_precommit_probe_rollback");
        Assert.Equal(
            FileTransferFallbackTailYieldTransitionStatus.Rejected,
            staleCallback.Status);
        Assert.Same(successor.State, staleCallback.State);
    }

