    [Fact]
    public void FallbackTailYield_SidecarFailureCarriesEarlySuccessorPeerProofIntoExactNewCycle()
    {
        var (state, _, predecessor) =
            AuthorizeFallbackRuntimeUnlockRetryDispatchSource();
        var operation = Assert.IsType<FileTransferFallbackTailYieldOperation>(
            FileTransferCoordinator.GetFallbackTailYieldSubstate(state)
                .CurrentOperation);
        var release = Assert.IsType<FileTransferFallbackTailPairedReleaseReceipt>(
            operation.PairedRelease);
        var scope = FileTransferCoordinator.GetEffectiveFallbackTailYieldScope(
            operation);
        var peerProof = release.PeerProof.Proof with
        {
            AuthorityId = new FileTransferAuthorityId(
                "fta2-fallback_tail_yield-fedcba9876543210fedcba98"),
            PredecessorAuthorityId = release.PeerProof.Proof.AuthorityId,
            YieldGeneration = release.PeerProof.Proof.YieldGeneration + 1,
        };
        var earlyReceipt =
            new FileTransferFallbackTailPeerProofReceipt(
                peerProof,
                scope,
                "retry-cycle-successor-proof-before-local-supersession",
                40_000);

        var retained = FileTransferCoordinator.ApplyFallbackTailPeerProofReceipt(
            state,
            earlyReceipt);
        Assert.Equal(
            FileTransferFallbackTailYieldTransitionStatus.Accepted,
            retained.Status);
        Assert.Equal(
            earlyReceipt,
            FileTransferCoordinator.GetFallbackTailYieldSubstate(retained.State)
                .PendingRetryCycleSuccessorPeerProof);
        Assert.Equal(
            operation,
            FileTransferCoordinator.GetFallbackTailYieldSubstate(retained.State)
                .CurrentOperation);

        var superseded = FileTransferCoordinator
            .SupersedeFallbackTailPairedYieldAfterRejectedProbe(
                retained.State,
                FileTransferFallbackTailRetryCycleSupersessionRole.Responder,
                predecessor,
                release,
                expectedInstallReceipt: null,
                "sidecar_failed_precommit_probe_rollback");
        Assert.Equal(
            FileTransferFallbackTailYieldTransitionStatus.Accepted,
            superseded.Status);
        Assert.True(
            FileTransferCoordinator.IsFallbackTailRetryCycleSupersessionPending(
                superseded.State));

        var successor = MarkFallbackTailQuiescent(
            superseded.State,
            superseded.State.RouteSelection,
            superseded.State.CurrentLeg!.TransportEpochId,
            superseded.State.CurrentLeg.ProvenCommittedChunkIndex,
            superseded.State.CurrentLeg.ProvenHighestObservedChunkIndex);
        var successorOperation =
            Assert.IsType<FileTransferFallbackTailYieldOperation>(
                FileTransferCoordinator.GetFallbackTailYieldSubstate(
                        successor.State)
                    .CurrentOperation);
        Assert.Equal(
            predecessor.AuthorityId,
            successorOperation.Decision.PredecessorAuthorityId);
        Assert.Equal(
            FileTransferFallbackTailYieldPairingState.PeerProofObserved,
            successorOperation.PairingState);
        Assert.Equal(earlyReceipt, successorOperation.PeerProof);
        Assert.Null(
            FileTransferCoordinator.GetFallbackTailYieldSubstate(successor.State)
                .PendingRetryCycleSuccessorPeerProof);
    }

    [Fact]
    [Trait("FileTransferCoordinatorSuite", "FileTransferRouteTransition")]
    public void FileTransferRouteTransition_TunaFallbackCommitsAndAppliesRetainedFrameOnce()
    {
        var setup = CreateRegularV4ToTunaRouteTransitionSetup();
        var activationPrepared =
            FileTransferCoordinator.PrepareFileTransferRouteTransition(
                setup.State,
                setup.Request);
        var activationAuthority = activationPrepared.Authority!.Value;
        var emptyFingerprint =
            FileTransferCoordinator
                .CreateFileTransferRouteTransitionPhysicalDrainFingerprint([]);
        var activationDraining =
            FileTransferCoordinator.BeginFileTransferRouteTransitionPhysicalDrain(
                activationPrepared.State,
                activationAuthority,
                new FileTransferRouteTransitionPauseBindReceipt(
                    activationPrepared.PauseBindCommand!.Value,
                    FileTransferRouteTransitionPauseBindStatus.Installed,
                    "filetransfer_route_transition_pause_bound"),
                capturedThroughPhysicalSendGeneration: 0,
                capturedPhysicalSendLeaseIds: [],
                emptyFingerprint);
        var activationDrain = activationDraining.DrainCommand!.Value;
        var activationCommitted =
            FileTransferCoordinator.CommitFileTransferRouteTransition(
                activationDraining.State,
                activationAuthority,
                new FileTransferRouteTransitionPhysicalDrainReceipt(
                    activationDrain,
                    activationDrain.CapturedPhysicalSendLeaseIds,
                    activationDrain.CapturedPhysicalSendCount,
                    activationDrain.CapturedPhysicalSendFingerprint,
                    FileTransferRouteTransitionPhysicalDrainOutcome.Completed,
                    "physical_drain_completed"),
                setup.FinalProof);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Committed,
            activationCommitted.Status);
        Assert.Equal(
            FileTransferRoute.FileTunaV4,
            activationCommitted.State.RouteSelection.Route);
        Assert.Equal(
            "recovered",
            activationCommitted.State.CurrentLiveRouteEpoch!.State);

        var activationDisposition =
            Assert.IsType<FileTransferRouteTransitionDispositionCommand>(
                activationCommitted.DispositionCommand);
        var tunaState = FileTransferCoordinator
            .ApplyFileTransferRouteTransitionDispositionReceipt(
                activationCommitted.State,
                new FileTransferRouteTransitionDispositionReceipt(
                    activationDisposition,
                    FileTransferRouteTransitionDispositionApplyStatus.Applied,
                    "filetransfer_route_transition_committed"))
            .State;
        var tunaOwner = tunaState.CurrentRuntimeOwner!.Value;
        var tunaPublication = tunaState.CurrentRoutePublicationToken!.Value;
        var tunaCommit = tunaState.CurrentRouteCommit!.Value;
        var tunaLeg = tunaState.CurrentLeg!;
        var targetEpoch = Math.Max(1, tunaLeg.TransportEpochId + 1);
        var frameIdentity = new PostTunaFallbackPeerProofFrameIdentity(
            "filetransfer_receiver_state_v6",
            targetEpoch,
            new string('a', 64));
        var peerProof = new PostTunaFallbackPeerProofEvidence(
            tunaState.SessionId,
            tunaState.TransferId,
            tunaState.Direction,
            ProofGeneration: 1,
            TransportEpoch: targetEpoch,
            ProofKind: "fallback_peer_state",
            Reason: "peer_fallback_proof",
            FrameIdentity: frameIdentity);
        var fallbackBoundary = new FileTransferFallbackTransitionProofBoundary(
            tunaCommit,
            peerProof,
            frameIdentity,
            targetEpoch,
            TargetBridgeRecoveryGeneration:
                Math.Max(1, tunaLeg.BridgeRecoveryGeneration + 1));
        var fallbackCheckpoint = new FileTransferRouteTransitionDurableCheckpoint(
            tunaOwner,
            tunaPublication,
            tunaState.TerminalGeneration,
            tunaLeg.Generation,
            tunaLeg.TransportEpochId,
            tunaLeg.BridgeRecoveryGeneration,
            DataSessionGeneration: 17,
            StateEpoch: 4,
            ContiguousCommittedChunkIndex: 4,
            DurableHighestChunkIndex: 6,
            ChunkCount: 128,
            CheckpointGeneration: 2);
        var fallbackRequest = new FileTransferRouteTransitionPrepareRequest(
            FileTransferRouteTransitionKind.TunaV4ToPostTunaFallbackV6,
            tunaOwner,
            tunaPublication,
            tunaCommit,
            FileTransferRoute.FileTunaV4,
            FileTransferProtocol.ProtocolVersionV4,
            FileTransferTransportKind.Tuna,
            fallbackBoundary,
            fallbackCheckpoint,
            FileTransferRoute.PostTunaFallbackV6,
            FileTransferProtocol.ProtocolVersionV6,
            FileTransferTransportKind.RegularNkn,
            FileTransferTransportHandoffKind.TunaToNormalFallback,
            PredecessorTransitionAuthorityId: null,
            "peer_fallback_proof");
        var fallbackPrepared =
            FileTransferCoordinator.PrepareFileTransferRouteTransition(
                tunaState,
                fallbackRequest);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Prepared,
            fallbackPrepared.Status);
        Assert.Equal(tunaOwner, fallbackPrepared.State.CurrentRuntimeOwner);
        Assert.Equal(tunaPublication, fallbackPrepared.State.CurrentRoutePublicationToken);

        var fallbackAuthority = fallbackPrepared.Authority!.Value;
        var fallbackDraining =
            FileTransferCoordinator.BeginFileTransferRouteTransitionPhysicalDrain(
                fallbackPrepared.State,
                fallbackAuthority,
                new FileTransferRouteTransitionPauseBindReceipt(
                    fallbackPrepared.PauseBindCommand!.Value,
                    FileTransferRouteTransitionPauseBindStatus.Installed,
                    "filetransfer_route_transition_pause_bound"),
                capturedThroughPhysicalSendGeneration: 0,
                capturedPhysicalSendLeaseIds: [],
                emptyFingerprint);
        var fallbackDrain = fallbackDraining.DrainCommand!.Value;
        var fallbackReceipt = new FileTransferRouteTransitionPhysicalDrainReceipt(
            fallbackDrain,
            fallbackDrain.CapturedPhysicalSendLeaseIds,
            fallbackDrain.CapturedPhysicalSendCount,
            fallbackDrain.CapturedPhysicalSendFingerprint,
            FileTransferRouteTransitionPhysicalDrainOutcome.Completed,
            "physical_drain_completed");
        var fallbackCommitted =
            FileTransferCoordinator.CommitFileTransferRouteTransition(
                fallbackDraining.State,
                fallbackAuthority,
                fallbackReceipt);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Committed,
            fallbackCommitted.Status);
        Assert.Equal(
            FileTransferRoute.PostTunaFallbackV6,
            fallbackCommitted.State.RouteSelection.Route);
        Assert.Equal(
            "started",
            fallbackCommitted.State.CurrentLiveRouteEpoch!.State);
        Assert.Null(fallbackCommitted.State.CurrentRouteCommit);
        var fallbackLeg = Assert.IsType<FileTransferLeg>(
            fallbackCommitted.State.CurrentLeg);
        Assert.Equal(
            FileTransferLegState.CheckpointPending,
            fallbackLeg.State);
        Assert.False(fallbackLeg.CanSendData);
        Assert.Equal(
            $"v6-regular-nkn-state-refresh:route-transition:{fallbackAuthority.TransitionGeneration}:{targetEpoch}",
            fallbackLeg.CheckpointRequestId);
        Assert.Equal("state_refresh", fallbackLeg.CheckpointPriority);
        var fallbackCheckpointLease = Assert.IsType<FallbackCheckpointLease>(
            fallbackCommitted.State.CurrentFallbackCheckpointLease);
        Assert.Equal(
            fallbackCommitted.RouteDecision!.FallbackCheckpointLease,
            fallbackCheckpointLease);
        Assert.Equal(fallbackLeg.Generation, fallbackCheckpointLease.LegGeneration);
        Assert.Equal(targetEpoch, fallbackCheckpointLease.TransportEpoch);
        Assert.Equal(
            fallbackBoundary.TargetBridgeRecoveryGeneration,
            fallbackCheckpointLease.BridgeRecoveryGeneration);
        Assert.Equal(
            fallbackLeg.CheckpointGeneration,
            fallbackCheckpointLease.CheckpointGeneration);
        Assert.Equal(
            fallbackLeg.CheckpointRequestId,
            fallbackCheckpointLease.CheckpointRequestId);
        Assert.True(
            FileTransferCoordinator.IsFallbackCheckpointLeaseCurrent(
                fallbackCommitted.State,
                fallbackCheckpointLease,
                out var checkpointLeaseReason),
            checkpointLeaseReason);
        Assert.True(
            FileTransferCoordinator.IsFileTransferRouteTransitionDispositionCommandValid(
                fallbackCommitted.DispositionCommand!.Value));
        var frameCommand = Assert.IsType<
            FileTransferRouteTransitionRetainedFrameApplyCommand>(
            fallbackCommitted.RetainedFrameApplyCommand);
        Assert.True(
            FileTransferCoordinator
                .IsFileTransferRouteTransitionRetainedFrameApplyCommandValid(
                    frameCommand));

        var applied = FileTransferCoordinator.ApplyFileTransferRouteTransitionRetainedFrameReceipt(
            fallbackCommitted.State,
            new FileTransferRouteTransitionRetainedFrameApplyReceipt(
                frameCommand,
                FileTransferRouteTransitionRetainedFrameApplyStatus.Applied,
                "filetransfer_route_transition_retained_frame_applied"));
        Assert.Equal(FileTransferRouteTransitionDecisionStatus.Committed, applied.Status);
        var duplicateCommit = FileTransferCoordinator.CommitFileTransferRouteTransition(
            applied.State,
            fallbackAuthority,
            fallbackReceipt);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Idempotent,
            duplicateCommit.Status);
        Assert.Same(applied.State, duplicateCommit.State);
        Assert.Equal(
            fallbackCheckpointLease,
            duplicateCommit.State.CurrentFallbackCheckpointLease);

        var duplicateFrame =
            FileTransferCoordinator.ApplyFileTransferRouteTransitionRetainedFrameReceipt(
                applied.State,
                new FileTransferRouteTransitionRetainedFrameApplyReceipt(
                    frameCommand,
                    FileTransferRouteTransitionRetainedFrameApplyStatus.Idempotent,
                    "filetransfer_route_transition_retained_frame_apply_idempotent"));
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Idempotent,
            duplicateFrame.Status);
        Assert.Same(applied.State, duplicateFrame.State);
    }

    [Fact]
    [Trait("FileTransferCoordinatorSuite", "FileTransferRouteTransition")]
    public void FileTransferFallbackV6ProofBootstrap_IsOneShotAndDoesNotMutateTunaRoute()
    {
        var regular = FileTransferRouteResolver.Resolve(
            FileTransferRoute.RegularNknV4Fast);
        var tunaState = ActivateTuna(
            StartRegular(regular).State,
            FileTransferRouteResolver.Resolve(FileTransferRoute.FileTunaV4),
            committedChunk: 4).State;
        var tuna = tunaState with
        {
            CurrentDataSessionIdentity = "fallback-bootstrap-data-session",
            CurrentDataSessionGeneration = 17,
            PersistentState = tunaState.PersistentState with
            {
                CoordinatorInstanceId = "fallback-bootstrap-coordinator",
            },
        };
        var owner = tuna.CurrentRuntimeOwner!.Value;
        var publication = tuna.CurrentRoutePublicationToken!.Value;
        var commit = tuna.CurrentRouteCommit!.Value;
        var leg = tuna.CurrentLeg!;
        var checkpoint = new FileTransferRouteTransitionDurableCheckpoint(
            owner,
            publication,
            tuna.TerminalGeneration,
            leg.Generation,
            leg.TransportEpochId,
            leg.BridgeRecoveryGeneration,
            tuna.CurrentDataSessionGeneration,
            StateEpoch: 9,
            ContiguousCommittedChunkIndex: 8,
            DurableHighestChunkIndex: 7,
            ChunkCount: 128,
            CheckpointGeneration: 2);
        var observation = new FileTransferFallbackV6ProofBootstrapObservation(
            tuna.SessionId,
            tuna.TransferId,
            tuna.Direction,
            ObservationGeneration: 1,
            FallbackEpoch: 1,
            Source: "header_switch_off",
            ProofKind: "file_transfer_v4_state_frame_received",
            ObservedUtcMilliseconds: 10_000,
            checkpoint);

        var issued =
            FileTransferCoordinator.IssueFileTransferFallbackV6ProofBootstrap(
                tuna,
                observation);
        Assert.Equal(
            FileTransferFallbackV6ProofBootstrapDecisionStatus.Issued,
            issued.Status);
        Assert.NotNull(issued.SnapshotEnvelope);
        Assert.Equal(1, issued.State.PersistentState.SnapshotStateGeneration);
        var command = Assert.IsType<FileTransferFallbackV6ProofBootstrapCommand>(
            issued.Command);
        Assert.Equal(FileTransferRoute.FileTunaV4, issued.State.RouteSelection.Route);
        Assert.Equal(owner, issued.State.CurrentRuntimeOwner);
        Assert.Equal(publication, issued.State.CurrentRoutePublicationToken);
        Assert.Equal(commit, issued.State.CurrentRouteCommit);
        Assert.Equal(leg.Generation, issued.State.CurrentLeg!.Generation);
        Assert.True(command.TargetTransportEpoch > leg.TransportEpochId);

        var duplicate =
            FileTransferCoordinator.IssueFileTransferFallbackV6ProofBootstrap(
                issued.State,
                observation);
        Assert.Equal(
            FileTransferFallbackV6ProofBootstrapDecisionStatus.Idempotent,
            duplicate.Status);
        Assert.Equal(command, duplicate.Command);
        Assert.Equal(issued.State, duplicate.State);
        Assert.NotNull(duplicate.SnapshotEnvelope);
        Assert.Equal(1, duplicate.State.PersistentState.SnapshotStateGeneration);

        var identity = new PostTunaFallbackPeerProofFrameIdentity(
            command.FrameKind ==
                FileTransferFallbackV6ProofBootstrapFrameKind.ReceiverState
                    ? FileTransferProtocol.ReceiverStateFrameTypeV6
                    : FileTransferProtocol.FrontierRequestFrameTypeV6,
            command.TargetTransportEpoch,
            new string('b', 64));
        var receipt = new FileTransferFallbackV6ProofBootstrapReceipt(
            command,
            FileTransferFallbackV6ProofBootstrapReceiptStatus.Delivered,
            identity,
            "filetransfer_fallback_v6_proof_bootstrap_delivered");
        var heldReceipt = new FileTransferFallbackV6ProofBootstrapReceipt(
            command,
            FileTransferFallbackV6ProofBootstrapReceiptStatus.Held,
            null,
            "filetransfer_fallback_v6_proof_bootstrap_data_session_unavailable");
        var held =
            FileTransferCoordinator.ApplyFileTransferFallbackV6ProofBootstrapReceipt(
                issued.State,
                heldReceipt);
        Assert.Equal(
            FileTransferFallbackV6ProofBootstrapDecisionStatus.Applied,
            held.Status);
        Assert.NotNull(held.SnapshotEnvelope);
        Assert.Equal(2, held.State.PersistentState.SnapshotStateGeneration);
        Assert.Equal(
            command,
            FileTransferCoordinator
                .GetCurrentHeldFileTransferFallbackV6ProofBootstrapCommand(
                    held.State));

        var duplicateHeld =
            FileTransferCoordinator.ApplyFileTransferFallbackV6ProofBootstrapReceipt(
                held.State,
                heldReceipt);
        Assert.Equal(
            FileTransferFallbackV6ProofBootstrapDecisionStatus.Idempotent,
            duplicateHeld.Status);
        Assert.Equal(held.State, duplicateHeld.State);
        Assert.Equal(2, duplicateHeld.State.PersistentState.SnapshotStateGeneration);

        var applied =
            FileTransferCoordinator.ApplyFileTransferFallbackV6ProofBootstrapReceipt(
                held.State,
                receipt);
        Assert.Equal(
            FileTransferFallbackV6ProofBootstrapDecisionStatus.Applied,
            applied.Status);
        Assert.NotNull(applied.SnapshotEnvelope);
        Assert.Equal(3, applied.State.PersistentState.SnapshotStateGeneration);
        var appliedBootstrap = Assert.Single(
            applied.SnapshotEnvelope!.Aggregate.Operations,
            operation => operation.OperationRole == "fallback_v6_bootstrap");
        Assert.Equal(
            $"route_transition|fallback_v6_bootstrap|" +
            $"{appliedBootstrap.AuthorityId}|" +
            $"{appliedBootstrap.OperationGeneration}|" +
            $"{appliedBootstrap.OperationKind}",
            appliedBootstrap.OperationKey);
        Assert.NotNull(appliedBootstrap.RouteTransition);
        Assert.Equal(
            "post_tuna_fallback_v6",
            appliedBootstrap.RouteTransition!.TargetBoundary.Route);
        Assert.Equal(
            "fallback_v6_proof_bootstrap",
            appliedBootstrap.RouteTransition.ProofAdmissionMode);
        Assert.Equal("Delivered", appliedBootstrap.ReceiptStatus);
        Assert.True(appliedBootstrap.ReceiptValidated);
        Assert.Null(
            FileTransferCoordinator.GetFileTransferRouteTransitionSubstate(
                    applied.State)
                .PendingFallbackV6ProofBootstrap);
        Assert.Equal(receipt,
            FileTransferCoordinator.GetFileTransferRouteTransitionSubstate(
                    applied.State)
                .LastFallbackV6ProofBootstrapReceipt);
        Assert.Equal(FileTransferRoute.FileTunaV4, applied.State.RouteSelection.Route);

        var newerObservationSameFallback =
            FileTransferCoordinator.IssueFileTransferFallbackV6ProofBootstrap(
                applied.State,
                observation with
                {
                    ObservationGeneration = 2,
                    ObservedUtcMilliseconds = 10_001,
                });
        Assert.Equal(
            FileTransferFallbackV6ProofBootstrapDecisionStatus.Idempotent,
            newerObservationSameFallback.Status);
        Assert.Null(newerObservationSameFallback.Command);
        Assert.Equal(receipt, newerObservationSameFallback.Receipt);
        Assert.Equal(applied.State, newerObservationSameFallback.State);

        var duplicateReceipt =
            FileTransferCoordinator.ApplyFileTransferFallbackV6ProofBootstrapReceipt(
                applied.State,
                receipt);
        Assert.Equal(
            FileTransferFallbackV6ProofBootstrapDecisionStatus.Idempotent,
            duplicateReceipt.Status);
        Assert.Equal(applied.State, duplicateReceipt.State);
    }

    [Fact]
    [Trait("FileTransferCoordinatorSuite", "FileTransferRouteTransition")]
    public void FileTransferFallbackV6ProofBootstrapPeerBoundary_IsReadOnlyExactAndReciprocal()
    {
        var outbound = IssueFallbackV6ProofBootstrapForPeerBoundary(
            FileTransferDirection.Outbound);
        var outboundCommand = Assert.IsType<
            FileTransferFallbackV6ProofBootstrapCommand>(outbound.Command);
        var receiverState = new FileTransferReceiverStateFrameV6
        {
            SessionId = outbound.State.SessionId,
            TransferId = outbound.State.TransferId,
            Epoch = 10,
            ContiguousCommittedChunkIndex = 8,
            DurableReceivedHighestChunkIndex = 7,
            CreditUntilChunkIndexExclusive = 8,
            MissingRanges = [],
            BytesCommitted = 8 * 1024,
            TransferPaused = true,
            TransferPauseReason =
                FileTransferProtocol.FallbackV6ProofBootstrapRecoveryMode,
            TransportEpoch = outboundCommand.TargetTransportEpoch,
            Priority = FileTransferProtocol.FallbackV6ProofBootstrapPriority,
            RecoveryMode =
                FileTransferProtocol.FallbackV6ProofBootstrapRecoveryMode,
        };

        Assert.True(
            FileTransferCoordinator
                .TryGetCurrentFileTransferFallbackV6ProofBootstrapPeerBoundary(
                    outbound.State,
                    receiverState,
                    out var pendingBoundary,
                    out var pendingReason));
        Assert.Equal(outboundCommand, pendingBoundary);
        Assert.Equal("exact_bootstrap_boundary", pendingReason);
        Assert.False(
            FileTransferCoordinator
                .TryGetCurrentFileTransferFallbackV6ProofBootstrapPeerProofBoundary(
                    outbound.State,
                    receiverState,
                    out _,
                    out var pendingProofReason));
        Assert.Equal("bootstrap_local_delivery_pending", pendingProofReason);
        Assert.Equal(
            outboundCommand,
            FileTransferCoordinator
                .GetCurrentFileTransferFallbackV6ProofBootstrapBoundary(
                    outbound.State));

        var held = FileTransferCoordinator.ApplyFileTransferFallbackV6ProofBootstrapReceipt(
            outbound.State,
            new FileTransferFallbackV6ProofBootstrapReceipt(
                outboundCommand,
                FileTransferFallbackV6ProofBootstrapReceiptStatus.Held,
                null,
                "filetransfer_fallback_v6_proof_bootstrap_data_session_unavailable"));
        Assert.True(
            FileTransferCoordinator
                .TryGetCurrentFileTransferFallbackV6ProofBootstrapPeerBoundary(
                    held.State,
                    receiverState,
                    out var heldBoundary,
                    out var heldReason));
        Assert.Equal(outboundCommand, heldBoundary);
        Assert.Equal("exact_bootstrap_boundary", heldReason);
        Assert.False(
            FileTransferCoordinator
                .TryGetCurrentFileTransferFallbackV6ProofBootstrapPeerProofBoundary(
                    held.State,
                    receiverState,
                    out _,
                    out var heldProofReason));
        Assert.Equal("bootstrap_local_delivery_pending", heldProofReason);
        Assert.Equal(
            "data_session_unavailable",
            FileTransferProtocol.GetFallbackV6ProofBootstrapReceiptReasonCode(
                held.Receipt!));

        var delivered = FileTransferCoordinator.ApplyFileTransferFallbackV6ProofBootstrapReceipt(
            held.State,
            new FileTransferFallbackV6ProofBootstrapReceipt(
                outboundCommand,
                FileTransferFallbackV6ProofBootstrapReceiptStatus.Delivered,
                new PostTunaFallbackPeerProofFrameIdentity(
                    FileTransferProtocol.FrontierRequestFrameTypeV6,
                    outboundCommand.TargetTransportEpoch,
                    new string('c', 64)),
                "filetransfer_fallback_v6_proof_bootstrap_delivered"));
        Assert.True(
            FileTransferCoordinator
                .TryGetCurrentFileTransferFallbackV6ProofBootstrapPeerBoundary(
                    delivered.State,
                    receiverState,
                    out var deliveredBoundary,
                    out var deliveredReason));
        Assert.Equal(outboundCommand, deliveredBoundary);
        Assert.Equal("exact_bootstrap_boundary", deliveredReason);
        Assert.True(
            FileTransferCoordinator
                .TryGetCurrentFileTransferFallbackV6ProofBootstrapPeerProofBoundary(
                    delivered.State,
                    receiverState,
                    out var exactProofBoundary,
                    out var exactProofReason));
        Assert.Equal("exact_bootstrap_peer_proof_boundary", exactProofReason);
        Assert.Equal(outboundCommand, exactProofBoundary.Command);
        Assert.Equal(delivered.Receipt, exactProofBoundary.LocalDeliveryReceipt);
        Assert.Equal(
            PostTunaFallbackPeerProofFrameIdentity.Create(receiverState),
            exactProofBoundary.PeerFrameIdentity);
        Assert.Equal(
            outboundCommand.BootstrapGeneration,
            exactProofBoundary.PeerProofEvidence.ProofGeneration);
        Assert.Equal(
            "fallback_v6_proof_bootstrap_peer_frame",
            exactProofBoundary.PeerProofEvidence.ProofKind);
        Assert.Equal(
            exactProofBoundary.PeerFrameIdentity,
            exactProofBoundary.PeerProofEvidence.FrameIdentity);
        Assert.Equal(
            "delivered",
            FileTransferProtocol.GetFallbackV6ProofBootstrapReceiptReasonCode(
                delivered.Receipt!));

        var retainedIdentity =
            PostTunaFallbackPeerProofFrameIdentity.Create(receiverState);
        var retainedProof = new PostTunaFallbackPeerProofEvidence(
            delivered.State.SessionId,
            delivered.State.TransferId,
            FileTransferDirection.Outbound,
            ProofGeneration: 1,
            TransportEpoch: outboundCommand.TargetTransportEpoch,
            ProofKind: "fallback_v6_proof_bootstrap_peer_state",
            Reason: "fallback_v6_proof_bootstrap_peer_state",
            FrameIdentity: retainedIdentity);
        var prepared = FileTransferCoordinator.PrepareFileTransferRouteTransition(
            delivered.State,
            new FileTransferRouteTransitionPrepareRequest(
                FileTransferRouteTransitionKind.TunaV4ToPostTunaFallbackV6,
                outboundCommand.SourceRuntimeOwner,
                outboundCommand.SourceRoutePublication,
                outboundCommand.SourceRouteCommit,
                FileTransferRoute.FileTunaV4,
                FileTransferProtocol.ProtocolVersionV4,
                FileTransferTransportKind.Tuna,
                new FileTransferFallbackTransitionProofBoundary(
                    outboundCommand.SourceRouteCommit,
                    retainedProof,
                    retainedIdentity,
                    outboundCommand.TargetTransportEpoch,
                    TargetBridgeRecoveryGeneration: Math.Max(
                        1,
                        outboundCommand.SourceBridgeRecoveryGeneration + 1)),
                outboundCommand.Observation.DurableCheckpoint,
                FileTransferRoute.PostTunaFallbackV6,
                FileTransferProtocol.ProtocolVersionV6,
                FileTransferTransportKind.RegularNkn,
                FileTransferTransportHandoffKind.TunaToNormalFallback,
                PredecessorTransitionAuthorityId: null,
                "fallback_v6_proof_bootstrap_peer_state"));
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Prepared,
            prepared.Status);
        Assert.False(
            FileTransferCoordinator
                .TryGetCurrentFileTransferFallbackV6ProofBootstrapPeerBoundary(
                    prepared.State,
                    receiverState,
                    out _,
                    out var retainedReason));
        Assert.Equal("bootstrap_not_current", retainedReason);
        Assert.Null(
            FileTransferCoordinator
                .GetCurrentFileTransferFallbackV6ProofBootstrapBoundary(
                    prepared.State));
        Assert.False(
            FileTransferCoordinator
                .TryGetCurrentFileTransferFallbackV6ProofBootstrapPeerBoundary(
                    prepared.State,
                    receiverState with { Epoch = receiverState.Epoch + 1 },
                    out _,
                    out var replacementReason));
        Assert.Equal("bootstrap_not_current", replacementReason);

        var emptyDrainFingerprint =
            FileTransferCoordinator
                .CreateFileTransferRouteTransitionPhysicalDrainFingerprint([]);
        var draining =
            FileTransferCoordinator.BeginFileTransferRouteTransitionPhysicalDrain(
                prepared.State,
                prepared.Authority!.Value,
                new FileTransferRouteTransitionPauseBindReceipt(
                    prepared.PauseBindCommand!.Value,
                    FileTransferRouteTransitionPauseBindStatus.Installed,
                    "filetransfer_route_transition_pause_bound"),
                capturedThroughPhysicalSendGeneration: 0,
                capturedPhysicalSendLeaseIds: [],
                emptyDrainFingerprint);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Draining,
            draining.Status);
        Assert.False(
            FileTransferCoordinator
                .TryGetCurrentFileTransferFallbackV6ProofBootstrapPeerBoundary(
                    draining.State,
                    receiverState,
                    out _,
                    out var drainingReason));
        Assert.Equal("bootstrap_not_current", drainingReason);

        var invalidated = FileTransferCoordinator.InvalidateFileTransferRouteTransition(
            draining.State,
            prepared.Authority!.Value,
            terminalInvalidation: false,
            "fallback_v6_proof_bootstrap_test_rollback");
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Invalidated,
            invalidated.Status);
        Assert.False(
            FileTransferCoordinator
                .TryGetCurrentFileTransferFallbackV6ProofBootstrapPeerBoundary(
                    invalidated.State,
                    receiverState,
                    out _,
                    out var invalidatedReason));
        Assert.Equal("bootstrap_not_current", invalidatedReason);

        var rejected = FileTransferCoordinator.ApplyFileTransferFallbackV6ProofBootstrapReceipt(
            outbound.State,
            new FileTransferFallbackV6ProofBootstrapReceipt(
                outboundCommand,
                FileTransferFallbackV6ProofBootstrapReceiptStatus.Rejected,
                null,
                "filetransfer_fallback_v6_proof_bootstrap_send_failed"));
        Assert.False(
            FileTransferCoordinator
                .TryGetCurrentFileTransferFallbackV6ProofBootstrapPeerBoundary(
                    rejected.State,
                    receiverState,
                    out _,
                    out var rejectedReason));
        Assert.Equal("bootstrap_not_current", rejectedReason);
        Assert.Equal(
            "send_failed",
            FileTransferProtocol.GetFallbackV6ProofBootstrapReceiptReasonCode(
                rejected.Receipt!));
        Assert.Null(
            FileTransferCoordinator
                .GetCurrentFileTransferFallbackV6ProofBootstrapBoundary(
                    rejected.State));

        Assert.False(
            FileTransferCoordinator
                .TryGetCurrentFileTransferFallbackV6ProofBootstrapPeerBoundary(
                    delivered.State with { IsTerminal = true },
                    receiverState,
                    out _,
                    out var terminalReason));
        Assert.Equal("bootstrap_not_current", terminalReason);

        var inbound = IssueFallbackV6ProofBootstrapForPeerBoundary(
            FileTransferDirection.Inbound);
        var inboundCommand = Assert.IsType<
            FileTransferFallbackV6ProofBootstrapCommand>(inbound.Command);
        var frontierRequest = new FileTransferFrontierRequestFrameV6
        {
            SessionId = inbound.State.SessionId,
            TransferId = inbound.State.TransferId,
            TransportEpoch = inboundCommand.TargetTransportEpoch,
            RequestCorrelationId =
                FileTransferProtocol.CreateFallbackV6ProofBootstrapCorrelationId(
                    inboundCommand.BootstrapGeneration),
            MissingRanges = [],
            Priority = FileTransferProtocol.FallbackV6ProofBootstrapPriority,
            RecoveryMode =
                FileTransferProtocol.FallbackV6ProofBootstrapRecoveryMode,
        };
        Assert.True(
            FileTransferCoordinator
                .TryGetCurrentFileTransferFallbackV6ProofBootstrapPeerBoundary(
                    inbound.State,
                    frontierRequest,
                    out var inboundBoundary,
                    out var inboundReason));
        Assert.Equal(inboundCommand, inboundBoundary);
        Assert.Equal("exact_bootstrap_boundary", inboundReason);

        Assert.False(
            FileTransferCoordinator
                .TryGetCurrentFileTransferFallbackV6ProofBootstrapPeerBoundary(
                    inbound.State,
                    frontierRequest with
                    {
                        RequestCorrelationId =
                            FileTransferProtocol.CreateFallbackV6ProofBootstrapCorrelationId(
                                inboundCommand.BootstrapGeneration + 1),
                    },
                    out _,
                    out var generationReason));
        Assert.Equal("peer_frame_generation_mismatch", generationReason);
        Assert.False(
            FileTransferCoordinator
                .TryGetCurrentFileTransferFallbackV6ProofBootstrapPeerBoundary(
                    inbound.State,
                    receiverState with
                    {
                        SessionId = inbound.State.SessionId,
                        TransferId = inbound.State.TransferId,
                        TransportEpoch = inboundCommand.TargetTransportEpoch,
                    },
                    out _,
                    out var reciprocalKindReason));
        Assert.Equal("peer_frame_kind_mismatch", reciprocalKindReason);
    }

    [Fact]
    [Trait("FileTransferCoordinatorSuite", "FileTransferRouteTransition")]
    public void FileTransferRouteTransition_FallbackToTunaRequiresExactEffectivePhase2Receipt()
    {
        var setup = CreateFallbackV6ToTunaRouteTransitionSetup();
        var activationRequest = Assert.IsType<
            FileTransferTunaActivationTransitionProofBoundary>(
            setup.Request.ProofBoundary);
        var retryRequest =
            activationRequest.EffectiveRetryInstallReceipt!.Value.Request;
        Assert.Equal(1, retryRequest.DispatchAttemptGeneration);
        Assert.Equal(0, retryRequest.MissingDispatchSuccessorGeneration);
        Assert.Null(retryRequest.PredecessorAuthorityId);
        Assert.False(retryRequest.RequestActivePredecessorSupersession);
        var prepared = FileTransferCoordinator.PrepareFileTransferRouteTransition(
            setup.State,
            setup.Request);

        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Prepared,
            prepared.Status);
        var authority = prepared.Authority!.Value;
        Assert.Equal(
            FileTransferRouteTransitionKind.PostTunaFallbackV6ToTunaV4,
            authority.Kind);

        var activation = Assert.IsType<
            FileTransferTunaActivationTransitionProofBoundary>(
            setup.Request.ProofBoundary);
        var rawReceipt = activation.EffectiveRetryInstallReceipt!.Value with
        {
            StageStatus = default,
            StageDisposition = RuntimeUnlockRetryDispatchStageDisposition.Unknown,
            StageCleared = false,
            StagedUtcMs = 0,
            StageExpiresUtcMs = 0,
        };
        var rawRequest = setup.Request with
        {
            ProofBoundary = activation with
            {
                EffectiveRetryInstallReceipt = rawReceipt,
            },
        };
        var rawRejected =
            FileTransferCoordinator.PrepareFileTransferRouteTransition(
                setup.State,
                rawRequest);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Rejected,
            rawRejected.Status);
        Assert.Same(setup.State, rawRejected.State);

        var mutatedReceipt = activation.EffectiveRetryInstallReceipt.Value with
        {
            Authority = activation.EffectiveRetryInstallReceipt.Value.Authority with
            {
                AuthorityId = new FileTransferAuthorityId(
                    "fta2-mutated-fallback-transition-receipt"),
            },
        };
        var mutatedRequest = setup.Request with
        {
            ProofBoundary = activation with
            {
                EffectiveRetryInstallReceipt = mutatedReceipt,
            },
        };
        var mutatedRejected =
            FileTransferCoordinator.PrepareFileTransferRouteTransition(
                setup.State,
                mutatedRequest);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Rejected,
            mutatedRejected.Status);
        Assert.Same(setup.State, mutatedRejected.State);

        var emptyFingerprint =
            FileTransferCoordinator
                .CreateFileTransferRouteTransitionPhysicalDrainFingerprint([]);
        var draining =
            FileTransferCoordinator.BeginFileTransferRouteTransitionPhysicalDrain(
                prepared.State,
                authority,
                new FileTransferRouteTransitionPauseBindReceipt(
                    prepared.PauseBindCommand!.Value,
                    FileTransferRouteTransitionPauseBindStatus.Installed,
                    "filetransfer_route_transition_pause_bound"),
                capturedThroughPhysicalSendGeneration: 0,
                capturedPhysicalSendLeaseIds: [],
                emptyFingerprint);
        var drain = draining.DrainCommand!.Value;
        Assert.False(
            FileTransferCoordinator.TryValidateFileTransferRouteTransitionCommitProof(
                draining.State,
                authority,
                finalProof: null,
                out var missingProofReason));
        Assert.Equal(
            "filetransfer_route_transition_activation_proof_mismatch",
            missingProofReason);
        Assert.True(
            FileTransferCoordinator.TryValidateFileTransferRouteTransitionCommitProof(
                draining.State,
                authority,
                setup.FinalProof with
                {
                    Reason = "runtime_unlock_transaction_peer_proof",
                },
                out var initiatorReasonDriftReason),
            initiatorReasonDriftReason);
        Assert.False(
            FileTransferCoordinator.TryValidateFileTransferRouteTransitionCommitProof(
                draining.State,
                authority,
                setup.FinalProof with
                {
                    OfferGeneration = setup.FinalProof.OfferGeneration + 1,
                },
                out var initiatorTupleMutationReason));
        Assert.Equal(
            "filetransfer_route_transition_activation_proof_mismatch",
            initiatorTupleMutationReason);
        Assert.True(
            FileTransferCoordinator
                .TryGetCurrentRuntimeUnlockRetryDispatchInstallReceipt(
                    draining.State,
                    out var currentBeforeInvalidation));
        Assert.Equal(
            activation.EffectiveRetryInstallReceipt.Value,
            currentBeforeInvalidation);
        var commitState =
            InvalidateRuntimeUnlockRetryLifecycleForRouteTransitionCommitForTest(
                draining.State);
        Assert.False(
            FileTransferCoordinator
                .TryGetCurrentRuntimeUnlockRetryDispatchInstallReceipt(
                    commitState,
                    out _));
        var committed = FileTransferCoordinator.CommitFileTransferRouteTransition(
            commitState,
            authority,
            new FileTransferRouteTransitionPhysicalDrainReceipt(
                drain,
                drain.CapturedPhysicalSendLeaseIds,
                drain.CapturedPhysicalSendCount,
                drain.CapturedPhysicalSendFingerprint,
                FileTransferRouteTransitionPhysicalDrainOutcome.Completed,
                "physical_drain_completed"),
            setup.FinalProof);

        Assert.True(
            committed.Status ==
                FileTransferRouteTransitionDecisionStatus.Committed,
            committed.Reason);
        Assert.Equal(
            FileTransferRoute.FileTunaV4,
            committed.State.RouteSelection.Route);
        Assert.Null(committed.State.CurrentRuntimeUnlockRetryDispatchAuthority);
        Assert.Null(committed.State.CurrentRuntimeUnlockAdmission);
        Assert.Null(committed.State.CurrentRuntimeUnlockPendingPreCommitProbe);
    }

    [Fact]
    [Trait("FileTransferCoordinatorSuite", "FileTransferRouteTransition")]
    public void FileTransferRouteTransition_InboundResponderAckedProbeUsesPairedReceiptWithoutPhase2Release()
    {
        var fallback = FileTransferRouteResolver.Resolve(
            FileTransferRoute.PostTunaFallbackV6);
        var state = ActiveFallbackStateWithoutCheckpoint(
            FileTransferDirection.Inbound);
        var owner = state.CurrentRuntimeOwner!.Value;
        var leg = state.CurrentLeg!;
        var publication = FileTransferCoordinator.AuthorizeAction(
            state,
            new FileTransferCoordinatorActionRequest(
                FileTransferCoordinatorActionKind.RoutePublication,
                Source: "test",
                Reason: "responder_handoff_publication",
                RuntimeOwner: owner,
                Route: fallback.Route,
                ProtocolVersion: fallback.ProtocolVersion,
                LiveRouteEpoch: leg.LiveRouteEpochId,
                LegGeneration: leg.Generation,
                RuntimeGeneration: owner.RuntimeGeneration,
                TerminalGeneration: state.TerminalGeneration,
                TargetRoute: fallback.Route,
                TargetProtocolVersion: fallback.ProtocolVersion,
                TargetTransport: FileTransferTransportKind.RegularNkn));
        Assert.True(publication.Accepted);
        state = publication.State with
        {
            CurrentDataSessionIdentity = "responder-handoff-data-session",
            CurrentDataSessionGeneration = 23,
        };
        var yielded = MarkFallbackTailQuiescent(
            state,
            fallback,
            state.CurrentLeg!.TransportEpochId,
            committedChunk: 5,
            highestObservedChunk: 5);
        var tailYield = Assert.IsType<FallbackTailYieldDecision>(
            yielded.FallbackTailYieldDecision);
        var local = FileTransferCoordinator.CreateFallbackTailLocalProofReceipt(
            yielded.State,
            tailYield,
            "responder-local-proof",
            new string('a', 64),
            40_000);
        var localApplied =
            FileTransferCoordinator.ApplyFallbackTailLocalProofReceipt(
                yielded.State,
                local);
        var peer = FileTransferCoordinator.CreateFallbackTailPeerProofReceipt(
            localApplied.State,
            CreateCoordinatorFallbackTailPeerProof(
                localApplied.State,
                tailYield),
            "responder-peer-proof",
            40_001);
        var paired =
            FileTransferCoordinator.ApplyFallbackTailPeerProofReceipt(
                localApplied.State,
                peer);
        Assert.True(paired.Accepted, paired.Reason);
        var pairedRelease =
            Assert.IsType<FileTransferFallbackTailPairedReleaseReceipt>(
                paired.PairedRelease);
        var fallbackTail = FileTransferCoordinator.GetFallbackTailYieldSubstate(
            paired.State);
        Assert.Equal(
            FileTransferFallbackTailYieldPairingState.Paired,
            fallbackTail.CurrentOperation!.Value.PairingState);
        Assert.Null(fallbackTail.CurrentReservation);
        Assert.Null(fallbackTail.LastConsumedReservation);
        Assert.Null(fallbackTail.LastConsumingInstallReceipt);
        Assert.False(paired.State.RuntimeUnlockFallbackSurvivalState.FallbackTerminalized);
        Assert.False(
            FileTransferCoordinator
                .HasEffectiveFallbackTailPairedReleaseForRouteTransition(
                    paired.State));
        var admitted = RequestRuntimeUnlockAdmission(
            paired.State,
            paired.State.CurrentRuntimeOwner);
        var admission = Assert.IsType<RuntimeUnlockAdmissionToken>(
            admitted.RuntimeUnlockAdmissionDecision!.Value.AdmissionToken);
        var pendingDecision = RecordPendingPreCommitProbe(
            admitted.State,
            admission);
        var pending = Assert.IsType<RuntimeUnlockPendingPreCommitProbeRequest>(
            pendingDecision.State.CurrentRuntimeUnlockPendingPreCommitProbe);
        var peerScopeState = pendingDecision.State;
        var peerScopeLeg = Assert.IsType<FileTransferLeg>(
            peerScopeState.CurrentLeg);
        var peerReceiveScope =
            new RuntimeUnlockPeerPreCommitAnswerAcceptanceScope(
                peerScopeState.CurrentRuntimeOwner!.Value,
                peerScopeState.CurrentRoutePublicationToken!.Value,
                peerScopeState.TerminalGeneration,
                peerScopeLeg.Generation,
                peerScopeLeg.TransportEpochId,
                peerScopeLeg.BridgeRecoveryGeneration,
                peerScopeLeg.CheckpointRequestId ?? "(none)",
                peerScopeLeg.CheckpointGeneration,
                peerScopeState.CurrentDataSessionIdentity!,
                peerScopeState.CurrentDataSessionGeneration,
                admission);
        var observation =
            new RuntimeUnlockResponderPeerProbeRouteTransitionObservation(
                pending.SessionId,
                pending.TransferId,
                pending.TransactionGeneration,
                pending.OfferGeneration,
                PendingAnswerAckGeneration: 5,
                PayerDecisionId: 7,
                LaunchGeneration: 31,
                Lanes: "file",
                AnswerAcceptanceSource: "SemanticAnswerAck",
                AckMessageId: "answer-ack-message",
                AckSourceFingerprint: new string('b', 64),
                PeerProbeFrameFingerprint: new string('c', 64),
                pending.TunaPathLeaseGeneration,
                pending.TunaPathLeaseListenerRunId,
                ProbeId: "probe-responder-fallback-v6-to-tuna",
                RuntimeUnlockPathProbeState.Acked,
                FileTransferTransportKind.Tuna,
                ProbeAckedUtcMs: 40_100,
                FileTransferRoute.FileTunaV4,
                FileTransferProtocol.ProtocolVersionV4,
                FileTransferTransportHandoffKind.NormalToTunaActivation,
                FileTransferTransportKind.Tuna,
                peerReceiveScope);
        var bound = FileTransferCoordinator
            .BindRuntimeUnlockResponderPeerProbeRouteTransitionHandoff(
                pendingDecision.State,
                observation,
                admission,
                pending);
        Assert.Equal(
            RuntimeUnlockResponderPeerProbeRouteTransitionHandoffStatus.Accepted,
            bound.Status);
        var responderAuthority = Assert.IsType<
            RuntimeUnlockResponderPeerProbeRouteTransitionHandoffAuthority>(
            bound.Authority);
        var duplicate = FileTransferCoordinator
            .BindRuntimeUnlockResponderPeerProbeRouteTransitionHandoff(
                bound.State,
                observation,
                admission,
                pending);
        Assert.Equal(
            RuntimeUnlockResponderPeerProbeRouteTransitionHandoffStatus.Idempotent,
            duplicate.Status);
        Assert.Equal(responderAuthority, duplicate.Authority);

        var observationMutations =
            new RuntimeUnlockResponderPeerProbeRouteTransitionObservation[]
            {
                observation with
                {
                    PendingAnswerAckGeneration =
                        observation.PendingAnswerAckGeneration + 1,
                },
                observation with
                {
                    PayerDecisionId = observation.PayerDecisionId + 1,
                },
                observation with
                {
                    LaunchGeneration = observation.LaunchGeneration + 1,
                },
                observation with { Lanes = "file,screen" },
                observation with { AnswerAcceptanceSource = "RawAnswerAck" },
                observation with { AckMessageId = "mutated-answer-ack-message" },
                observation with
                {
                    AckSourceFingerprint = new string('d', 64),
                },
                observation with
                {
                    PeerProbeFrameFingerprint = new string('e', 64),
                },
                observation with
                {
                    TunaPathLeaseGeneration =
                        observation.TunaPathLeaseGeneration + 1,
                },
                observation with
                {
                    TunaPathLeaseListenerRunId = "mutated-listener-run",
                },
                observation with { ProbeId = "mutated-probe" },
                observation with
                {
                    ProbeState = RuntimeUnlockPathProbeState.Started,
                },
                observation with
                {
                    ProbeTransport = FileTransferTransportKind.RegularNkn,
                },
                observation with
                {
                    ProbeAckedUtcMs = observation.ProbeAckedUtcMs + 1,
                },
                observation with
                {
                    TargetRoute = FileTransferRoute.PostTunaFallbackV6,
                },
                observation with
                {
                    PeerReceiveScope = peerReceiveScope with
                    {
                        Admission = admission with
                        {
                            AdmissionGeneration =
                                admission.AdmissionGeneration + 1,
                        },
                    },
                },
                observation with
                {
                    PeerReceiveScope = peerReceiveScope with
                    {
                        DataSessionGeneration =
                            peerReceiveScope.DataSessionGeneration + 1,
                    },
                },
            };
        foreach (var mutation in observationMutations)
        {
            var mutatedBound = FileTransferCoordinator
                .BindRuntimeUnlockResponderPeerProbeRouteTransitionHandoff(
                    bound.State,
                    mutation,
                    admission,
                    pending);
            Assert.Equal(
                RuntimeUnlockResponderPeerProbeRouteTransitionHandoffStatus
                    .Rejected,
                mutatedBound.Status);
            Assert.Equal(responderAuthority, mutatedBound.Authority);
        }

        FileTransferCoordinatorState MutatePairScope(
            Func<FileTransferFallbackTailYieldScope,
                FileTransferFallbackTailYieldScope> mutate)
        {
            var currentFallback = bound.State.PersistentState.FallbackTailYield;
            var currentOperation = currentFallback.CurrentOperation!.Value;
            return bound.State with
            {
                PersistentState = bound.State.PersistentState with
                {
                    FallbackTailYield = currentFallback with
                    {
                        CurrentOperation = currentOperation with
                        {
                            Scope = mutate(currentOperation.Scope),
                        },
                    },
                },
            };
        }

        var currentPair = bound.State.PersistentState.FallbackTailYield;
        var currentPairOperation = currentPair.CurrentOperation!.Value;
        var mutationPublication =
            bound.State.CurrentRoutePublicationToken!.Value;
        var scopeMutations = new FileTransferCoordinatorState[]
        {
            bound.State with { Direction = FileTransferDirection.Outbound },
            bound.State with { IsTerminal = true },
            bound.State with
            {
                RouteSelection = FileTransferRouteResolver.Resolve(
                    FileTransferRoute.FileTunaV4),
            },
            bound.State with
            {
                CurrentRoutePublicationToken = mutationPublication with
                {
                    PublicationGeneration =
                        mutationPublication.PublicationGeneration + 1,
                },
            },
            bound.State with
            {
                CurrentRuntimeUnlockAdmission = admission with
                {
                    AdmissionGeneration = admission.AdmissionGeneration + 1,
                },
            },
            bound.State with
            {
                PersistentState = bound.State.PersistentState with
                {
                    FallbackTailYield = currentPair with
                    {
                        CurrentOperation = currentPairOperation with
                        {
                            PairingState =
                                FileTransferFallbackTailYieldPairingState
                                    .PeerProofObserved,
                            PairedRelease = null,
                        },
                    },
                },
            },
            MutatePairScope(scope => scope with
            {
                LegGeneration = scope.LegGeneration + 1,
            }),
            MutatePairScope(scope => scope with
            {
                TransportEpoch = scope.TransportEpoch + 1,
            }),
            MutatePairScope(scope => scope with
            {
                BridgeRecoveryGeneration = scope.BridgeRecoveryGeneration + 1,
            }),
            MutatePairScope(scope => scope with
            {
                CheckpointRequestIdSnapshot =
                    $"{scope.CheckpointRequestIdSnapshot}-mutated",
            }),
        };
        foreach (var mutation in scopeMutations)
        {
            var invalidatedScope = FileTransferCoordinator
                .BindRuntimeUnlockResponderPeerProbeRouteTransitionHandoff(
                    mutation,
                    observation,
                    admission,
                    pending);
            Assert.Equal(
                RuntimeUnlockResponderPeerProbeRouteTransitionHandoffStatus
                    .Invalidated,
                invalidatedScope.Status);
            Assert.Null(invalidatedScope.Authority);
        }

        var unavailable = FileTransferCoordinator
            .InvalidateRuntimeUnlockResponderPeerProbeRouteTransitionHandoff(
                bound.State,
                observation,
                "data_session_unavailable");
        Assert.Equal(
            RuntimeUnlockResponderPeerProbeRouteTransitionHandoffStatus.Invalidated,
            unavailable.Status);
        Assert.Null(unavailable.Authority);
        Assert.Null(
            unavailable.State.PersistentState
                .RuntimeUnlockResponderPeerProbeRouteTransitionHandoff
                .CurrentAuthority);
        var unavailableReplay = FileTransferCoordinator
            .BindRuntimeUnlockResponderPeerProbeRouteTransitionHandoff(
                unavailable.State,
                observation,
                admission,
                pending);
        Assert.Equal(
            RuntimeUnlockResponderPeerProbeRouteTransitionHandoffStatus.Accepted,
            unavailableReplay.Status);
        Assert.True(
            unavailableReplay.Authority!.Value.AuthorityGeneration >
            responderAuthority.AuthorityGeneration);

        var staleScope = bound.State with
        {
            CurrentDataSessionGeneration =
                bound.State.CurrentDataSessionGeneration + 1,
        };
        var invalidated = FileTransferCoordinator
            .BindRuntimeUnlockResponderPeerProbeRouteTransitionHandoff(
                staleScope,
                observation,
                admission,
                pending);
        Assert.Equal(
            RuntimeUnlockResponderPeerProbeRouteTransitionHandoffStatus.Invalidated,
            invalidated.Status);
        Assert.Null(invalidated.Authority);
        var staleReplay = FileTransferCoordinator
            .BindRuntimeUnlockResponderPeerProbeRouteTransitionHandoff(
                invalidated.State,
                observation,
                admission,
                pending);
        Assert.Equal(
            RuntimeUnlockResponderPeerProbeRouteTransitionHandoffStatus.Invalidated,
            staleReplay.Status);
        Assert.Null(staleReplay.Authority);

        var transaction = BuildCommitReadyRuntimeUnlockTransaction(
            bound.State,
            pending.TransactionGeneration,
            pending.OfferGeneration,
            observation.ProbeId);
        var finalProof = WithCurrentTunaLease(
            RuntimeUnlockTransaction.CreateRouteCommitProof(
                transaction,
                "runtime_unlock_transaction_peer_proof",
                admission),
            pending.TunaPathLeaseGeneration,
            pending.TunaPathLeaseListenerRunId!);
        var acceptedLaunchBoundary = finalProof with
        {
            Reason = "runtime_unlock_responder_peer_probe_acked",
        };
        var currentOwner = bound.State.CurrentRuntimeOwner!.Value;
        var currentPublication = bound.State.CurrentRoutePublicationToken!.Value;
        var currentLeg = bound.State.CurrentLeg!;
        var checkpoint = new FileTransferRouteTransitionDurableCheckpoint(
            currentOwner,
            currentPublication,
            bound.State.TerminalGeneration,
            currentLeg.Generation,
            currentLeg.TransportEpochId,
            currentLeg.BridgeRecoveryGeneration,
            bound.State.CurrentDataSessionGeneration,
            StateEpoch: 5,
            ContiguousCommittedChunkIndex: 6,
            DurableHighestChunkIndex: 7,
            ChunkCount: 128,
            CheckpointGeneration: 3);
        var request = new FileTransferRouteTransitionPrepareRequest(
            FileTransferRouteTransitionKind.PostTunaFallbackV6ToTunaV4,
            currentOwner,
            currentPublication,
            SourceRouteCommit: null,
            FileTransferRoute.PostTunaFallbackV6,
            FileTransferProtocol.ProtocolVersionV6,
            FileTransferTransportKind.RegularNkn,
            new FileTransferTunaActivationTransitionProofBoundary(
                admission,
                pending,
                acceptedLaunchBoundary,
                observation.LaunchGeneration,
                EffectiveRetryInstallReceipt: null,
                pairedRelease,
                responderAuthority),
            checkpoint,
            FileTransferRoute.FileTunaV4,
            FileTransferProtocol.ProtocolVersionV4,
            FileTransferTransportKind.Tuna,
            FileTransferTransportHandoffKind.NormalToTunaActivation,
            PredecessorTransitionAuthorityId: null,
            "responder_fallback_v6_to_tuna_transition_test");
        var committed = CommitEmptyFileTransferRouteTransitionForTest(
            bound.State,
            request,
            finalProof,
            invalidateRuntimeUnlockRetryLifecycle: false);
        Assert.Equal(FileTransferRoute.FileTunaV4, committed.State.RouteSelection.Route);
        Assert.Null(
            FileTransferCoordinator.GetFallbackTailYieldSubstate(committed.State)
                .LastConsumedReservation);
        var unavailableAfterCommit = FileTransferCoordinator
            .InvalidateRuntimeUnlockResponderPeerProbeRouteTransitionHandoff(
                committed.State,
                observation,
                "data_session_unavailable_after_commit");
        Assert.Equal(
            RuntimeUnlockResponderPeerProbeRouteTransitionHandoffStatus.Invalidated,
            unavailableAfterCommit.Status);
        Assert.Null(unavailableAfterCommit.Authority);
        Assert.Equal(
            FileTransferRoute.FileTunaV4,
            unavailableAfterCommit.State.RouteSelection.Route);
        var staleAvailableAfterCommit = FileTransferCoordinator
            .BindRuntimeUnlockResponderPeerProbeRouteTransitionHandoff(
                unavailableAfterCommit.State,
                observation,
                admission,
                pending);
        Assert.Equal(
            RuntimeUnlockResponderPeerProbeRouteTransitionHandoffStatus.Invalidated,
            staleAvailableAfterCommit.Status);
        Assert.Null(staleAvailableAfterCommit.Authority);
    }

    [Fact]
    [Trait("FileTransferCoordinatorSuite", "FileTransferRouteTransition")]
    public void FileTransferRouteTransition_InstalledPressureRequiresExactApplyReceipt()
    {
        var setup = CreateRegularV4ToTunaRouteTransitionSetup();
        var (repairState, repairDecision) =
            AuthorizeRegularV4FrontierRepair(setup.State);
        var stagedPressure =
            FileTransferCoordinator.StageRegularV4FrontierRepairPressureBinding(
                repairState,
                repairDecision,
                RegularV4PressureAuthorityRequest(
                    "regular-v4-pressure:route-transition"),
                "regular_v4_receiver_frontier_repair_due");
        var pressureBinding = stagedPressure.Binding!.Value;
        var installedPressure =
            FileTransferCoordinator.CommitRegularV4FrontierRepairPressureBinding(
                stagedPressure.State,
                new FileTransferRegularV4FrontierRepairPressureInstallReceipt(
                    pressureBinding.Authority,
                    FileTransferRegularV4FrontierRepairPressureInstallStatus.Installed,
                    "installed",
                    pressureBinding.InstallGeneration,
                    pressureBinding.PressureReason));
        Assert.Equal(
            RegularV4FrontierRepairPressureBindingDecisionStatus.Accepted,
            installedPressure.Status);

        var prepared = FileTransferCoordinator.PrepareFileTransferRouteTransition(
            installedPressure.State,
            setup.Request);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Prepared,
            prepared.Status);
        var authority = prepared.Authority!.Value;
        var emptyFingerprint =
            FileTransferCoordinator
                .CreateFileTransferRouteTransitionPhysicalDrainFingerprint([]);
        var draining =
            FileTransferCoordinator.BeginFileTransferRouteTransitionPhysicalDrain(
                prepared.State,
                authority,
                new FileTransferRouteTransitionPauseBindReceipt(
                    prepared.PauseBindCommand!.Value,
                    FileTransferRouteTransitionPauseBindStatus.Installed,
                    "filetransfer_route_transition_pause_bound"),
                capturedThroughPhysicalSendGeneration: 0,
                capturedPhysicalSendLeaseIds: [],
                emptyFingerprint);
        var drainCommand = draining.DrainCommand!.Value;
        var drainReceipt = new FileTransferRouteTransitionPhysicalDrainReceipt(
            drainCommand,
            drainCommand.CapturedPhysicalSendLeaseIds,
            drainCommand.CapturedPhysicalSendCount,
            drainCommand.CapturedPhysicalSendFingerprint,
            FileTransferRouteTransitionPhysicalDrainOutcome.Completed,
            "physical_drain_completed");
        var preparedPressureSettlement =
            FileTransferCoordinator
                .PrepareFileTransferRouteTransitionPressureSettlement(
                    draining.State,
                    authority,
                    drainReceipt,
                    setup.FinalProof);
        Assert.Equal(
            RegularV4FrontierRepairPressureBindingDecisionStatus.Accepted,
            preparedPressureSettlement.Status);
        var pressureCommand =
            Assert.IsType<FileTransferRegularV4FrontierRepairPressureSettlementCommand>(
                preparedPressureSettlement.SettlementCommand);

        var missingReceipt =
            FileTransferCoordinator.CommitFileTransferRouteTransition(
                draining.State,
                authority,
                drainReceipt,
                setup.FinalProof);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Rejected,
            missingReceipt.Status);
        Assert.Same(draining.State, missingReceipt.State);
        Assert.NotNull(PressureState(missingReceipt.State).InstalledBinding);

        var mutatedReceipt =
            FileTransferCoordinator.CommitFileTransferRouteTransition(
                draining.State,
                authority,
                drainReceipt,
                setup.FinalProof,
                new FileTransferRegularV4FrontierRepairPressureSettlementApplyReceipt(
                    pressureCommand,
                    FileTransferRegularV4FrontierRepairPressureSettlementApplyStatus.Applied,
                    "pressure_applied_by_unrelated_path",
                    CurrentAuthorityCleared: true,
                    RetainedPredecessorCleared: false));
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Rejected,
            mutatedReceipt.Status);
        Assert.Same(draining.State, mutatedReceipt.State);

        var exactReceipt =
            new FileTransferRegularV4FrontierRepairPressureSettlementApplyReceipt(
                pressureCommand,
                FileTransferRegularV4FrontierRepairPressureSettlementApplyStatus.Applied,
                "regular_v4_frontier_repair_pressure_settlement_applied",
                CurrentAuthorityCleared: true,
                RetainedPredecessorCleared: false);
        var committed = FileTransferCoordinator.CommitFileTransferRouteTransition(
            draining.State,
            authority,
            drainReceipt,
            setup.FinalProof,
            exactReceipt);
        Assert.True(
            committed.Status ==
                FileTransferRouteTransitionDecisionStatus.Committed,
            committed.Reason);
        Assert.Equal(
            FileTransferRoute.FileTunaV4,
            committed.State.RouteSelection.Route);
        Assert.Null(PressureState(committed.State).InstalledBinding);

        var duplicate = FileTransferCoordinator.CommitFileTransferRouteTransition(
            committed.State,
            authority,
            drainReceipt,
            setup.FinalProof,
            exactReceipt with
            {
                Status =
                    FileTransferRegularV4FrontierRepairPressureSettlementApplyStatus
                        .Idempotent,
                Reason =
                    "regular_v4_frontier_repair_pressure_settlement_apply_idempotent",
            });
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Idempotent,
            duplicate.Status);
        Assert.Same(committed.State, duplicate.State);
    }

    [Fact]
    [Trait("FileTransferCoordinatorSuite", "FileTransferRouteTransition")]
    public void FileTransferRouteTransition_RollbackPreservesSourceScopeAndAppliesOnce()
    {
        var setup = CreateRegularV4ToTunaRouteTransitionSetup();
        var sourceOwner = setup.State.CurrentRuntimeOwner;
        var sourcePublication = setup.State.CurrentRoutePublicationToken;
        var sourceLeg = setup.State.CurrentLeg;
        var prepared = FileTransferCoordinator.PrepareFileTransferRouteTransition(
            setup.State,
            setup.Request);
        var authority = prepared.Authority!.Value;

        var invalidated = FileTransferCoordinator.InvalidateFileTransferRouteTransition(
            prepared.State,
            authority,
            terminalInvalidation: false,
            "precommit_probe_rejected");
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Invalidated,
            invalidated.Status);
        Assert.Equal(sourceOwner, invalidated.State.CurrentRuntimeOwner);
        Assert.Equal(sourcePublication, invalidated.State.CurrentRoutePublicationToken);
        Assert.Same(sourceLeg, invalidated.State.CurrentLeg);
        Assert.Equal(
            FileTransferRoute.RegularNknV4Fast,
            invalidated.State.RouteSelection.Route);

        var duplicate = FileTransferCoordinator.InvalidateFileTransferRouteTransition(
            invalidated.State,
            authority,
            terminalInvalidation: false,
            "precommit_probe_rejected");
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Idempotent,
            duplicate.Status);
        Assert.Same(invalidated.State, duplicate.State);

        var disposition = Assert.IsType<FileTransferRouteTransitionDispositionCommand>(
            invalidated.DispositionCommand);
        var mismatched = FileTransferCoordinator
            .ApplyFileTransferRouteTransitionDispositionReceipt(
                invalidated.State,
                new FileTransferRouteTransitionDispositionReceipt(
                    disposition,
                    FileTransferRouteTransitionDispositionApplyStatus.Applied,
                    "filetransfer_route_transition_committed"));
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Rejected,
            mismatched.Status);
        Assert.Same(invalidated.State, mismatched.State);

        var applied = FileTransferCoordinator
            .ApplyFileTransferRouteTransitionDispositionReceipt(
                invalidated.State,
                new FileTransferRouteTransitionDispositionReceipt(
                    disposition,
                    FileTransferRouteTransitionDispositionApplyStatus.Applied,
                    "filetransfer_route_transition_rolled_back"));
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Invalidated,
            applied.Status);

        var duplicateReceipt = FileTransferCoordinator
            .ApplyFileTransferRouteTransitionDispositionReceipt(
                applied.State,
                new FileTransferRouteTransitionDispositionReceipt(
                    disposition,
                    FileTransferRouteTransitionDispositionApplyStatus.Idempotent,
                    "filetransfer_route_transition_disposition_idempotent"));
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Idempotent,
            duplicateReceipt.Status);
        Assert.Same(applied.State, duplicateReceipt.State);
    }

    [Fact]
    [Trait("FileTransferCoordinatorSuite", "FileTransferRouteTransition")]
    public void FileTransferRouteTransition_UncommittedTunaFallbackSupersedesExactDrain()
    {
        var setup = CreateRegularV4ToTunaRouteTransitionSetup();
        var prepared = FileTransferCoordinator.PrepareFileTransferRouteTransition(
            setup.State,
            setup.Request);
        var predecessor = prepared.Authority!.Value;
        long[] capturedLeaseIds = [3, 7];
        var fingerprint =
            FileTransferCoordinator
                .CreateFileTransferRouteTransitionPhysicalDrainFingerprint(
                    capturedLeaseIds);
        var draining =
            FileTransferCoordinator.BeginFileTransferRouteTransitionPhysicalDrain(
                prepared.State,
                predecessor,
                new FileTransferRouteTransitionPauseBindReceipt(
                    prepared.PauseBindCommand!.Value,
                    FileTransferRouteTransitionPauseBindStatus.Installed,
                    "filetransfer_route_transition_pause_bound"),
                capturedThroughPhysicalSendGeneration: 7,
                capturedLeaseIds,
                fingerprint);

        var sourceLeg = draining.State.CurrentLeg!;
        var targetEpoch = Math.Max(1, sourceLeg.TransportEpochId + 1);
        var frameIdentity = new PostTunaFallbackPeerProofFrameIdentity(
            "filetransfer_frontier_request_v6",
            targetEpoch,
            new string('b', 64));
        var peerProof = new PostTunaFallbackPeerProofEvidence(
            draining.State.SessionId,
            draining.State.TransferId,
            draining.State.Direction,
            ProofGeneration: 2,
            TransportEpoch: targetEpoch,
            ProofKind: "fallback_peer_frontier",
            Reason: "uncommitted_tuna_fallback",
            FrameIdentity: frameIdentity);
        var successorRequest = new FileTransferRouteTransitionPrepareRequest(
            FileTransferRouteTransitionKind.UncommittedTunaToPostTunaFallbackV6,
            predecessor.SourceRuntimeOwner,
            predecessor.SourceRoutePublication,
            SourceRouteCommit: null,
            predecessor.SourceRoute,
            predecessor.SourceProtocolVersion,
            predecessor.SourceTransport,
            new FileTransferFallbackTransitionProofBoundary(
                SourceRouteCommit: null,
                peerProof,
                frameIdentity,
                targetEpoch,
                TargetBridgeRecoveryGeneration:
                    Math.Max(1, sourceLeg.BridgeRecoveryGeneration + 1),
                PredecessorTransitionAuthorityId: predecessor.AuthorityId),
            predecessor.DurableCheckpoint,
            FileTransferRoute.PostTunaFallbackV6,
            FileTransferProtocol.ProtocolVersionV6,
            FileTransferTransportKind.RegularNkn,
            FileTransferTransportHandoffKind.TunaToNormalFallback,
            predecessor.AuthorityId,
            "uncommitted_tuna_fallback");
        var staged = FileTransferCoordinator.StageFileTransferRouteTransitionSupersession(
            draining.State,
            predecessor,
            successorRequest);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.SupersessionStaged,
            staged.Status);
        Assert.Equal(
            predecessor,
            staged.PauseBindCommand!.Value.PredecessorAuthority);

        var missingPredecessorReceipt = new FileTransferRouteTransitionPauseBindReceipt(
            new FileTransferRouteTransitionPauseBindCommand(
                staged.PauseBindCommand.Value.Authority),
            FileTransferRouteTransitionPauseBindStatus.Installed,
            "filetransfer_route_transition_pause_rebound");
        var missingPredecessor =
            FileTransferCoordinator.CommitFileTransferRouteTransitionSupersession(
                staged.State,
                missingPredecessorReceipt);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Rejected,
            missingPredecessor.Status);
        Assert.Same(staged.State, missingPredecessor.State);

        var reboundReceipt = new FileTransferRouteTransitionPauseBindReceipt(
            staged.PauseBindCommand.Value,
            FileTransferRouteTransitionPauseBindStatus.Installed,
            "filetransfer_route_transition_pause_rebound");
        var superseded =
            FileTransferCoordinator.CommitFileTransferRouteTransitionSupersession(
                staged.State,
                reboundReceipt);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Draining,
            superseded.Status);
        var transitionState =
            FileTransferCoordinator.GetFileTransferRouteTransitionSubstate(
                superseded.State);
        var successor = transitionState.CurrentOperation!.Value;
        Assert.Equal(
            FileTransferRouteTransitionKind
                .UncommittedTunaToPostTunaFallbackV6,
            successor.Authority.Kind);
        Assert.Equal(
            capturedLeaseIds,
            successor.DrainCommand!.Value.CapturedPhysicalSendLeaseIds);
        Assert.Equal(
            FileTransferRouteTransitionDispositionKind.Superseded,
            transitionState.LastTerminalOperation!.Value
                .DispositionCommand!.Value.Kind);

        var duplicate =
            FileTransferCoordinator.CommitFileTransferRouteTransitionSupersession(
                superseded.State,
                reboundReceipt with
                {
                    Status = FileTransferRouteTransitionPauseBindStatus.Idempotent,
                    Reason = "filetransfer_route_transition_pause_bind_idempotent",
                });
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Idempotent,
            duplicate.Status);
        Assert.Same(superseded.State, duplicate.State);

        var successorDrain = successor.DrainCommand.Value;
        var committed = FileTransferCoordinator.CommitFileTransferRouteTransition(
            superseded.State,
            successor.Authority,
            new FileTransferRouteTransitionPhysicalDrainReceipt(
                successorDrain,
                successorDrain.CapturedPhysicalSendLeaseIds,
                successorDrain.CapturedPhysicalSendCount,
                successorDrain.CapturedPhysicalSendFingerprint,
                FileTransferRouteTransitionPhysicalDrainOutcome.Completed,
                "physical_drain_completed"));
        Assert.True(
            committed.Status ==
                FileTransferRouteTransitionDecisionStatus.Committed,
            committed.Reason);
        Assert.Equal(
            FileTransferRoute.PostTunaFallbackV6,
            committed.State.RouteSelection.Route);

        var stalePredecessorReceipt = new FileTransferRouteTransitionPhysicalDrainReceipt(
            draining.DrainCommand!.Value,
            draining.DrainCommand.Value.CapturedPhysicalSendLeaseIds,
            draining.DrainCommand.Value.CapturedPhysicalSendCount,
            draining.DrainCommand.Value.CapturedPhysicalSendFingerprint,
            FileTransferRouteTransitionPhysicalDrainOutcome.Completed,
            "physical_drain_completed");
        var staleCommit = FileTransferCoordinator.CommitFileTransferRouteTransition(
            committed.State,
            predecessor,
            stalePredecessorReceipt,
            setup.FinalProof);
        Assert.Equal(
            FileTransferRouteTransitionDecisionStatus.Rejected,
            staleCommit.Status);
        Assert.Same(committed.State, staleCommit.State);
    }

