    private static (
        FileTransferCoordinatorState State,
        FileTransferRouteSelection Fallback,
        FallbackTailYieldDecision Predecessor,
        FallbackTailYieldTransportEpochReauthorization Reauthorization)
        CreatePendingFallbackTailReauthorizationForTest(
            bool includePeerProof = false)
    {
        var fallback = FileTransferRouteResolver.Resolve(
            FileTransferRoute.PostTunaFallbackV6);
        var source = ActiveFallbackStateWithoutCheckpoint() with
        {
            CurrentDataSessionIdentity = "reauthorization-data-session",
            CurrentDataSessionGeneration = 1,
        };
        var sourceLeg = Assert.IsType<FileTransferLeg>(
            source.CurrentLeg);
        var yielded = MarkFallbackTailQuiescent(
            source,
            fallback,
            sourceLeg.TransportEpochId,
            committedChunk: 5,
            highestObservedChunk: 5);
        var predecessor = Assert.IsType<FallbackTailYieldDecision>(
            yielded.FallbackTailYieldDecision);
        var yieldedState = yielded.State;
        if (includePeerProof)
        {
            var peerReceipt =
                FileTransferCoordinator.CreateFallbackTailPeerProofReceipt(
                    yieldedState,
                    CreateCoordinatorFallbackTailPeerProof(
                        yieldedState,
                        predecessor),
                    "reauthorization-predecessor-peer",
                    19_000);
            var peerApplied =
                FileTransferCoordinator.ApplyFallbackTailPeerProofReceipt(
                    yieldedState,
                    peerReceipt);
            Assert.True(peerApplied.Accepted, peerApplied.Reason);
            yieldedState = peerApplied.State;
        }

        var adoptedLeg = Assert.IsType<FileTransferLeg>(
            yieldedState.CurrentLeg);
        var targetEpoch = adoptedLeg.TransportEpochId + 1;
        var adoption =
            AuthorizeFallbackTransportEpochAdoptionForTest(
                yieldedState,
                targetEpoch);
        Assert.True(adoption.Accepted, adoption.RejectionReason);
        adoptedLeg = Assert.IsType<FileTransferLeg>(
            adoption.State.CurrentLeg);
        adoptedLeg.TransportEpochId = targetEpoch;
        Assert.True(
            FileTransferCoordinator
                .TryCreateFallbackTailYieldTransportEpochReauthorizationRequest(
                    adoption.State,
                    targetEpoch,
                    "peer_transport_epoch_adopted",
                    out var request,
                    out var requestReason),
            requestReason);
        var restarted = FileTransferCoordinator.Apply(
            CoordinatorEvent(
                FileTransferCoordinatorEventKind.StartTransfer,
                fallback,
                reason: "peer_transport_epoch_adopted",
                state: FileTransferLegState.RecoveryActive,
                canSendData: false,
                committedChunk: 5,
                highestObservedChunk: 5,
                transportEpoch: targetEpoch,
                bridgeRecoveryGeneration:
                    adoptedLeg.BridgeRecoveryGeneration,
                fallbackTailYieldTransportEpochReauthorizationRequest:
                    request),
            adoption.State);
        Assert.Null(restarted.MutationRejectedReason);
        var reauthorization =
            Assert.IsType<
                FallbackTailYieldTransportEpochReauthorization>(
                FileTransferCoordinator.GetFallbackTailYieldSubstate(
                        restarted.State)
                    .PendingReauthorization);
        return (
            restarted.State,
            fallback,
            predecessor,
            reauthorization);
    }

    private static FileTransferCoordinatorDecision
        ActivateInitialResponderTunaForFallbackFixture(
            FileTransferCoordinatorState state)
    {
        Assert.Equal(FileTransferDirection.Inbound, state.Direction);
        state = state with
        {
            CurrentDataSessionIdentity =
                "initial-responder-fallback-fixture-data-session",
            CurrentDataSessionGeneration = 17,
        };
        var setup = CreateRegularV4ToTunaRouteTransitionSetup(state);
        var activation = Assert.IsType<
            FileTransferTunaActivationTransitionProofBoundary>(
                setup.Request.ProofBoundary);
        var sourceLeg = Assert.IsType<FileTransferLeg>(setup.State.CurrentLeg);
        var receiveScope =
            new RuntimeUnlockPeerPreCommitAnswerAcceptanceScope(
                setup.State.CurrentRuntimeOwner!.Value,
                setup.State.CurrentRoutePublicationToken!.Value,
                setup.State.TerminalGeneration,
                sourceLeg.Generation,
                sourceLeg.TransportEpochId,
                sourceLeg.BridgeRecoveryGeneration,
                sourceLeg.CheckpointRequestId ?? "(none)",
                sourceLeg.CheckpointGeneration,
                setup.State.CurrentDataSessionIdentity!,
                setup.State.CurrentDataSessionGeneration,
                activation.RuntimeUnlockAdmission,
                RuntimeUnlockResponderPeerProbeTransitionMode
                    .InitialRegularV4);
        var observation =
            new RuntimeUnlockResponderPeerProbeRouteTransitionObservation(
                setup.State.SessionId,
                setup.State.TransferId,
                activation.PendingPreCommitProbe.TransactionGeneration,
                activation.PendingPreCommitProbe.OfferGeneration,
                PendingAnswerAckGeneration: 7,
                PayerDecisionId: 11,
                activation.LaunchGeneration,
                Lanes: "file",
                AnswerAcceptanceSource: "SemanticAnswerAck",
                AckMessageId:
                    "initial-responder-fallback-fixture-answer-ack",
                AckSourceFingerprint: new string('a', 64),
                PeerProbeFrameFingerprint: new string('b', 64),
                activation.PendingPreCommitProbe.TunaPathLeaseGeneration,
                activation.PendingPreCommitProbe
                    .TunaPathLeaseListenerRunId!,
                ProbeId: setup.FinalProof.PathProbeId!,
                RuntimeUnlockPathProbeState.Acked,
                FileTransferTransportKind.Tuna,
                ProbeAckedUtcMs: setup.FinalProof.PathProbeAckedUtcMs,
                FileTransferRoute.FileTunaV4,
                FileTransferProtocol.ProtocolVersionV4,
                FileTransferTransportHandoffKind.NormalToTunaActivation,
                FileTransferTransportKind.Tuna,
                receiveScope);
        return CommitEmptyFileTransferRouteTransitionForTest(
            setup.State,
            setup.Request with
            {
                ProofBoundary = activation with
                {
                    AcceptedLaunchBoundary = setup.FinalProof,
                    InitialResponderPeerProbeObservation = observation,
                },
            },
            setup.FinalProof);
    }

    private static FileTransferCoordinatorState ActiveFallbackStateWithoutCheckpoint(
        FileTransferDirection direction = FileTransferDirection.Outbound)
    {
        var regular = FileTransferRouteResolver.Resolve(FileTransferRoute.RegularNknV4Fast);
        var tuna = FileTransferRouteResolver.Resolve(FileTransferRoute.FileTunaV4);
        var fallback = FileTransferRouteResolver.Resolve(FileTransferRoute.PostTunaFallbackV6);
        var regularState = StartRegular(regular, direction).State;
        var activeTuna = direction == FileTransferDirection.Inbound
            ? ActivateInitialResponderTunaForFallbackFixture(regularState)
            : ActivateTuna(
                regularState,
                tuna,
                committedChunk: 5);
        var state = FallBack(
            activeTuna.State,
            fallback,
            committedChunk: 5,
            transportEpoch: 2).State;
        state.CurrentLeg!.State = FileTransferLegState.Active;
        state.CurrentLeg.CanSendData = true;
        state.CurrentLeg.CheckpointRequestId = null;
        return state;
    }

    private static FileTransferCoordinatorDecision RequestRuntimeUnlockAdmission(
        FileTransferCoordinatorState state,
        RuntimeOwnerToken? owner,
        RuntimeUnlockFallbackSurvivalState? survivalState = null)
    {
        var nextState = state;
        if (survivalState is { } survival)
        {
            nextState = FileTransferCoordinator.Apply(
                CoordinatorEvent(
                    FileTransferCoordinatorEventKind.RuntimeUnlockFallbackSurvivalUpdated,
                    state.RouteSelection,
                    reason: "fallback_survival_updated",
                    state: state.CurrentLeg?.State ?? FileTransferLegState.Active,
                    canSendData: state.CurrentLeg?.CanSendData ?? true,
                    transportEpoch: state.CurrentLeg?.TransportEpochId ?? 0,
                    bridgeRecoveryGeneration: state.CurrentLeg?.BridgeRecoveryGeneration ?? 0,
                    runtimeUnlockFallbackSurvivalState: survival),
                state).State;
        }

        return FileTransferCoordinator.Apply(
            CoordinatorEvent(
                FileTransferCoordinatorEventKind.RuntimeUnlockAdmission,
                nextState.RouteSelection,
                reason: "runtime_unlock_admission",
                state: nextState.CurrentLeg?.State ?? FileTransferLegState.Active,
                canSendData: nextState.CurrentLeg?.CanSendData ?? true,
                transportEpoch: nextState.CurrentLeg?.TransportEpochId ?? 0,
                bridgeRecoveryGeneration: nextState.CurrentLeg?.BridgeRecoveryGeneration ?? 0,
                runtimeUnlockAdmissionRequest: new RuntimeUnlockAdmissionRequest(
                    "test",
                    "runtime_unlock_admission",
                    owner)),
            nextState);
    }

    private static FileTransferCoordinatorDecision CommitRuntimeUnlockToTuna(
        FileTransferCoordinatorState state,
        FileTransferRouteSelection tuna)
    {
        var admission = RequestRuntimeUnlockAdmission(state, state.CurrentRuntimeOwner);
        var admissionToken = admission.RuntimeUnlockAdmissionDecision!.Value.AdmissionToken!.Value;
        var transaction = BuildCommitReadyRuntimeUnlockTransaction(admission.State);
        var proof = WithCurrentTunaLease(
            RuntimeUnlockTransaction.CreateRouteCommitProof(transaction, "answer_received", admissionToken));
        return FileTransferCoordinator.Apply(
            CoordinatorEvent(
                FileTransferCoordinatorEventKind.RuntimeUnlockCommitRequested,
                tuna,
                FileTransferTransportHandoffKind.NormalToTunaActivation,
                FileTransferTransportKind.Tuna,
                "runtime_unlock_commit",
                FileTransferLegState.Active,
                canSendData: true,
                runtimeUnlockCommitProof: proof),
            admission.State);
    }

