            RuntimeUnlockRetryDispatchListenerRearmRequirement
                listenerRearmRequirement =
                    RuntimeUnlockRetryDispatchListenerRearmRequirement.None)
    {
        var fixture = AuthorizeAndStagePersistentRetryLifecycle(
            stagedUtcMs,
            listenerRearmRequirement);
        return StageAndInstallPersistentRetryLifecycle(
            fixture.StagedState,
            fixture.Granted,
            fixture.Request,
            stagedUtcMs,
            stageAlreadyRecorded: true);
    }

    private static FileTransferCoordinatorState
        ClosePersistentRetryLifecycleForTest()
    {
        var first = InstallPersistentRetryLifecycle(stagedUtcMs: 6_000_000);
        const long firstOfferGeneration = 301;
        var firstMissing = SettlePersistentRetryMissingDispatch(
            first.State,
            first.Receipt.Authority.AuthorityId,
            firstOfferGeneration,
            "retry-offer-bounded-301");
        var successor =
            FileTransferCoordinator.PrepareRuntimeUnlockRetryDispatchSuccessor(
                firstMissing.State,
                first.Receipt.Authority,
                firstOfferGeneration);
        Assert.Equal(
            RuntimeUnlockRetryDispatchSuccessorDecisionStatus.Requested,
            successor.Status);
        var successorRequest =
            Assert.IsType<RuntimeUnlockRetryDispatchAuthorityRequest>(
                successor.Request);
        var successorInstall = StageAndInstallPersistentRetryLifecycle(
            successor.State,
            Assert.IsType<RuntimeUnlockRetryDispatchDecision>(
                successor.AuthorizationDecision),
            successorRequest,
            stagedUtcMs: 6_100_000);
        const long secondOfferGeneration = 302;
        var secondMissing = SettlePersistentRetryMissingDispatch(
            successorInstall.State,
            successorInstall.Receipt.Authority.AuthorityId,
            secondOfferGeneration,
            "retry-offer-bounded-302");

        var closed =
            FileTransferCoordinator.PrepareRuntimeUnlockRetryDispatchSuccessor(
                secondMissing.State,
                successorInstall.Receipt.Authority,
                secondOfferGeneration);
        Assert.Equal(
            RuntimeUnlockRetryDispatchSuccessorDecisionStatus.ChainClosed,
            closed.Status);
        Assert.NotNull(
            FileTransferCoordinator.GetRuntimeUnlockRetryLifecycle(closed.State)
                .BoundedClosure);
        return closed.State;
    }

    private static (
        FileTransferCoordinatorState State,
        RuntimeUnlockRetryDispatchAuthorityRequest Request,
        RecoveryLivenessLease RetiredLease)
        AuthorizeReceiveRecoveryLeaseClosureRetrySource(
            RuntimeUnlockRetryLifecycleSubstate preservedRetryLifecycle)
    {
        var adopted = CreateAdoptedReceiveRecoveryClosure();
        var request = CreateReceiveRecoveryRetryRequest(
            adopted.State,
            adopted.Authority,
            adopted.RetiredLease,
            recoveryContractGeneration: 52);
        var state = adopted.State with
        {
            PersistentState = adopted.State.PersistentState with
            {
                RuntimeUnlockRetryLifecycle = preservedRetryLifecycle,
            },
        };
        return (state, request, adopted.RetiredLease);
    }

    private static PersistentRetryInstallFixture
        StageAndInstallPersistentRetryLifecycle(
            FileTransferCoordinatorState state,
            RuntimeUnlockRetryDispatchDecision granted,
            RuntimeUnlockRetryDispatchAuthorityRequest request,
            long stagedUtcMs,
            bool stageAlreadyRecorded = false)
    {
        var stagedState = state;
        if (!stageAlreadyRecorded)
        {
            var staged = StagePersistentRetryLifecycle(
                state,
                granted,
                stagedUtcMs);
            Assert.Equal(
                RuntimeUnlockRetryLifecycleTransitionStatus.Accepted,
                staged.Status);
            stagedState = staged.State;
        }

        var issuance =
            FileTransferCoordinator.IssueRuntimeUnlockRetryDispatchInstallReceipt(
                stagedState,
                granted,
                request,
                stagedUtcMs + 1);
        Assert.Equal(
            RuntimeUnlockRetryLifecycleTransitionStatus.Accepted,
            issuance.Status);
        var receipt = Assert.IsType<RuntimeUnlockRetryDispatchInstallReceipt>(
            issuance.Receipt);
        var committed =
            FileTransferCoordinator.CommitRuntimeUnlockRetryDispatchInstall(
                issuance.State,
                new RuntimeUnlockRetryDispatchInstallResult(
                    RuntimeUnlockRetryDispatchInstallStatus.Installed,
                    "installed",
                    receipt),
                stagedUtcMs + 2);
        Assert.Equal(
            RuntimeUnlockRetryLifecycleTransitionStatus.Accepted,
            committed.Status);
        return new PersistentRetryInstallFixture(committed.State, receipt);
    }

    private static RuntimeUnlockRetryLifecycleTransitionDecision
        StagePersistentRetryLifecycle(
            FileTransferCoordinatorState state,
            RuntimeUnlockRetryDispatchDecision granted,
            long stagedUtcMs)
    {
        var stageResult =
            new RuntimeUnlockRetryDispatchDecisionStageResult(
                RuntimeUnlockRetryDispatchDecisionStageStatus.Staged,
                "staged",
                granted)
            {
                StageDisposition =
                    RuntimeUnlockRetryDispatchStageDisposition.Retained,
                StageCleared = false,
                StagedUtcMs = stagedUtcMs,
                StageExpiresUtcMs =
                    stagedUtcMs +
                    FileTransferCoordinator
                        .RuntimeUnlockRetryDispatchDeadlineMilliseconds,
            };
        return FileTransferCoordinator.ObserveRuntimeUnlockRetryDispatchStage(
            state,
            stageResult,
            stagedUtcMs);
    }

    private static RuntimeUnlockRetryLifecycleDeadlineDecision
        SettlePersistentRetryMissingDispatch(
            FileTransferCoordinatorState state,
            FileTransferAuthorityId authorityId,
            long offerGeneration,
            string offerNonce)
    {
        var aliasBound =
            FileTransferCoordinator.ObserveRuntimeUnlockRetryDispatchExecutionState(
                state,
                FileTransferCoordinator.GetRuntimeUnlockRetryLifecycle(state)
                    .InstalledAttempt!.Value.InstallReceipt!.Value,
                RuntimeUnlockRetryDispatchAttemptPhase.AliasBound,
                offerGeneration,
                offerNonce,
                dispatchObserved: false);
        Assert.True(aliasBound.Accepted);
        var sending =
            FileTransferCoordinator.ObserveRuntimeUnlockRetryDispatchExecutionState(
                aliasBound.State,
                FileTransferCoordinator.GetRuntimeUnlockRetryLifecycle(aliasBound.State)
                    .InstalledAttempt!.Value.InstallReceipt!.Value,
                RuntimeUnlockRetryDispatchAttemptPhase.SendInFlight,
                offerGeneration,
                offerNonce,
                dispatchObserved: false);
        Assert.True(sending.Accepted);
        var deadline = FileTransferCoordinator.GetRuntimeUnlockRetryLifecycle(
                sending.State)
            .InstalledAttempt!.Value.DispatchDeadlineUtcMs;
        var elapsed =
            FileTransferCoordinator.EvaluateRuntimeUnlockRetryDispatchDeadline(
                sending.State,
                authorityId,
                deadline);
        Assert.True(elapsed.SettlementIssued);
        return elapsed;
    }

    private static (
        FileTransferCoordinatorState State,
        RuntimeUnlockRetryDispatchAuthorityRequest Request,
        RepairReplayDecision Release) AuthorizeRegularRuntimeUnlockRetryDispatchSource(
            long retiredOfferGeneration = 17,
            string? coordinatorInstanceId = null)
    {
        var regular = FileTransferRouteResolver.Resolve(FileTransferRoute.RegularNknV4Fast);
        var state = StartRegular(regular).State;
        var owner = state.CurrentRuntimeOwner!.Value;
        var leg = state.CurrentLeg!;
        var publicationDecision = FileTransferCoordinator.AuthorizeAction(
            state,
            new FileTransferCoordinatorActionRequest(
                FileTransferCoordinatorActionKind.RoutePublication,
                Source: "test",
                Reason: "regular_v4_retry_publication",
                RuntimeOwner: owner,
                Route: regular.Route,
                ProtocolVersion: regular.ProtocolVersion,
                LiveRouteEpoch: leg.LiveRouteEpochId,
                LegGeneration: leg.Generation,
                RuntimeGeneration: owner.RuntimeGeneration,
                TerminalGeneration: state.TerminalGeneration,
                TargetRoute: FileTransferRoute.RegularNknV4Fast,
                TargetProtocolVersion: FileTransferProtocol.ProtocolVersionV4,
                TargetTransport: FileTransferTransportKind.RegularNkn));
        Assert.True(publicationDecision.Accepted);
        var repairDecision = FileTransferCoordinator.AuthorizeAction(
            publicationDecision.State,
            RecoveryActionRequest(
                FileTransferCoordinatorActionKind.RepairReplay,
                owner,
                publicationDecision.State.CurrentLeg!,
                repairReplayKind: RepairReplayKind.V4Repair));
        Assert.True(repairDecision.Accepted);
        var release = repairDecision.RepairReplayDecision!.Value;
        var publication = repairDecision.State.CurrentRoutePublicationToken!.Value;
        var publicPublication = new FileTransferRoutePublicationAuthority(
            publication.SessionId,
            publication.TransferId,
            publication.Direction,
            publication.RouteToken,
            publication.ProtocolVersion,
            publication.LiveRouteEpoch,
            publication.RuntimeGeneration,
            publication.TerminalGeneration,
            publication.LegGeneration,
            publication.PublicationGeneration,
            publication.RouteCommitGeneration,
            FileTransferRouteResolver.Resolve(publication.TargetRoute).TelemetryToken,
            publication.TargetProtocolVersion,
            publication.TargetTransport,
            publication.ActionKind.ToString(),
            publication.Reason);
        var request = new RuntimeUnlockRetryDispatchAuthorityRequest(
            repairDecision.State.SessionId,
            repairDecision.State.TransferId,
            repairDecision.State.Direction,
            publicPublication,
            RecoveryContractGeneration: 41,
            RetiredOfferGeneration: retiredOfferGeneration,
            DispatchAttemptGeneration: 1,
            RetryReason: "runtime_unlock_offer_send_not_observed",
            RecoveryReason: "regular_v4_repair_settled",
            RegularV4LivenessGeneration: 0,
            BridgeDecisionGeneration: release.BridgeDecisionGeneration);
        var releasedState = CommitRegularV4RepairSettlementRelease(
            repairDecision.State,
            release,
            FileTransferRegularV4FrontierRepairSettlementOutcome
                .ProgressObserved);
        if (!string.IsNullOrWhiteSpace(coordinatorInstanceId))
        {
            releasedState = releasedState with
            {
                PersistentState = releasedState.PersistentState with
                {
                    CoordinatorInstanceId = coordinatorInstanceId,
                    SnapshotStateGeneration = 0,
                },
            };
        }
        return (
            releasedState,
            request,
            release);
    }

    private static FileTransferCoordinatorState
        CommitRegularV4RepairSettlementRelease(
            FileTransferCoordinatorState state,
            RepairReplayDecision release,
            FileTransferRegularV4FrontierRepairSettlementOutcome outcome)
    {
        var pressureStage =
            FileTransferCoordinator.StageRegularV4FrontierRepairPressureBinding(
                state,
                release,
                new RegularV4FrontierRepairAuthorityRequest(
                    "regular-v4-frontier:0:test",
                    FrontierChunkIndex: 0,
                    DurableReceivedHighestChunkIndex: -1,
                    PendingRepairCount: 1,
                    DecisionReason: "regular_v4_repair_settled",
                    FrontierLagChunks: 1),
                "regular_v4_receiver_frontier_repair_due");
        var pressureBinding =
            Assert.IsType<RegularV4FrontierRepairPressureBinding>(
                pressureStage.Binding);
        var pressureInstalled =
            FileTransferCoordinator.CommitRegularV4FrontierRepairPressureBinding(
                pressureStage.State,
                new FileTransferRegularV4FrontierRepairPressureInstallReceipt(
                    pressureBinding.Authority,
                    FileTransferRegularV4FrontierRepairPressureInstallStatus
                        .Installed,
                    "installed",
                    pressureBinding.InstallGeneration,
                    pressureBinding.PressureReason));
        Assert.Equal(
            RegularV4FrontierRepairPressureBindingDecisionStatus.Accepted,
            pressureInstalled.Status);
        var settlement = RegularV4PressureSettlement(
            pressureBinding.Authority,
            outcome);
        var preparedSettlement =
            FileTransferCoordinator
                .PrepareRegularV4FrontierRepairPressureSettlement(
                    pressureInstalled.State,
                    settlement);
        var settlementCommand =
            Assert.IsType<
                FileTransferRegularV4FrontierRepairPressureSettlementCommand>(
                preparedSettlement.SettlementCommand);
        var settlementCommitted =
            FileTransferCoordinator
                .CommitRegularV4FrontierRepairPressureSettlement(
                    pressureInstalled.State,
                    new FileTransferRegularV4FrontierRepairPressureSettlementApplyReceipt(
                        settlementCommand,
                        FileTransferRegularV4FrontierRepairPressureSettlementApplyStatus
                            .Applied,
                        "applied",
                        CurrentAuthorityCleared: true,
                        RetainedPredecessorCleared: false));
        Assert.Equal(
            RegularV4FrontierRepairPressureBindingDecisionStatus.Accepted,
            settlementCommitted.Status);
        var repairSettlementRelease =
            FileTransferCoordinator.GetRuntimeUnlockRetryLifecycle(
                    settlementCommitted.State)
                .RepairSettlementRelease;
        Assert.NotNull(repairSettlementRelease);
        Assert.Equal(
            RuntimeUnlockRetryLifecycleRepairSettlementReleaseState.Available,
            repairSettlementRelease.Value.State);
        Assert.Equal(settlement, repairSettlementRelease.Value.Settlement);
        return settlementCommitted.State;
    }

    private static (
        FileTransferCoordinatorState State,
        RuntimeUnlockRetryDispatchAuthorityRequest Request,
        FallbackTailYieldDecision TailYield) AuthorizeFallbackRuntimeUnlockRetryDispatchSource(
            FileTransferCoordinatorState? sourceState = null)
    {
        var fallback = FileTransferRouteResolver.Resolve(FileTransferRoute.PostTunaFallbackV6);
        var state = sourceState ?? ActiveFallbackStateWithoutCheckpoint();
        var owner = state.CurrentRuntimeOwner!.Value;
        var leg = state.CurrentLeg!;
        var publication = FileTransferCoordinator.AuthorizeAction(
            state,
            new FileTransferCoordinatorActionRequest(
                FileTransferCoordinatorActionKind.RoutePublication,
                Source: "test",
                Reason: "fallback_retry_publication",
                RuntimeOwner: owner,
                Route: fallback.Route,
                ProtocolVersion: fallback.ProtocolVersion,
                LiveRouteEpoch: leg.LiveRouteEpochId,
                LegGeneration: leg.Generation,
                RuntimeGeneration: owner.RuntimeGeneration,
                TerminalGeneration: state.TerminalGeneration,
                TargetRoute: fallback.Route,
                TargetProtocolVersion: fallback.ProtocolVersion,
                TargetTransport: FileTransferTransportKind.RegularNkn));
        Assert.True(publication.Accepted);

        state = publication.State with
        {
            CurrentDataSessionIdentity = "fallback-retry-data-session",
            CurrentDataSessionGeneration = Math.Max(
                1,
                publication.State.CurrentDataSessionGeneration + 1),
        };
        var yielded = FileTransferCoordinator.Apply(
            CoordinatorEvent(
                FileTransferCoordinatorEventKind.FallbackTailQuiescent,
                fallback,
                reason: "fallback_tail_quiescent",
                state: FileTransferLegState.Active,
                canSendData: true,
                committedChunk: Math.Max(0, leg.ProvenCommittedChunkIndex),
                highestObservedChunk: leg.ProvenHighestObservedChunkIndex,
                transportEpoch: leg.TransportEpochId,
                bridgeRecoveryGeneration: leg.BridgeRecoveryGeneration),
            state);
        Assert.Null(yielded.MutationRejectedReason);
        var tailYield = Assert.IsType<FallbackTailYieldDecision>(yielded.FallbackTailYieldDecision);
        var localReceipt =
            FileTransferCoordinator.CreateFallbackTailLocalProofReceipt(
                yielded.State,
                tailYield,
                "fallback-retry-local-proof",
                "fallback-retry-local-frame",
                20_000);
        var localApplied =
            FileTransferCoordinator.ApplyFallbackTailLocalProofReceipt(
                yielded.State,
                localReceipt);
        Assert.True(localApplied.Accepted, localApplied.Reason);
        var peerReceipt =
            FileTransferCoordinator.CreateFallbackTailPeerProofReceipt(
                localApplied.State,
                CreateCoordinatorFallbackTailPeerProof(
                    localApplied.State,
                    tailYield),
                "fallback-retry-peer-proof",
                20_001);
        var paired =
            FileTransferCoordinator.ApplyFallbackTailPeerProofReceipt(
                localApplied.State,
                peerReceipt);
        Assert.True(paired.Accepted, paired.Reason);
        var pairedRelease =
            Assert.IsType<FileTransferFallbackTailPairedReleaseReceipt>(
                paired.PairedRelease);
        Assert.True(
            FileTransferCoordinator
                .TryCreateFallbackPairedTailYieldRuntimeUnlockRetryDispatchRequest(
                    paired.State,
                    pairedRelease,
                    "runtime_unlock_offer_send_not_observed",
                    "post_tuna_fallback_tail_unblocked",
                    out var request,
                    out var requestRejectionReason),
            requestRejectionReason);
        Assert.Equal(
            request,
            FileTransferCoordinator.GetFallbackTailYieldSubstate(
                    paired.State)
                .PendingRetryRecheckRequest);
        return (paired.State, request, tailYield);
    }

    private static FallbackPairedTailYieldReleaseEvidence
        CreateFallbackPairedTailYieldReleaseEvidence(
            FileTransferCoordinatorState state,
            FallbackTailYieldDecision tailYield)
    {
        var leg = Assert.IsType<FileTransferLeg>(state.CurrentLeg);
        const string peerAuthority =
            "fta2-fallback_tail_yield-0123456789abcdef01234567";
        var peerOwnerKey = FileTransferCoordinator.BuildFallbackTailYieldOwnerKey(
            state.SessionId,
            state.TransferId,
            state.RouteSelection.TelemetryToken,
            state.RouteSelection.ProtocolVersion,
            tailYield.CurrentLiveRouteEpoch,
            leg.Generation,
            leg.BridgeRecoveryGeneration,
            leg.TransportEpochId,
            tailYield.CheckpointRequestIdSnapshot);
        return new FallbackPairedTailYieldReleaseEvidence(
            tailYield,
            new FileTransferAuthorityId(peerAuthority),
            PeerPredecessorAuthorityId: null,
            PeerYieldGeneration: 1,
            state.Direction == FileTransferDirection.Outbound
                ? FileTransferDirection.Inbound.ToString().ToLowerInvariant()
                : FileTransferDirection.Outbound.ToString().ToLowerInvariant(),
            peerOwnerKey,
            tailYield.PairKey,
            tailYield.CurrentLiveRouteEpoch,
            leg.Generation,
            leg.BridgeRecoveryGeneration,
            leg.TransportEpochId,
            tailYield.CheckpointRequestIdSnapshot);
    }

    private static FileTransferFallbackTailPeerProof
        CreateCoordinatorFallbackTailPeerProof(
            FileTransferCoordinatorState state,
            FallbackTailYieldDecision tailYield)
    {
        var leg = Assert.IsType<FileTransferLeg>(state.CurrentLeg);
        return new FileTransferFallbackTailPeerProof(
            state.SessionId,
            state.TransferId,
            state.Direction == FileTransferDirection.Outbound
                ? FileTransferDirection.Inbound
                : FileTransferDirection.Outbound,
            new FileTransferAuthorityId(
                "fta2-fallback_tail_yield-89abcdef0123456789abcdef"),
            PredecessorAuthorityId: null,
            YieldGeneration: 1,
            FileTransferCoordinator.BuildFallbackTailYieldOwnerKey(
                state.SessionId,
                state.TransferId,
                state.RouteSelection.TelemetryToken,
                state.RouteSelection.ProtocolVersion,
                tailYield.CurrentLiveRouteEpoch,
                leg.Generation,
                leg.BridgeRecoveryGeneration,
                leg.TransportEpochId,
                tailYield.CheckpointRequestIdSnapshot),
            tailYield.PairKey,
            tailYield.CurrentLiveRouteEpoch,
            leg.Generation,
            leg.BridgeRecoveryGeneration,
            leg.TransportEpochId,
            tailYield.CheckpointRequestIdSnapshot,
            CommittedChunkIndex: 5,
            HighestObservedChunkIndex: 5,
            "peer-frame-fingerprint");
    }

    private static RegularV4FrontierRepairPressureSubstate PressureState(
